INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#11','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C4',3,'mc','auto','0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨56/100⟩ ÷ ⟨16/100⟩","correct":true},{"t":"⟨56/100⟩ ÷ 0.16","mis":"M6-2-u3-X06"},{"t":"⟨56/100⟩ ÷ ⟨16/10⟩","mis":"M6-2-u3-X05"},{"t":"0.56 ÷ ⟨16/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.56은 ⟨56/100⟩, 0.16은 ⟨16/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨56/100⟩ ÷ ⟨16/100⟩이에요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨14/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."]},{"stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#12','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',1,'mc','auto','9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"960","correct":true},{"t":"96","mis":"M6-2-u3-X07"},{"t":"9.60","mis":"M6-2-u3-X07"},{"t":"9600","mis":"M6-2-u3-X02"}],"explanation":["9.6의 소수점을 한 칸 옮기면 96이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 960이 돼요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4의 소수점을 한 칸 옮기면 54예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 540이 돼요."]},{"stem":"8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4의 소수점을 한 칸 옮기면 84예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 840이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#13','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',2,'sa','auto','6.3 ÷ 0.42의 몫은 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 0.45의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."]},{"stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#14','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',4,'mc','auto','□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":14,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.55","correct":true},{"t":"0.255","mis":"M6-2-u3-X03"},{"t":"25.5","mis":"M6-2-u3-X04"},{"t":"255","mis":"M6-2-u3-X02"}],"explanation":["□ = 1.7 × 1.5예요.","1.7 × 1.5 = 2.55예요.","2.55 ÷ 1.5 = 1.7로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M6-2-u3-X03"},{"t":"54","mis":"M6-2-u3-X04"},{"t":"540","mis":"M6-2-u3-X02"}],"explanation":["□ = 12 × 0.45예요.","12 × 0.45 = 5.4예요.","5.4 ÷ 0.45 = 12로 맞아요."]},{"stem":"□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.64","correct":true},{"t":"0.864","mis":"M6-2-u3-X03"},{"t":"86.4","mis":"M6-2-u3-X04"},{"t":"864","mis":"M6-2-u3-X02"}],"explanation":["□ = 3.6 × 2.4예요.","3.6 × 2.4 = 8.64예요.","8.64 ÷ 2.4 = 3.6으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#15','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"2.55 ÷ 0.15","correct":true},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"25.5 ÷ 15","mis":"M6-2-u3-X19"},{"t":"255 ÷ 150","mis":"M6-2-u3-X19"}],"explanation":["2.55 ÷ 1.5, 25.5 ÷ 15, 255 ÷ 150은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 1.7이에요.","2.55 ÷ 0.15는 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"8.64 ÷ 0.24","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"86.4 ÷ 24","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240","mis":"M6-2-u3-X19"}],"explanation":["8.64 ÷ 2.4, 86.4 ÷ 24, 864 ÷ 240은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.6이에요.","8.64 ÷ 0.24는 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#16','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',1,'sa','auto','18 ÷ 3.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."],"variant_rule":{"alt":[{"stem":"8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."]},{"stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["나누어지는 수 16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#17','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',2,'mc','auto','2 ÷ 0.8의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"2 ÷ 0.8의 몫은 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"0.25","mis":"M6-2-u3-X03"},{"t":"25","mis":"M6-2-u3-X04"},{"t":"0.025","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 2는 2.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","2 ÷ 0.8은 20 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.5예요."],"variant_rule":{"alt":[{"stem":"5 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"12.5","correct":true},{"t":"1.25","mis":"M6-2-u3-X03"},{"t":"125","mis":"M6-2-u3-X04"},{"t":"0.125","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 5는 5.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","5 ÷ 0.4는 50 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 12.5예요."]},{"stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#18','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',3,'ox','auto','12 ÷ 0.8의 몫은 12보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":18,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"12 ÷ 0.8의 몫은 12보다 작아요.","answer":"X","reason_options":[{"t":"0.8은 1보다 작아서 12 안에 12번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["12 ÷ 0.8 = 15예요.","15는 12보다 커요.","1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["16 ÷ 0.25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]},{"stem":"31 ÷ 0.62의 몫은 31보다 작아요.","answer":"X","reason_options":[{"t":"0.62는 1보다 작아서 31 안에 31번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["31 ÷ 0.62 = 50이에요.","50은 31보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#19','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',4,'mc','auto','수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"2.59","correct":true},{"t":"9.52","mis":"M6-2-u3-X09"},{"t":"5.29","mis":"M6-2-u3-X09"},{"t":"2.95","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 2.59예요.","그래서 □는 2.59예요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X09"},{"t":"5.26","mis":"M6-2-u3-X09"},{"t":"6.25","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","그래서 □는 6.52예요."]},{"stem":"수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"3.47","correct":true},{"t":"7.43","mis":"M6-2-u3-X09"},{"t":"4.37","mis":"M6-2-u3-X09"},{"t":"3.74","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 3.47이에요.","그래서 □는 3.47이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#20','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',1,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":20,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."],"variant_rule":{"alt":[{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."]},{"stem":"2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.29","correct":true},{"t":"0.28","mis":"M6-2-u3-X11"},{"t":"0.286","mis":"M6-2-u3-X12"},{"t":"0.3","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#21','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#22','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',3,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["3.38 ÷ 0.9 = 3.755…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 3.8이에요."],"variant_rule":{"alt":[{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 0.17이에요."]},{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#23','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#24','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#25','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.8 = 5.66…이므로 5명에게 나누어 줄 수 있다. 나누어 준 주스는 1.8 × 5 = 9 L이고 남는 주스는 10.2 − 9 = 1.2 L이다. 몫을 반올림해 6명으로 하면 10.8 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["5명을 구했는가","남는 주스 1.2 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["10.2 ÷ 1.8 = 5.66… — 5명이에요.","남는 양은 10.2 − 9 = 1.2 (L)예요.","6명이면 10.8 L가 필요해 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C1','math',6,2,'u4',2,'비의 성질 — 비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 같은 수로 나누어도 비율은 같음을 알고(같은 수를 더하는 것은 성질이 아님), 전항·후항·비율을 바르게 읽기',ARRAY['6수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C2','math',6,2,'u4',3,'자연수의 비를 간단한 자연수의 비로 나타내기 — 두 항의 공약수로 더 나눌 수 없을 때까지(최대공약수로) 나누기',ARRAY['6수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C3','math',6,2,'u4',3,'소수의 비를 간단한 자연수의 비로 나타내기 — 두 항이 모두 자연수가 되도록 10·100을 곱한 뒤 공약수로 나누기',ARRAY['6수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C4','math',6,2,'u4',3,'분수의 비와 소수·분수가 섞인 비를 간단한 자연수의 비로 나타내기 — 두 분모의 공배수를 곱하거나, 한쪽을 소수(분수)로 바꾸어 같은 꼴로 만든 뒤 나타내기',ARRAY['6수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C5','math',6,2,'u4',4,'비례식과 외항·내항 — 비율이 같은 두 비를 등호로 이은 식을 비례식이라 하고, 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라 하며, 비례식인지는 수의 모양이 아니라 비율로 판단하기',ARRAY['6수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C6','math',6,2,'u4',5,'비례식의 성질 — 비례식에서 외항의 곱과 내항의 곱이 같음을 알고, 이를 이용하여 □가 있는 비례식을 풀거나 비례식인지 확인하기',ARRAY['6수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C7','math',6,2,'u4',6,'비례식을 세워 생활 문제 해결하기 — 함께 같은 비율로 변하는 두 양에서 구하려는 것을 □로 두고 대응이 맞게 비례식을 세운 뒤 비례식의 성질이나 비의 성질로 풀기',ARRAY['6수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C8','math',6,2,'u4',7,'비례배분 — 전체를 가：나로 배분할 때 전체를 (가+나)칸으로 갈라 전체 × (가 ÷ (가+나)), 전체 × (나 ÷ (가+나))로 구하기',ARRAY['6수04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C9','math',6,2,'u4',8,'비례배분 활용 — 먼저 전체에서 우리 몫을 비례배분한 뒤 그 몫을 다시 정한 기준(낸 금액·만든 수 등)의 비로 나누고, 기준에 따라 몫이 달라짐을 알기',ARRAY['6수04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X01','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C5']::text[],'전항과 후항에 같은 수를 더하거나 빼도 비율이 같다고 본다(2：3에 2를 더해 4：5)','더하기는 비의 성질이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X02','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'전항과 후항 가운데 한 항에만 곱하거나 한 항만 나눈다','두 항을 똑같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X03','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5']::text[],'전항과 후항(비교하는 양과 기준량)을 바꾸어 쓰거나 비율의 기준량을 잘못 잡는다','「무엇에 대한」 쪽이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X04','math',6,'u4',ARRAY['M6-2-u4-C1']::text[],'전항과 후항에 0을 곱하거나 0으로 나누어도 된다고 본다','0이 아닌 같은 수만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X05','math',6,'u4',ARRAY['M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'공약수로 끝까지 나누지 않아 가장 간단한 자연수의 비가 아닌 채로 멈춘다','더 나눌 공약수가 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X06','math',6,'u4',ARRAY['M6-2-u4-C3','M6-2-u4-C4']::text[],'소수의 비에서 곱하는 수를 잘못 정해(한 자리 수에만 맞춰 10만 곱하는 등) 자연수가 되지 않거나 비가 달라진다','두 항이 모두 자연수가 되도록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X07','math',6,'u4',ARRAY['M6-2-u4-C4']::text[],'분수의 비에서 분모끼리 또는 분자끼리만 떼어 비로 쓴다(⟨1/5⟩：⟨1/7⟩을 5：7이나 1：1로)','두 분모의 공배수를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X09','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'두 비의 수 모양만 보고(같은 수가 들어 있으면) 비례식이라고 판단한다(7：4 = 4：7)','비율을 견주어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X10','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'외항과 내항을 바꾸어 안다(안쪽 두 수를 외항으로)','바깥 둘이 외항') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X11','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱한다','바깥끼리, 안쪽끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X12','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항의 곱과 내항의 곱을 같게 놓은 뒤 □를 구하지 않고 곱한 값을 답으로 쓰거나 나눗셈을 잘못한다','곱 ÷ 아는 수 = □') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X13','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'비례식을 세울 때 대응을 어긋나게 놓는다(2：8000 = 40000：★처럼 무게와 값의 자리를 바꿈)','같은 종류끼리 같은 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X14','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'두 양이 같은 비율로 변하는지 보지 않고 차이(더하기·빼기)로 늘린다','몇 배가 되었는지 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X15','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 전체를 비의 한 항(가 또는 나)으로 나눈다(1200을 2：3으로 → 1200 ÷ 2)','한 묶음은 (가+나)칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X16','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 (가 ÷ (가+나)) 대신 (가 ÷ 나)를 곱하거나 한 칸의 양을 답으로 쓴다','분모는 가+나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X17','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분한 두 몫 가운데 다른 쪽의 몫을 답으로 쓴다','누구의 몫을 묻나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X18','math',6,'u4',ARRAY['M6-2-u4-C9']::text[],'두 번 나누어야 할 때 첫 단계(전체에서 우리 몫)를 건너뛰고 전체를 바로 나눈다','먼저 우리 몫부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X19','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'묻는 말을 거꾸로 읽는다 — 알맞은↔알맞지 않은, 외항↔내항, 큰↔작은','물음의 「않은·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X20','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'곱셈·나눗셈·약분 계산을 잘못한다','거꾸로 곱해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#1','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','비 3：4에서 후항은 어느 수인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"비 3：4에서 후항은 어느 수인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M6-2-u4-X03"},{"t":"7","mis":"M6-2-u4-X20"},{"t":"12","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","3：4에서 전항은 3, 후항은 4예요.","그래서 후항은 4예요."],"variant_rule":{"alt":[{"stem":"비 5：8에서 전항은 어느 수인가요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M6-2-u4-X03"},{"t":"13","mis":"M6-2-u4-X20"},{"t":"40","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 전항은 5예요."]},{"stem":"비 7：2에서 후항은 어느 수인가요?","options":[{"t":"2","correct":true},{"t":"7","mis":"M6-2-u4-X03"},{"t":"9","mis":"M6-2-u4-X20"},{"t":"14","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","7：2에서 전항은 7, 후항은 2예요.","그래서 후항은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#2','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?',ARRAY['M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨7/2⟩","mis":"M6-2-u4-X03"},{"t":"⟨2/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨7/9⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","2：7에서 비교하는 양은 2, 기준량은 7이에요.","비율은 2 ÷ 7 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"학생 8명 중에서 우산을 가져온 학생은 3명이에요. 전체 학생 수에 대한 우산을 가져온 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨8/3⟩","mis":"M6-2-u4-X03"},{"t":"⟨3/11⟩","mis":"M6-2-u4-X03"},{"t":"⟨8/11⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","3：8에서 비교하는 양은 3, 기준량은 8이에요.","비율은 3 ÷ 8 = ⟨3/8⟩이에요."]},{"stem":"학생 9명 중에서 자전거를 타는 학생은 4명이에요. 전체 학생 수에 대한 자전거를 타는 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨9/4⟩","mis":"M6-2-u4-X03"},{"t":"⟨4/13⟩","mis":"M6-2-u4-X03"},{"t":"⟨9/13⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","4：9에서 비교하는 양은 4, 기준량은 9예요.","비율은 4 ÷ 9 = ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#3','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"3：4의 전항과 후항에 똑같이 6을 곱했어요. 18：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 6을 곱해 18이 되었으니 후항 4에도 6을 곱해요.","4 × 6 = 24 — 18：24예요."]},{"stem":"2：3의 전항과 후항에 똑같이 7을 곱했어요. 14：□에서 □에 알맞은 수는 얼마인가요?","answer":["21"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 2에 7을 곱해 14가 되었으니 후항 3에도 7을 곱해요.","3 × 7 = 21 — 14：21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#4','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."],"variant_rule":{"alt":[{"stem":"12：20의 전항과 후항을 똑같이 4로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 12를 4로 나누면 3이에요.","후항도 20 ÷ 4 = 5 — 3：5예요."]},{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#5','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["2"],"explanation":["2：1에서 앞의 수 2가 4가 되었으니 2배예요.","비율이 같으려면 뒤의 수도 똑같이 2배 해야 해요.","1 × 2 = 2예요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["2：1에서 앞의 수 2가 6이 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]},{"stem":"비눗방울 용액과 물을 3：1로 섞어요. 용액을 9컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["3：1에서 앞의 수 3이 9가 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#6','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','2：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#7','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','14：10과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"14：10과 비율이 같은 비는 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"12：8","mis":"M6-2-u4-X01"},{"t":"5：7","mis":"M6-2-u4-X03"},{"t":"7：10","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","14：10의 두 항을 똑같이 2로 나누면 7：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"12：20과 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"8：16","mis":"M6-2-u4-X01"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","12：20의 두 항을 똑같이 4로 나누면 3：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]},{"stem":"18：12와 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"12：6","mis":"M6-2-u4-X01"},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：12","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","18：12의 두 항을 똑같이 6으로 나누면 3：2예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#8','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["21"],"explanation":["2：3에서 앞의 수 2가 14가 되었으니 7배예요.","비율이 같으려면 뒤의 수도 똑같이 7배 해야 해요.","3 × 7 = 21이에요."],"variant_rule":{"alt":[{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 10장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["15"],"explanation":["2：3에서 앞의 수 2가 10이 되었으니 5배예요.","비율이 같으려면 뒤의 수도 똑같이 5배 해야 해요.","3 × 5 = 15예요."]},{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 16장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["24"],"explanation":["2：3에서 앞의 수 2가 16이 되었으니 8배예요.","비율이 같으려면 뒤의 수도 똑같이 8배 해야 해요.","3 × 8 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#9','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 2를 더해 8：6을 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 12：8을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항을 2로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 18：12를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","12：8, 3：2, 18：12는 모두 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"9：6과 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에서 3을 빼서 6：3을 구한다","correct":true},{"t":"전항과 후항을 3으로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 2를 곱해 18：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 4를 곱해 36：24를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","3：2, 18：12, 36：24는 모두 비율이 ⟨3/2⟩이에요.","6：3은 비율이 2 — 같은 수를 빼는 것은 비의 성질이 아니에요."]},{"stem":"10：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 5를 더해 15：9를 구한다","correct":true},{"t":"전항과 후항을 2로 나누어 5：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 30：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 10을 곱해 100：40을 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","5：2, 30：12, 100：40은 모두 비율이 ⟨5/2⟩예요.","15：9는 비율이 ⟨5/3⟩ — 더하기는 비의 성질이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#10','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',3,'ox','auto','2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.',ARRAY['M6-2-u4-X04']::text[],true,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"mis":"M6-2-u4-X04","explanation":["비의 성질은 0이 아닌 같은 수를 곱할 때만 써요.","2：3에 0을 곱하면 0：0이 돼요.","0：0은 비율을 나타낼 수 없어요."],"variant_rule":{"alt":[{"stem":"6：9의 전항과 후항을 똑같이 0으로 나누어도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"어떤 수도 0으로는 나눌 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["비의 성질은 0이 아닌 같은 수로 나눌 때만 써요.","0으로 나누는 계산은 할 수 없어요.","그래서 6：9를 0으로 나눌 수 없어요."]},{"stem":"4：5의 전항과 후항에 0이 아닌 같은 수를 곱해야 비율이 그대로예요.","answer":"O","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["4：5에 3을 곱한 12：15는 비율이 ⟨4/5⟩로 같아요.","0을 곱하면 0：0이 돼요.","그래서 「0이 아닌」 같은 수라는 조건이 붙어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#1','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'sa','auto','4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."],"variant_rule":{"alt":[{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]},{"stem":"8：3의 전항과 후항에 똑같이 5를 곱했어요. 40：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 8에 5를 곱해 40이 되었으니 후항 3에도 5를 곱해요.","3 × 5 = 15 — 40：15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#2','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'mc','auto','24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?',ARRAY['M6-2-u4-X02','M6-2-u4-X01','M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?","options":[{"t":"2：3","correct":true},{"t":"2：36","mis":"M6-2-u4-X02"},{"t":"12：24","mis":"M6-2-u4-X01"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 12로 나누어요.","24 ÷ 12 = 2, 36 ÷ 12 = 3이에요.","그래서 2：3 — 비율은 그대로예요."],"variant_rule":{"alt":[{"stem":"28：21의 전항과 후항을 똑같이 7로 나누면 어떤 비가 되나요?","options":[{"t":"4：3","correct":true},{"t":"4：21","mis":"M6-2-u4-X02"},{"t":"21：14","mis":"M6-2-u4-X01"},{"t":"3：4","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 7로 나누어요.","28 ÷ 7 = 4, 21 ÷ 7 = 3이에요.","그래서 4：3 — 비율은 그대로예요."]},{"stem":"40：64의 전항과 후항을 똑같이 8로 나누면 어떤 비가 되나요?","options":[{"t":"5：8","correct":true},{"t":"5：64","mis":"M6-2-u4-X02"},{"t":"32：56","mis":"M6-2-u4-X01"},{"t":"8：5","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 8로 나누어요.","40 ÷ 8 = 5, 64 ÷ 8 = 8이에요.","그래서 5：8 — 비율은 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#3','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','화면의 가로와 세로의 비가 16：9예요. 이와 비율이 같은 화면은 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"화면의 가로와 세로의 비가 16：9예요. 이와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"가로 32 cm, 세로 18 cm","correct":true},{"t":"가로 20 cm, 세로 13 cm","mis":"M6-2-u4-X01"},{"t":"가로 18 cm, 세로 32 cm","mis":"M6-2-u4-X03"},{"t":"가로 32 cm, 세로 9 cm","mis":"M6-2-u4-X02"}],"explanation":["16：9에 같은 수를 곱한 비를 찾아요.","16：9의 두 항에 2를 곱하면 32：18이에요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."],"variant_rule":{"alt":[{"stem":"화면의 가로와 세로의 비가 4：3이에요. 이와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"가로 20 cm, 세로 15 cm","correct":true},{"t":"가로 6 cm, 세로 5 cm","mis":"M6-2-u4-X01"},{"t":"가로 15 cm, 세로 20 cm","mis":"M6-2-u4-X03"},{"t":"가로 20 cm, 세로 3 cm","mis":"M6-2-u4-X02"}],"explanation":["4：3에 같은 수를 곱한 비를 찾아요.","4：3의 두 항에 5를 곱하면 20：15예요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."]},{"stem":"사진의 가로와 세로의 비가 3：2예요. 이와 비율이 같은 사진은 어느 것인가요?","options":[{"t":"가로 12 cm, 세로 8 cm","correct":true},{"t":"가로 5 cm, 세로 4 cm","mis":"M6-2-u4-X01"},{"t":"가로 8 cm, 세로 12 cm","mis":"M6-2-u4-X03"},{"t":"가로 12 cm, 세로 2 cm","mis":"M6-2-u4-X02"}],"explanation":["3：2에 같은 수를 곱한 비를 찾아요.","3：2의 두 항에 4를 곱하면 12：8이에요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#4','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'error','auto','5：2와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"error","stem":"5：2와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 항에 3을 더한 8：5도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"나린 — 「두 항에 2를 곱한 10：4는 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"지호 — 「두 항에 4를 곱한 20：8도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"유진 — 「비율은 모두 ⟨5/2⟩야.」","mis":"M6-2-u4-X19"}],"explanation":["10：4와 20：8은 두 항에 같은 수를 곱해 비율이 ⟨5/2⟩예요.","8：5는 비율이 ⟨8/5⟩로 달라요.","같은 수를 더하는 것은 비의 성질이 아니에요 — 가온이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"12：8과 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「두 항에서 4를 뺀 8：4도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"하린 — 「두 항을 4로 나눈 3：2는 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"도윤 — 「두 항에 2를 곱한 24：16도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"민준 — 「비율은 모두 ⟨3/2⟩이야.」","mis":"M6-2-u4-X19"}],"explanation":["3：2와 24：16은 비율이 ⟨3/2⟩이에요.","8：4는 비율이 2로 달라요.","같은 수를 빼는 것은 비의 성질이 아니에요 — 수아가 잘못 말했어요."]},{"stem":"3：7과 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「두 항에 10을 더한 13：17도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"지호 — 「두 항에 10을 곱한 30：70은 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「두 항에 2를 곱한 6：14도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「비율은 모두 ⟨3/7⟩이야.」","mis":"M6-2-u4-X19"}],"explanation":["30：70과 6：14는 비율이 ⟨3/7⟩이에요.","13：17은 비율이 ⟨13/17⟩으로 달라요.","같은 수를 더하는 것은 비의 성질이 아니에요 — 서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#5','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 4개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X02','M6-2-u4-X03']::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 4개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"8：12","correct":true},{"t":"6：7","mis":"M6-2-u4-X01"},{"t":"8：3","mis":"M6-2-u4-X02"},{"t":"12：8","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 4개면 초록도 빨강도 4배가 돼요.","초록 8장, 빨강 12장 — 8：12예요.","비율은 여전히 ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 5개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"10：15","correct":true},{"t":"7：8","mis":"M6-2-u4-X01"},{"t":"10：3","mis":"M6-2-u4-X02"},{"t":"15：10","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 5개면 초록도 빨강도 5배가 돼요.","초록 10장, 빨강 15장 — 10：15예요.","비율은 여전히 ⟨2/3⟩예요."]},{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 3개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"6：9","correct":true},{"t":"5：6","mis":"M6-2-u4-X01"},{"t":"6：3","mis":"M6-2-u4-X02"},{"t":"9：6","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 3개면 초록도 빨강도 3배가 돼요.","초록 6장, 빨강 9장 — 6：9예요.","비율은 여전히 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#6','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'ox','auto','4：6과 6：9는 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"4：6과 6：9는 비율이 같아요.","answer":"O","reason_options":[{"t":"둘 다 2：3의 두 항에 같은 수(2와 3)를 곱한 비라서","correct":true},{"t":"4：6의 두 항에 2와 3을 더한 비가 6：9라서","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["4：6을 2로 나누면 2：3이에요.","6：9를 3으로 나누면 2：3이에요.","그래서 비율은 모두 ⟨2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"3：5와 5：7은 비율이 같아요.","answer":"X","reason_options":[{"t":"5：7은 3：5에 2를 더했을 뿐 같은 수를 곱한 비가 아니라서","correct":true},{"t":"두 항에 똑같이 2를 더했으니 비율이 같아서","mis":"M6-2-u4-X01"}],"explanation":["3：5의 비율은 ⟨3/5⟩이에요.","5：7의 비율은 ⟨5/7⟩예요.","같은 수를 더하면 비율이 달라져요."]},{"stem":"6：8과 9：12는 비율이 같아요.","answer":"O","reason_options":[{"t":"둘 다 3：4의 두 항에 같은 수(2와 3)를 곱한 비라서","correct":true},{"t":"6：8의 두 항에 3과 4를 더한 비가 9：12라서","mis":"M6-2-u4-X01"}],"explanation":["6：8을 2로 나누면 3：4예요.","9：12를 3으로 나누면 3：4예요.","그래서 비율은 모두 ⟨3/4⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#7','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'match','auto','비율이 같은 비끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":3,"kind":"match","stem":"비율이 같은 비끼리 이으세요.","pairs":[{"l":"2：3","r":"8：12"},{"l":"3：4","r":"9：12"},{"l":"5：2","r":"15：6"}],"mis":"M6-2-u4-X01","explanation":["2：3에 4를 곱하면 8：12예요.","3：4에 3을 곱하면 9：12예요.","5：2에 3을 곱하면 15：6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 같은 비끼리 이으세요.","pairs":[{"l":"4：5","r":"12：15"},{"l":"1：3","r":"5：15"},{"l":"7：2","r":"14：4"}],"explanation":["4：5에 3을 곱하면 12：15예요.","1：3에 5를 곱하면 5：15예요.","7：2에 2를 곱하면 14：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#8','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'mc','auto','비율이 ⟨3/4⟩이고 전항과 후항의 합이 28인 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":4,"kind":"mc","stem":"비율이 ⟨3/4⟩이고 전항과 후항의 합이 28인 비는 어느 것인가요?","options":[{"t":"12：16","correct":true},{"t":"16：12","mis":"M6-2-u4-X03"},{"t":"9：12","mis":"M6-2-u4-X20"},{"t":"3：25","mis":"M6-2-u4-X02"}],"explanation":["3：4의 두 항에 같은 수를 곱해도 비율은 ⟨3/4⟩이에요.","3 + 4 = 7이고 28은 7의 4배예요.","두 항에 4를 곱하면 12：16 — 합이 28이에요."],"variant_rule":{"alt":[{"stem":"비율이 ⟨2/5⟩이고 전항과 후항의 합이 35인 비는 어느 것인가요?","options":[{"t":"10：25","correct":true},{"t":"25：10","mis":"M6-2-u4-X03"},{"t":"8：20","mis":"M6-2-u4-X20"},{"t":"2：33","mis":"M6-2-u4-X02"}],"explanation":["2：5의 두 항에 같은 수를 곱해도 비율은 ⟨2/5⟩예요.","2 + 5 = 7이고 35는 7의 5배예요.","두 항에 5를 곱하면 10：25 — 합이 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#9','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','순달이는 비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 해도 진하기가 그대로인 까닭을 비의 성질로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"순달이는 비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 해도 진하기가 그대로인 까닭을 비의 성질로 설명해 보세요.","answer_guide":{"answer":"예: 용액 2컵과 물 1컵을 한 묶음으로 보면 용액 6컵은 3묶음이므로 물은 3컵이다. 2：1의 전항과 후항에 똑같이 3을 곱해 6：3이 되었고, 0이 아닌 같은 수를 곱하면 비율이 같으므로 진하기가 그대로이다.","scoring_points":["물 3컵을 구했는가","두 항에 똑같이 3을 곱했음을 밝혔는가","같은 수를 곱하면 비율이 같다는 까닭을 썼는가"]},"explanation":["용액 6컵은 2컵의 3배예요.","물도 1컵의 3배 — 3컵이에요.","6：3은 2：1과 비율이 같아 진하기가 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#10','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','6：4와 비율이 같은 비를 두 개 만들고, 친구가 만든 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"6：4와 비율이 같은 비를 두 개 만들고, 친구가 만든 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 6：4의 두 항에 2를 곱하면 12：8, 2로 나누면 3：2이다. 8：6은 두 항에 2를 더한 것인데, 같은 수를 더하는 것은 비의 성질이 아니므로 비율이 ⟨4/3⟩로 ⟨3/2⟩과 다르다.","scoring_points":["비율이 같은 비 두 개를 바르게 만들었는가","8：6은 같은 수를 더한 것임을 밝혔는가","두 비의 비율을 견주어 다름을 보였는가"]},"explanation":["12：8, 3：2는 비율이 ⟨3/2⟩이에요.","8：6은 2를 더한 비예요.","8：6의 비율은 ⟨4/3⟩ — 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#1','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',1,'mc','auto','28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":1,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#2','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'sa','auto','0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."],"variant_rule":{"alt":[{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]},{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#3','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'sa','auto','2.5：3의 전항과 후항에 똑같이 2를 곱했어요. 5：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"2.5：3의 전항과 후항에 똑같이 2를 곱했어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","2.5 × 2 = 5예요.","3 × 2 = 6 — 5：6이에요."],"variant_rule":{"alt":[{"stem":"1.5：2의 전항과 후항에 똑같이 2를 곱했어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","1.5 × 2 = 3이에요.","2 × 2 = 4 — 3：4예요."]},{"stem":"3.5：4의 전항과 후항에 똑같이 2를 곱했어요. 7：□에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","3.5 × 2 = 7이에요.","4 × 2 = 8 — 7：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#4','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',1,'sa','auto','45：18을 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C2","difficulty":1,"kind":"sa","stem":"45：18을 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["45와 18의 최대공약수는 9예요.","두 항을 똑같이 9로 나눠요.","18 ÷ 9 = 2 — 5：2예요."],"variant_rule":{"alt":[{"stem":"36：48을 간단한 자연수의 비로 나타내면 3：□예요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["36과 48의 최대공약수는 12예요.","두 항을 똑같이 12로 나눠요.","48 ÷ 12 = 4 — 3：4예요."]},{"stem":"35：14를 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["35와 14의 최대공약수는 7이에요.","두 항을 똑같이 7로 나눠요.","14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#5','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',2,'mc','auto','고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]},{"stem":"0.5：1.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"5：15","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"5：1.5","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 5：15예요.","5와 15의 최대공약수 5로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#6','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":6,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]},{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#7','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','민규는 책 전체의 ⟨1/5⟩, 세아는 ⟨1/7⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":7,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"민규는 책 전체의 ⟨1/5⟩, 세아는 ⟨1/7⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."],"variant_rule":{"alt":[{"stem":"하린이는 책 전체의 ⟨1/4⟩, 도윤이는 ⟨1/6⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/4⟩ × 12 = 3, ⟨1/6⟩ × 12 = 2예요.","그래서 가장 간단한 자연수의 비는 3：2예요."]},{"stem":"수아는 책 전체의 ⟨1/3⟩, 지호는 ⟨1/8⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：3","correct":true},{"t":"3：8","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"9：3","mis":"M6-2-u4-X20"}],"explanation":["두 분모 3과 8의 공배수 24를 전항과 후항에 똑같이 곱해요.","⟨1/3⟩ × 24 = 8, ⟨1/8⟩ × 24 = 3이에요.","그래서 가장 간단한 자연수의 비는 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#8','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":8,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."],"variant_rule":{"alt":[{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]},{"stem":"0.9：⟨3/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"9：3","mis":"M6-2-u4-X06"},{"t":"4：2","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨3/5⟩을 소수 0.6으로 바꾸면 0.9：0.6이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#9','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',2,'mc','auto','0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":9,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."],"variant_rule":{"alt":[{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]},{"stem":"1.25：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"125：50","mis":"M6-2-u4-X05"},{"t":"2：5","mis":"M6-2-u4-X03"},{"t":"12.5：5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 125：50이에요.","125와 50의 최대공약수 25로 나누면 5：2예요.","그래서 가장 간단한 자연수의 비는 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#10','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',3,'mc','auto','0.5：1.5에 10을 곱하면 5：15예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?',ARRAY['M6-2-u4-X06','M6-2-u4-X03']::text[],true,'{"seq":10,"concept":"M6-2-u4-C2","difficulty":3,"kind":"mc","stem":"0.5：1.5에 10을 곱하면 5：15예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"5와 15를 5로 더 나눌 수 있어서","correct":true},{"t":"5：15는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["5：15는 두 항이 모두 자연수예요.","그런데 5와 15는 공약수 5가 있어요.","5로 나누면 1：3 — 이것이 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"0.4：1.2에 10을 곱하면 4：12예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"4와 12를 4로 더 나눌 수 있어서","correct":true},{"t":"4：12는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["4：12는 두 항이 모두 자연수예요.","그런데 4와 12는 공약수 4가 있어요.","4로 나누면 1：3 — 이것이 가장 간단한 자연수의 비예요."]},{"stem":"0.6：0.9에 10을 곱하면 6：9예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"6과 9를 3으로 더 나눌 수 있어서","correct":true},{"t":"6：9는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["6：9는 두 항이 모두 자연수예요.","그런데 6과 9는 공약수 3이 있어요.","3으로 나누면 2：3 — 이것이 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#1','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C2',2,'mc','auto','84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":1,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#2','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',2,'mc','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：6","correct":true},{"t":"6：5","mis":"M6-2-u4-X03"},{"t":"1：3","mis":"M6-2-u4-X06"},{"t":"6：6","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨1/4⟩을 소수 0.25로 바꾸면 0.25：0.3이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 5：6이에요."]},{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#3','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'sa','auto','꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C4","difficulty":3,"kind":"sa","stem":"꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["8"],"explanation":["두 분모 40과 5의 공배수 40을 곱하면 3：24예요.","두 항을 3으로 나누면 1：8이에요.","그래서 □는 8이에요."],"variant_rule":{"alt":[{"stem":"소금 ⟨1/20⟩컵을 넣어 소금물 ⟨1/2⟩컵을 만들었어요. 넣은 소금의 양과 만든 소금물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["10"],"explanation":["두 분모 20과 2의 공배수 20을 곱하면 1：10이에요.","전항이 1이라 이미 가장 간단한 자연수의 비예요.","그래서 □는 10이에요."]},{"stem":"설탕 ⟨2/15⟩컵을 넣어 설탕물 ⟨2/3⟩컵을 만들었어요. 넣은 설탕의 양과 만든 설탕물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["5"],"explanation":["두 분모 15와 3의 공배수 15를 곱하면 2：10이에요.","두 항을 2로 나누면 1：5예요.","그래서 □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#4','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'error','auto','0.6：0.9를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C3","difficulty":3,"kind":"error","stem":"0.6：0.9를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「10을 곱한 6：9가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"도윤 — 「두 항에 10을 곱하면 6：9가 돼.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「6：9를 3으로 나누면 2：3이야.」","mis":"M6-2-u4-X19"},{"t":"지호 — 「가장 간단한 자연수의 비는 2：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["0.6：0.9에 10을 곱하면 6：9예요.","6과 9는 아직 공약수 3으로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 2：3 — 하린의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"0.4：1.2를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「10을 곱한 4：12가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"서아 — 「두 항에 10을 곱하면 4：12가 돼.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「4：12를 4로 나누면 1：3이야.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「가장 간단한 자연수의 비는 1：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["0.4：1.2에 10을 곱하면 4：12예요.","4와 12는 아직 공약수 4로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 1：3 — 민준의 말이 잘못되었어요."]},{"stem":"1.6：2.4를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「10을 곱한 16：24가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"하린 — 「두 항에 10을 곱하면 16：24가 돼.」","mis":"M6-2-u4-X19"},{"t":"도윤 — 「16：24를 8로 나누면 2：3이야.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「가장 간단한 자연수의 비는 2：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["1.6：2.4에 10을 곱하면 16：24예요.","16과 24는 아직 공약수 8로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 2：3 — 유진의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#5','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'mc','auto','고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 단백질량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C3","difficulty":3,"kind":"mc","stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 단백질량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량에 대한 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：3","correct":true},{"t":"56：21","mis":"M6-2-u4-X05"},{"t":"3：8","mis":"M6-2-u4-X03"},{"t":"56：2.1","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 56：21이에요.","56과 21의 최대공약수 7로 나누면 8：3이에요.","그래서 가장 간단한 자연수의 비는 8：3이에요."]},{"stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 탄수화물량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"95：28","correct":true},{"t":"190：56","mis":"M6-2-u4-X05"},{"t":"28：95","mis":"M6-2-u4-X03"},{"t":"190：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 190：56이에요.","190과 56의 최대공약수 2로 나누면 95：28이에요.","그래서 가장 간단한 자연수의 비는 95：28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#6','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C2',3,'mc','auto','간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":3,"kind":"mc","stem":"간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"⟨2/5⟩：⟨3/4⟩","correct":true},{"t":"1.2：1.8","mis":"M6-2-u4-X19"},{"t":"⟨1/3⟩：⟨1/2⟩","mis":"M6-2-u4-X19"},{"t":"10：15","mis":"M6-2-u4-X19"}],"explanation":["1.2：1.8, ⟨1/3⟩：⟨1/2⟩, 10：15를 간단히 하면 모두 2：3이에요.","⟨2/5⟩：⟨3/4⟩을 간단히 하면 8：15예요.","그래서 ⟨2/5⟩：⟨3/4⟩이 다른 하나예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"1.5：2.5","correct":true},{"t":"0.9：1.2","mis":"M6-2-u4-X19"},{"t":"⟨1/4⟩：⟨1/3⟩","mis":"M6-2-u4-X19"},{"t":"15：20","mis":"M6-2-u4-X19"}],"explanation":["0.9：1.2, ⟨1/4⟩：⟨1/3⟩, 15：20을 간단히 하면 모두 3：4예요.","1.5：2.5를 간단히 하면 3：5예요.","그래서 1.5：2.5가 다른 하나예요."]},{"stem":"이번에는 다른 보기예요. 간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"⟨1/2⟩：⟨1/5⟩","correct":true},{"t":"0.4：1","mis":"M6-2-u4-X19"},{"t":"⟨1/5⟩：⟨1/2⟩","mis":"M6-2-u4-X19"},{"t":"6：15","mis":"M6-2-u4-X19"}],"explanation":["0.4：1, ⟨1/5⟩：⟨1/2⟩, 6：15를 간단히 하면 모두 2：5예요.","⟨1/2⟩：⟨1/5⟩을 간단히 하면 5：2예요.","그래서 ⟨1/2⟩：⟨1/5⟩이 다른 하나예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#7','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'match','auto','비와 간단한 자연수의 비를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C4","difficulty":3,"kind":"match","stem":"비와 간단한 자연수의 비를 알맞게 이으세요.","pairs":[{"l":"0.3：0.5","r":"3：5"},{"l":"⟨1/2⟩：⟨1/3⟩","r":"3：2"},{"l":"24：32","r":"3：4"}],"mis":"M6-2-u4-X05","explanation":["0.3：0.5에 10을 곱하면 3：5예요.","⟨1/2⟩：⟨1/3⟩에 6을 곱하면 3：2예요.","24：32를 8로 나누면 3：4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비와 간단한 자연수의 비를 알맞게 이으세요.","pairs":[{"l":"0.7：0.2","r":"7：2"},{"l":"⟨1/4⟩：⟨1/5⟩","r":"5：4"},{"l":"18：45","r":"2：5"}],"explanation":["0.7：0.2에 10을 곱하면 7：2예요.","⟨1/4⟩：⟨1/5⟩에 20을 곱하면 5：4예요.","18：45를 9로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#8','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'mc','auto','어떤 비의 전항은 0.6이에요. 이 비를 간단한 자연수의 비로 나타내면 3：4예요. 후항은 얼마인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C4","difficulty":4,"kind":"mc","stem":"어떤 비의 전항은 0.6이에요. 이 비를 간단한 자연수의 비로 나타내면 3：4예요. 후항은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"4","mis":"M6-2-u4-X07"},{"t":"0.45","mis":"M6-2-u4-X03"},{"t":"8","mis":"M6-2-u4-X06"}],"explanation":["0.6：□의 비율은 3：4와 같아야 해요.","0.6은 3의 0.2배이니 □도 4의 0.2배예요.","□ = 0.8이에요."],"variant_rule":{"alt":[{"stem":"어떤 비의 전항은 1.2예요. 이 비를 간단한 자연수의 비로 나타내면 3：5예요. 후항은 얼마인가요?","options":[{"t":"2","correct":true},{"t":"5","mis":"M6-2-u4-X07"},{"t":"0.72","mis":"M6-2-u4-X03"},{"t":"20","mis":"M6-2-u4-X06"}],"explanation":["1.2：□의 비율은 3：5와 같아야 해요.","1.2는 3의 0.4배이니 □도 5의 0.4배예요.","□ = 2예요."]},{"stem":"어떤 비의 전항은 0.8이에요. 이 비를 간단한 자연수의 비로 나타내면 2：3이에요. 후항은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"3","mis":"M6-2-u4-X07"},{"t":"⟨8/15⟩","mis":"M6-2-u4-X03"},{"t":"12","mis":"M6-2-u4-X06"}],"explanation":["0.8：□의 비율은 2：3과 같아야 해요.","0.8은 2의 0.4배이니 □도 3의 0.4배예요.","□ = 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#9','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',4,'essay','teacher','해바라기씨 간식의 단백질은 2.1 g, 지방은 5.6 g이에요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내는 과정을 쓰고, 왜 먼저 10을 곱하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C3","difficulty":4,"kind":"essay","stem":"해바라기씨 간식의 단백질은 2.1 g, 지방은 5.6 g이에요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내는 과정을 쓰고, 왜 먼저 10을 곱하는지 설명해 보세요.","answer_guide":{"answer":"예: 2.1：5.6의 두 항에 10을 곱하면 21：56이고, 21과 56의 최대공약수 7로 나누면 3：8이다. 두 항이 소수 한 자리 수라서 10을 곱해야 둘 다 자연수가 되고, 두 항에 같은 수를 곱하면 비율이 변하지 않기 때문이다.","scoring_points":["21：56을 만들었는가","7로 나누어 3：8을 구했는가","10을 곱해야 두 항이 자연수가 되고 비율은 그대로라는 까닭을 썼는가"]},"explanation":["10을 곱하면 21：56이에요.","7로 나누면 3：8이에요.","같은 수를 곱해도 비율은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#10','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'essay','teacher','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내는 방법을 두 가지로 쓰고, 두 방법의 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":4,"kind":"essay","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내는 방법을 두 가지로 쓰고, 두 방법의 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: ① 후항 ⟨2/5⟩를 0.4로 바꾸면 0.7：0.4이고 10을 곱하면 7：4이다. ② 전항 0.7을 ⟨7/10⟩로 바꾸면 ⟨7/10⟩：⟨2/5⟩이고 두 분모의 공배수 10을 곱하면 7：4이다. 두 방법 모두 7：4로 같다.","scoring_points":["소수로 바꾸는 방법으로 7：4를 구했는가","분수로 바꾸는 방법으로 7：4를 구했는가","두 답이 같음을 확인했는가"]},"explanation":["⟨2/5⟩ = 0.4 → 0.7：0.4 → 7：4예요.","0.7 = ⟨7/10⟩ → 10을 곱하면 7：4예요.","두 길 모두 7：4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#1','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 56：21 = 8：3에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 8：5 = 16：10에서 외항은 어느 것인가요?","options":[{"t":"8과 10","correct":true},{"t":"5와 16","mis":"M6-2-u4-X10"},{"t":"8과 5","mis":"M6-2-u4-X10"},{"t":"16과 10","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：5 = 16：10에서 바깥쪽은 8과 10, 안쪽은 5와 16이에요.","그래서 외항은 8과 10이에요."]},{"stem":"비례식 6：8 = 9：12에서 외항은 어느 것인가요?","options":[{"t":"6과 12","correct":true},{"t":"8과 9","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 외항은 6과 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#2','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 9：12 = 3：4에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 5：7 = 10：14에서 내항은 어느 것인가요?","options":[{"t":"7과 10","correct":true},{"t":"5와 14","mis":"M6-2-u4-X10"},{"t":"5와 7","mis":"M6-2-u4-X10"},{"t":"10과 14","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","5：7 = 10：14에서 바깥쪽은 5와 14, 안쪽은 7과 10이에요.","그래서 내항은 7과 10이에요."]},{"stem":"비례식 7：9 = 14：18에서 내항은 어느 것인가요?","options":[{"t":"9와 14","correct":true},{"t":"7과 18","mis":"M6-2-u4-X10"},{"t":"7과 9","mis":"M6-2-u4-X10"},{"t":"14와 18","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","7：9 = 14：18에서 바깥쪽은 7과 18, 안쪽은 9와 14예요.","그래서 내항은 9와 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#3','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'sa','auto','48：32의 전항과 후항을 16으로 나누어 비례식 48：32 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"sa","stem":"48：32의 전항과 후항을 16으로 나누어 비례식 48：32 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","48 ÷ 16 = 3, 32 ÷ 16 = 2예요.","그래서 48：32 = 3：2예요."],"variant_rule":{"alt":[{"stem":"45：30의 전항과 후항을 15로 나누어 비례식 45：30 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","45 ÷ 15 = 3, 30 ÷ 15 = 2예요.","그래서 45：30 = 3：2예요."]},{"stem":"56：21의 전항과 후항을 7로 나누어 비례식 56：21 = 8：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","56 ÷ 7 = 8, 21 ÷ 7 = 3이에요.","그래서 56：21 = 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#4','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'sa','auto','7：9의 전항과 후항에 2를 곱해 비례식 7：9 = 14：□를 만들었어요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":1,"kind":"sa","stem":"7：9의 전항과 후항에 2를 곱해 비례식 7：9 = 14：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["18"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","7 × 2 = 14, 9 × 2 = 18이에요.","그래서 7：9 = 14：18이에요."],"variant_rule":{"alt":[{"stem":"8：5의 전항과 후항에 2를 곱해 비례식 8：5 = 16：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","8 × 2 = 16, 5 × 2 = 10이에요.","그래서 8：5 = 16：10이에요."]},{"stem":"3：4의 전항과 후항에 6을 곱해 비례식 3：4 = 18：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","3 × 6 = 18, 4 × 6 = 24예요.","그래서 3：4 = 18：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#5','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#6','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','4：3과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07','M6-2-u4-X01']::text[],true,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"4：3과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/9⟩：⟨1/12⟩","correct":true},{"t":"6：8","mis":"M6-2-u4-X03"},{"t":"⟨1/4⟩：⟨1/3⟩","mis":"M6-2-u4-X07"},{"t":"7：6","mis":"M6-2-u4-X01"}],"explanation":["4：3의 비율은 ⟨4/3⟩예요.","⟨1/9⟩：⟨1/12⟩을 간단한 자연수의 비로 나타내면 4：3이에요.","그래서 4：3 = ⟨1/9⟩：⟨1/12⟩로 이을 수 있어요."],"variant_rule":{"alt":[{"stem":"2：5와 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/5⟩：⟨1/2⟩","correct":true},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"⟨1/2⟩：⟨1/5⟩","mis":"M6-2-u4-X07"},{"t":"4：7","mis":"M6-2-u4-X01"}],"explanation":["2：5의 비율은 ⟨2/5⟩예요.","⟨1/5⟩：⟨1/2⟩을 간단한 자연수의 비로 나타내면 2：5예요.","그래서 2：5 = ⟨1/5⟩：⟨1/2⟩로 이을 수 있어요."]},{"stem":"3：2와 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/2⟩：⟨1/3⟩","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"⟨1/3⟩：⟨1/2⟩","mis":"M6-2-u4-X07"},{"t":"5：4","mis":"M6-2-u4-X01"}],"explanation":["3：2의 비율은 ⟨3/2⟩이에요.","⟨1/2⟩：⟨1/3⟩을 간단한 자연수의 비로 나타내면 3：2예요.","그래서 3：2 = ⟨1/2⟩：⟨1/3⟩로 이을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#7','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'sa','auto','외항이 6과 12이고 두 비의 비율이 모두 ⟨3/4⟩인 비례식이에요. 6：□ = 9：12에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":2,"kind":"sa","stem":"외항이 6과 12이고 두 비의 비율이 모두 ⟨3/4⟩인 비례식이에요. 6：□ = 9：12에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["9：12의 비율은 ⟨3/4⟩이에요.","6：□의 비율도 ⟨3/4⟩이어야 해요.","6 ÷ □ = ⟨3/4⟩이므로 □ = 8이에요."],"variant_rule":{"alt":[{"stem":"외항이 4와 15이고 두 비의 비율이 모두 ⟨2/3⟩인 비례식이에요. 4：□ = 10：15에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["10：15의 비율은 ⟨2/3⟩예요.","4：□의 비율도 ⟨2/3⟩이어야 해요.","4 ÷ □ = ⟨2/3⟩이므로 □ = 6이에요."]},{"stem":"외항이 10과 21이고 두 비의 비율이 모두 ⟨5/7⟩인 비례식이에요. 10：□ = 15：21에서 □에 알맞은 수는 얼마인가요?","answer":["14"],"explanation":["15：21의 비율은 ⟨5/7⟩예요.","10：□의 비율도 ⟨5/7⟩이어야 해요.","10 ÷ □ = ⟨5/7⟩이므로 □ = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#8','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','비례식 8：5 = 16：10에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 8：5 = 16：10에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 8과 10, 내항 5와 16","correct":true},{"t":"외항 5와 16, 내항 8과 10","mis":"M6-2-u4-X10"},{"t":"외항 8과 5, 내항 16과 10","mis":"M6-2-u4-X10"},{"t":"외항 8과 16, 내항 5와 10","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","8：5 = 16：10에서 바깥쪽은 8과 10이에요.","안쪽은 5와 16 — 내항이에요."],"variant_rule":{"alt":[{"stem":"비례식 7：9 = 14：18에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 7과 18, 내항 9와 14","correct":true},{"t":"외항 9와 14, 내항 7과 18","mis":"M6-2-u4-X10"},{"t":"외항 7과 9, 내항 14와 18","mis":"M6-2-u4-X10"},{"t":"외항 7과 14, 내항 9와 18","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","7：9 = 14：18에서 바깥쪽은 7과 18이에요.","안쪽은 9와 14 — 내항이에요."]},{"stem":"비례식 5：7 = 10：14에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 5와 14, 내항 7과 10","correct":true},{"t":"외항 7과 10, 내항 5와 14","mis":"M6-2-u4-X10"},{"t":"외항 5와 7, 내항 10과 14","mis":"M6-2-u4-X10"},{"t":"외항 5와 10, 내항 7과 14","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","5：7 = 10：14에서 바깥쪽은 5와 14예요.","안쪽은 7과 10 — 내항이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#9','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','7：9와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"7：9와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"7：9 = 14：18","correct":true},{"t":"7：9 = 9：7","mis":"M6-2-u4-X09"},{"t":"7：9 = 9：11","mis":"M6-2-u4-X01"},{"t":"7：9 = 14：9","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","7：9와 14：18의 비율은 모두 ⟨7/9⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"3：5와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"3：5 = 9：15","correct":true},{"t":"3：5 = 5：3","mis":"M6-2-u4-X09"},{"t":"3：5 = 5：7","mis":"M6-2-u4-X01"},{"t":"3：5 = 9：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：5와 9：15의 비율은 모두 ⟨3/5⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"4：7과 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"4：7 = 12：21","correct":true},{"t":"4：7 = 7：4","mis":"M6-2-u4-X09"},{"t":"4：7 = 6：9","mis":"M6-2-u4-X01"},{"t":"4：7 = 12：7","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：7과 12：21의 비율은 모두 ⟨4/7⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#10','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',3,'error','auto','비례식에 대해 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X19']::text[],true,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":3,"kind":"error","stem":"비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"지호 — 「2：5와 24：15를 이어 2：5 = 24：15로 나타낼 수 있어.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"유진 — 「6：8 = 9：12에서 외항은 6과 12, 내항은 8과 9야.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「8：5 = 16：10에서 외항은 8과 10이야.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「비례식은 비율이 같은 두 비를 등호로 이은 식이야.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5의 비율은 ⟨2/5⟩, 24：15의 비율은 ⟨8/5⟩로 달라요 — 2：5와 24：15는 등호로 이을 수 없어요.","그래서 그 친구의 설명이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"하린 — 「3：4와 4：3은 같은 수로 되어 있으니 3：4 = 4：3이야.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"도윤 — 「3：4 = 6：8에서 외항은 3과 8이야.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「6：8의 비율도 ⟨3/4⟩이야.」","mis":"M6-2-u4-X19"},{"t":"민준 — 「비례식인지는 비율로 판단해.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：4의 비율은 ⟨3/4⟩, 4：3의 비율은 ⟨4/3⟩로 달라요 — 수의 모양이 같아도 비례식이 아니에요.","그래서 그 친구의 설명이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"서아 — 「5：2와 2：5는 같은 두 수로 되어 있어서 비례식을 만들 수 있어.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"지호 — 「5：2 = 10：4에서 내항은 2와 10이야.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「10：4의 비율도 ⟨5/2⟩야.」","mis":"M6-2-u4-X19"},{"t":"유진 — 「두 비의 비율을 견주어 비례식인지 알아.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","5：2의 비율은 ⟨5/2⟩, 2：5의 비율은 ⟨2/5⟩로 달라요 — 수의 모양이 같아도 비례식이 아니에요.","그래서 그 친구의 설명이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#1','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'mc','auto','비례식 56：21 = 8：3에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 56：21 = 8：3에서 내항은 어느 것인가요?","options":[{"t":"21과 8","correct":true},{"t":"56과 3","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 내항은 21과 8이에요."],"variant_rule":{"alt":[{"stem":"비례식 4：3 = 8：6에서 내항은 어느 것인가요?","options":[{"t":"3과 8","correct":true},{"t":"4와 6","mis":"M6-2-u4-X10"},{"t":"4와 3","mis":"M6-2-u4-X10"},{"t":"8과 6","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","4：3 = 8：6에서 바깥쪽은 4와 6, 안쪽은 3과 8이에요.","그래서 내항은 3과 8이에요."]},{"stem":"비례식 12：15 = 4：5에서 외항은 어느 것인가요?","options":[{"t":"12와 5","correct":true},{"t":"15와 4","mis":"M6-2-u4-X10"},{"t":"12와 15","mis":"M6-2-u4-X10"},{"t":"4와 5","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","12：15 = 4：5에서 바깥쪽은 12와 5, 안쪽은 15와 4예요.","그래서 외항은 12와 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#2','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"6：4 = 3：2","correct":true},{"t":"6：4 = 4：6","mis":"M6-2-u4-X09"},{"t":"6：4 = 8：6","mis":"M6-2-u4-X01"},{"t":"6：4 = 3：4","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","6：4와 3：2의 비율은 모두 ⟨3/2⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"10：15 = 2：3","correct":true},{"t":"10：15 = 15：10","mis":"M6-2-u4-X09"},{"t":"10：15 = 12：17","mis":"M6-2-u4-X01"},{"t":"10：15 = 2：15","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","10：15와 2：3의 비율은 모두 ⟨2/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#3','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','⟨1/6⟩：⟨1/9⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"⟨1/6⟩：⟨1/9⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"300：200","correct":true},{"t":"6：9","mis":"M6-2-u4-X07"},{"t":"200：300","mis":"M6-2-u4-X03"},{"t":"1.5：1.2","mis":"M6-2-u4-X20"}],"explanation":["⟨1/6⟩：⟨1/9⟩의 비율은 ⟨3/2⟩이에요.","300：200을 간단한 자연수의 비로 나타내면 3：2예요.","그래서 ⟨1/6⟩：⟨1/9⟩ = 300：200으로 이을 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩：⟨1/5⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"1.5：0.9","correct":true},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"0.9：1.5","mis":"M6-2-u4-X03"},{"t":"1.5：1.2","mis":"M6-2-u4-X20"}],"explanation":["⟨1/3⟩：⟨1/5⟩의 비율은 ⟨5/3⟩예요.","1.5：0.9를 간단한 자연수의 비로 나타내면 5：3이에요.","그래서 ⟨1/3⟩：⟨1/5⟩ = 1.5：0.9로 이을 수 있어요."]},{"stem":"⟨1/2⟩：⟨1/8⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"2.4：0.6","correct":true},{"t":"2：8","mis":"M6-2-u4-X07"},{"t":"0.6：2.4","mis":"M6-2-u4-X03"},{"t":"2.4：0.8","mis":"M6-2-u4-X20"}],"explanation":["⟨1/2⟩：⟨1/8⟩의 비율은 4예요.","2.4：0.6을 간단한 자연수의 비로 나타내면 4：1이에요.","그래서 ⟨1/2⟩：⟨1/8⟩ = 2.4：0.6으로 이을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#4','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'ox','auto','7：4 = 4：7은 같은 수 7과 4로 이루어져 있으니 비례식이에요.',ARRAY['M6-2-u4-X09']::text[],true,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"7：4 = 4：7은 같은 수 7과 4로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["비례식인지는 수의 모양이 아니라 비율로 판단해요.","7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩예요.","비율이 다르니 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"3：2 = 2：3은 같은 수 3과 2로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"3：2의 비율은 ⟨3/2⟩, 2：3의 비율은 ⟨2/3⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"explanation":["비례식인지는 비율로 판단해요.","3：2의 비율은 ⟨3/2⟩, 2：3의 비율은 ⟨2/3⟩예요.","비율이 다르니 비례식이 아니에요."]},{"stem":"5：8 = 8：5는 같은 수 5와 8로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"5：8의 비율은 ⟨5/8⟩, 8：5의 비율은 ⟨8/5⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"explanation":["비례식인지는 비율로 판단해요.","5：8의 비율은 ⟨5/8⟩, 8：5의 비율은 ⟨8/5⟩이에요.","비율이 다르니 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#5','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8：5 = 16：10","correct":true},{"t":"8：5 = 10：16","mis":"M6-2-u4-X03"},{"t":"8：5 = 16：5","mis":"M6-2-u4-X02"},{"t":"5：8 = 16：10","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 8：5, 확대한 후는 16：10이에요.","두 비의 비율은 모두 1.6으로 같아요.","그래서 8：5 = 16：10이에요."],"variant_rule":{"alt":[{"stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 6 cm, 세로 4 cm이고, 확대한 후 사진은 가로 9 cm, 세로 6 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6：4 = 9：6","correct":true},{"t":"6：4 = 6：9","mis":"M6-2-u4-X03"},{"t":"6：4 = 9：4","mis":"M6-2-u4-X02"},{"t":"4：6 = 9：6","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 6：4, 확대한 후는 9：6이에요.","두 비의 비율은 모두 1.5로 같아요.","그래서 6：4 = 9：6이에요."]},{"stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 10 cm, 세로 6 cm이고, 확대한 후 사진은 가로 15 cm, 세로 9 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10：6 = 15：9","correct":true},{"t":"10：6 = 9：15","mis":"M6-2-u4-X03"},{"t":"10：6 = 15：6","mis":"M6-2-u4-X02"},{"t":"6：10 = 15：9","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 10：6, 확대한 후는 15：9예요.","두 비의 비율은 모두 ⟨5/3⟩로 같아요.","그래서 10：6 = 15：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#6','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','외항이 4와 15, 내항이 5와 12인 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X09']::text[],true,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"외항이 4와 15, 내항이 5와 12인 비례식은 어느 것인가요?","options":[{"t":"4：5 = 12：15","correct":true},{"t":"5：4 = 15：12","mis":"M6-2-u4-X10"},{"t":"4：5 = 15：12","mis":"M6-2-u4-X09"},{"t":"12：4 = 15：5","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","4：5 = 12：15에서 바깥쪽은 4와 15, 안쪽은 5와 12예요.","두 비의 비율도 0.8로 같아 비례식이에요."],"variant_rule":{"alt":[{"stem":"외항이 3과 20, 내항이 4와 15인 비례식은 어느 것인가요?","options":[{"t":"3：4 = 15：20","correct":true},{"t":"4：3 = 20：15","mis":"M6-2-u4-X10"},{"t":"3：4 = 20：15","mis":"M6-2-u4-X09"},{"t":"15：3 = 20：4","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","3：4 = 15：20에서 바깥쪽은 3과 20, 안쪽은 4와 15예요.","두 비의 비율도 0.75로 같아 비례식이에요."]},{"stem":"외항이 2와 21, 내항이 3과 14인 비례식은 어느 것인가요?","options":[{"t":"2：3 = 14：21","correct":true},{"t":"3：2 = 21：14","mis":"M6-2-u4-X10"},{"t":"2：3 = 21：14","mis":"M6-2-u4-X09"},{"t":"14：2 = 21：3","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","2：3 = 14：21에서 바깥쪽은 2와 21, 안쪽은 3과 14예요.","두 비의 비율도 ⟨2/3⟩로 같아 비례식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#7','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'match','auto','비례식이 되도록 □에 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":3,"kind":"match","stem":"비례식이 되도록 □에 알맞은 수를 이으세요.","pairs":[{"l":"2：3 = 8：□","r":"12"},{"l":"5：4 = □：12","r":"15"},{"l":"3：7 = 9：□","r":"21"}],"mis":"M6-2-u4-X12","explanation":["2：3의 두 항에 4를 곱하면 8：12예요.","5：4의 두 항에 3을 곱하면 15：12예요.","3：7의 두 항에 3을 곱하면 9：21이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식이 되도록 □에 알맞은 수를 이으세요.","pairs":[{"l":"4：5 = 20：□","r":"25"},{"l":"2：9 = □：27","r":"6"},{"l":"6：5 = 18：□","r":"15"}],"explanation":["4：5의 두 항에 5를 곱하면 20：25예요.","2：9의 두 항에 3을 곱하면 6：27이에요.","6：5의 두 항에 3을 곱하면 18：15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#8','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":4,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]},{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#9','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','친구가 「7：4 = 4：7은 같은 수로 되어 있으니 비례식이야」라고 했어요. 이 말이 맞는지 비율을 견주어 설명하고, 7：4와 비례식으로 이을 수 있는 비를 하나 만들어 비례식으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"친구가 「7：4 = 4：7은 같은 수로 되어 있으니 비례식이야」라고 했어요. 이 말이 맞는지 비율을 견주어 설명하고, 7：4와 비례식으로 이을 수 있는 비를 하나 만들어 비례식으로 써 보세요.","answer_guide":{"answer":"예: 7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩로 달라서 비례식이 아니다. 7：4의 두 항에 2를 곱한 14：8은 비율이 ⟨7/4⟩로 같으므로 7：4 = 14：8로 쓸 수 있다.","scoring_points":["두 비의 비율을 구해 다름을 보였는가","비례식이 아니라고 판단했는가","7：4와 비율이 같은 비로 비례식을 바르게 썼는가"]},"explanation":["7：4는 ⟨7/4⟩, 4：7은 ⟨4/7⟩예요.","비율이 다르니 비례식이 아니에요.","7：4 = 14：8처럼 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#10','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','확대하기 전 철새 사진은 가로 8 cm, 세로 5 cm, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비로 비례식을 세우고, 외항과 내항을 각각 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"확대하기 전 철새 사진은 가로 8 cm, 세로 5 cm, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비로 비례식을 세우고, 외항과 내항을 각각 써 보세요.","answer_guide":{"answer":"예: 두 비 8：5와 16：10은 비율이 ⟨8/5⟩로 같으므로 8：5 = 16：10이다. 외항은 바깥쪽의 8과 10, 내항은 안쪽의 5와 16이다.","scoring_points":["8：5 = 16：10을 세웠는가","외항 8과 10을 바르게 썼는가","내항 5와 16을 바르게 썼는가"]},"explanation":["8：5와 16：10은 비율이 같아요.","8：5 = 16：10이에요.","외항 8과 10, 내항 5와 16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#1','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]},{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#2','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."],"variant_rule":{"alt":[{"stem":"3：4 = 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 4 × 9 = 36이므로 3 × □ = 36이에요.","□ = 36 ÷ 3 = 12예요."]},{"stem":"2：5 = 6：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 6 = 30이므로 2 × □ = 30이에요.","□ = 30 ÷ 2 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#3','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','3：11 = □：22에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."],"variant_rule":{"alt":[{"stem":"4：7 = □：21에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 21 = 84이므로 7 × □ = 84예요.","□ = 84 ÷ 7 = 12예요."]},{"stem":"5：9 = □：27에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 5 × 27 = 135이므로 9 × □ = 135예요.","□ = 135 ÷ 9 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#4','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'mc','auto','외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"mc","stem":"외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"5：2 = 10：4","correct":true},{"t":"7：14 = 6：13","mis":"M6-2-u4-X01"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"3：5 = 4：6","mis":"M6-2-u4-X01"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","5：2와 10：4의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"4：6 = 10：15","correct":true},{"t":"4：6 = 6：4","mis":"M6-2-u4-X09"},{"t":"4：6 = 5：7","mis":"M6-2-u4-X01"},{"t":"4：6 = 8：10","mis":"M6-2-u4-X01"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：6과 10：15의 비율은 모두 ⟨2/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"3：8 = 9：24","correct":true},{"t":"3：8 = 8：3","mis":"M6-2-u4-X09"},{"t":"3：8 = 5：10","mis":"M6-2-u4-X01"},{"t":"3：8 = 6：8","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：8과 9：24의 비율은 모두 ⟨3/8⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#5','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X10','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"100","correct":true},{"t":"29","mis":"M6-2-u4-X14"},{"t":"25","mis":"M6-2-u4-X10"},{"t":"200","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 25 = 100이므로 1 × □ = 100이에요.","□ = 100 ÷ 1 = 100이에요."],"variant_rule":{"alt":[{"stem":"3：□ = 1：40에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"120","correct":true},{"t":"43","mis":"M6-2-u4-X14"},{"t":"40","mis":"M6-2-u4-X10"},{"t":"240","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 40 = 120이므로 1 × □ = 120이에요.","□ = 120 ÷ 1 = 120이에요."]},{"stem":"6：□ = 1：30에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"180","correct":true},{"t":"36","mis":"M6-2-u4-X14"},{"t":"30","mis":"M6-2-u4-X10"},{"t":"360","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 6 × 30 = 180이므로 1 × □ = 180이에요.","□ = 180 ÷ 1 = 180이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#6','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20','M6-2-u4-X10']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 14 × □와 내항의 곱 8 × 21은 같아요","correct":true},{"t":"14：8과 21：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 6이에요","mis":"M6-2-u4-X20"},{"t":"내항은 14와 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 14와 □, 내항은 8과 21이에요.","14 × □ = 168이므로 □ = 12예요."],"variant_rule":{"alt":[{"stem":"6：4 = 9：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 6 × □와 내항의 곱 4 × 9는 같아요","correct":true},{"t":"6：4와 9：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 3이에요","mis":"M6-2-u4-X20"},{"t":"내항은 6과 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 6과 □, 내항은 4와 9예요.","6 × □ = 36이므로 □ = 6이에요."]},{"stem":"10：4 = 15：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 10 × □와 내항의 곱 4 × 15는 같아요","correct":true},{"t":"10：4와 15：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 3이에요","mis":"M6-2-u4-X20"},{"t":"내항은 10과 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 10과 □, 내항은 4와 15예요.","10 × □ = 60이므로 □ = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#7','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','21：28 = 3：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"21：28 = 3：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"147","correct":true},{"t":"84","mis":"M6-2-u4-X10"},{"t":"63","mis":"M6-2-u4-X11"},{"t":"196","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 21과 7이에요.","외항의 곱은 21 × 7 = 147이에요.","내항의 곱은 28 × 3 = 84 — 두 곱이 달라 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"18：24 = 4：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"126","correct":true},{"t":"96","mis":"M6-2-u4-X10"},{"t":"72","mis":"M6-2-u4-X11"},{"t":"168","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 18과 7이에요.","외항의 곱은 18 × 7 = 126이에요.","내항의 곱은 24 × 4 = 96 — 두 곱이 달라 비례식이 아니에요."]},{"stem":"25：15 = 6：4는 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"100","correct":true},{"t":"90","mis":"M6-2-u4-X10"},{"t":"150","mis":"M6-2-u4-X11"},{"t":"60","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 25와 4예요.","외항의 곱은 25 × 4 = 100이에요.","내항의 곱은 15 × 6 = 90 — 두 곱이 달라 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#8','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'sa','auto','8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 8 × □ = 72예요.","□ = 72 ÷ 8 = 9예요."],"variant_rule":{"alt":[{"stem":"6：9 = 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 9 × 8 = 72이므로 6 × □ = 72예요.","□ = 72 ÷ 6 = 12예요."]},{"stem":"12：9 = 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 9 × 8 = 72이므로 12 × □ = 72예요.","□ = 72 ÷ 12 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#9','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','4：★ = 1.2：☆에서 내항의 곱이 6이에요. ★에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X12','M6-2-u4-X10']::text[],true,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"4：★ = 1.2：☆에서 내항의 곱이 6이에요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M6-2-u4-X12"},{"t":"1.2","mis":"M6-2-u4-X10"},{"t":"4","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 1.2예요.","★ × 1.2 = 6이에요.","★ = 6 ÷ 1.2 = 5예요."],"variant_rule":{"alt":[{"stem":"5：★ = 0.8：☆에서 내항의 곱이 2예요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"2","mis":"M6-2-u4-X12"},{"t":"0.8","mis":"M6-2-u4-X10"},{"t":"5","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 0.8이에요.","★ × 0.8 = 2예요.","★ = 2 ÷ 0.8 = 2.5예요."]},{"stem":"3：★ = 1.5：☆에서 내항의 곱이 9예요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"9","mis":"M6-2-u4-X12"},{"t":"1.5","mis":"M6-2-u4-X10"},{"t":"3","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 1.5예요.","★ × 1.5 = 9예요.","★ = 9 ÷ 1.5 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#10','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',3,'mc','auto','8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."],"variant_rule":{"alt":[{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]},{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#1','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"□：5 = 8：10에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 8 = 40이므로 10 × □ = 40이에요.","□ = 40 ÷ 10 = 4예요."]},{"stem":"□：7 = 12：21에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 7 × 12 = 84이므로 21 × □ = 84예요.","□ = 84 ÷ 21 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#2','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.4 × 15 = 6이므로 2 × □ = 6이에요.","□ = 6 ÷ 2 = 3이에요."],"variant_rule":{"alt":[{"stem":"1.5：□ = 3：8에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 1.5 × 8 = 12이므로 3 × □ = 12예요.","□ = 12 ÷ 3 = 4예요."]},{"stem":"0.6：□ = 3：10에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.6 × 10 = 6이므로 3 × □ = 6이에요.","□ = 6 ÷ 3 = 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#3','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'sa','auto','⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":3,"kind":"sa","stem":"⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/2⟩ × 4 = 2이므로 ⟨1/3⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/3⟩ = 6이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩：⟨1/5⟩ = □：8에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/4⟩ × 8 = 2이므로 ⟨1/5⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/5⟩ = 10이에요."]},{"stem":"⟨2/3⟩：⟨1/2⟩ = □：6에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨2/3⟩ × 6 = 4이므로 ⟨1/2⟩ × □ = 4예요.","□ = 4 ÷ ⟨1/2⟩ = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#4','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"6：9 = 3：5","correct":true},{"t":"6：9 = 2：3","mis":"M6-2-u4-X19"},{"t":"4：10 = 6：15","mis":"M6-2-u4-X19"},{"t":"12：8 = 3：2","mis":"M6-2-u4-X19"}],"explanation":["6：9 = 2：3은 18과 18, 4：10 = 6：15는 60과 60이에요.","12：8 = 3：2는 24와 24예요.","6：9 = 3：5는 외항의 곱 30, 내항의 곱 27로 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"5：4 = 15：13","correct":true},{"t":"5：4 = 15：12","mis":"M6-2-u4-X19"},{"t":"2：7 = 6：21","mis":"M6-2-u4-X19"},{"t":"9：3 = 6：2","mis":"M6-2-u4-X19"}],"explanation":["5：4 = 15：12는 60과 60, 2：7 = 6：21은 42와 42예요.","9：3 = 6：2는 18과 18이에요.","5：4 = 15：13은 외항의 곱 65, 내항의 곱 60으로 달라요."]},{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"3：8 = 6：15","correct":true},{"t":"3：8 = 6：16","mis":"M6-2-u4-X19"},{"t":"10：4 = 5：2","mis":"M6-2-u4-X19"},{"t":"7：3 = 14：6","mis":"M6-2-u4-X19"}],"explanation":["3：8 = 6：16은 48과 48, 10：4 = 5：2는 20과 20이에요.","7：3 = 14：6은 42와 42예요.","3：8 = 6：15는 외항의 곱 45, 내항의 곱 48로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#5','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X12','M6-2-u4-X11','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"12","correct":true},{"t":"60","mis":"M6-2-u4-X12"},{"t":"20","mis":"M6-2-u4-X11"},{"t":"36","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 5와 □예요.","5 × □ = 60이에요.","□ = 60 ÷ 5 = 12예요."],"variant_rule":{"alt":[{"stem":"비례식 2：7 = □：△에서 내항의 곱이 56이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"56","mis":"M6-2-u4-X12"},{"t":"28","mis":"M6-2-u4-X11"},{"t":"16","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 7과 □예요.","7 × □ = 56이에요.","□ = 56 ÷ 7 = 8이에요."]},{"stem":"비례식 4：9 = □：△에서 내항의 곱이 72예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"72","mis":"M6-2-u4-X12"},{"t":"18","mis":"M6-2-u4-X11"},{"t":"32","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 9와 □예요.","9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#6','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'ox','auto','비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.',ARRAY['M6-2-u4-X11']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":3,"kind":"ox","stem":"비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.","answer":"O","reason_options":[{"t":"8 × 9와 6 × 12가 모두 72이기 때문에","correct":true},{"t":"8 × 12와 6 × 9가 같기 때문에","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["외항은 8과 9, 내항은 6과 12예요.","8 × 9 = 72, 6 × 12 = 72예요.","두 곱이 모두 72로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 4：10 = 6：15에서 외항의 곱과 내항의 곱은 모두 60이에요.","answer":"O","reason_options":[{"t":"4 × 15와 10 × 6이 모두 60이기 때문에","correct":true},{"t":"4 × 6과 10 × 15가 같기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 4와 15, 내항은 10과 6이에요.","4 × 15 = 60, 10 × 6 = 60이에요.","두 곱이 모두 60으로 같아요."]},{"stem":"비례식 3：7 = 9：21에서 외항의 곱과 내항의 곱은 모두 27이에요.","answer":"X","reason_options":[{"t":"외항의 곱 3 × 21과 내항의 곱 7 × 9는 모두 63이기 때문에","correct":true},{"t":"3 × 9가 27이라 외항의 곱이 27이기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 3과 21, 내항은 7과 9예요.","3 × 21 = 63, 7 × 9 = 63이에요.","27은 전항끼리 곱한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#7','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'match','auto','비례식의 □에 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":3,"kind":"match","stem":"비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：4 = 6：8","r":"3"},{"l":"5：□ = 10：14","r":"7"},{"l":"9：12 = 3：□","r":"4"}],"mis":"M6-2-u4-X12","explanation":["□ × 8 = 4 × 6 = 24 → □ = 3이에요.","5 × 14 = □ × 10 = 70 → □ = 7이에요.","9 × □ = 12 × 3 = 36 → □ = 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：6 = 4：8","r":"3"},{"l":"2：□ = 6：15","r":"5"},{"l":"8：10 = 12：□","r":"15"}],"explanation":["□ × 8 = 6 × 4 = 24 → □ = 3이에요.","2 × 15 = □ × 6 = 30 → □ = 5예요.","8 × □ = 10 × 12 = 120 → □ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#8','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'mc','auto','어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X12']::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"63","mis":"M6-2-u4-X20"},{"t":"81","mis":"M6-2-u4-X20"},{"t":"648","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 72예요.","9 × □ = 72 — □ = 8이에요."],"variant_rule":{"alt":[{"stem":"어떤 비례식에서 외항의 곱이 84이고 내항 하나가 12예요. 다른 내항은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"72","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"1008","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 84예요.","12 × □ = 84 — □ = 7이에요."]},{"stem":"어떤 비례식에서 내항의 곱이 90이고 외항 하나가 6이에요. 다른 외항은 얼마인가요?","options":[{"t":"15","correct":true},{"t":"84","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"540","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 외항의 곱도 90이에요.","6 × □ = 90 — □ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#9','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 외항의 곱은 5 × 14 = 70, 내항의 곱은 7 × 10 = 70으로 같다. 비례식은 두 비의 비율이 같다는 뜻이고, 10：14는 5：7의 두 항에 똑같이 2를 곱한 것이어서 외항의 곱과 내항의 곱이 모두 5 × 7 × 2가 되기 때문이다.","scoring_points":["외항의 곱 70을 구했는가","내항의 곱 70을 구해 같음을 보였는가","비율이 같다(같은 수를 곱했다)는 까닭을 썼는가"]},"explanation":["5 × 14 = 70이에요.","7 × 10 = 70이에요.","비율이 같아서 생기는 결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#10','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.","answer_guide":{"answer":"예: 비례식에서는 외항끼리, 내항끼리 곱해야 하는데 친구는 한 비의 두 수를 곱했다. 외항의 곱 9 × 12 = 108과 내항의 곱 4 × □가 같으므로 □ = 27이다. 사과는 27개 필요하다.","scoring_points":["잘못된 점(외항끼리·내항끼리 곱하지 않음)을 썼는가","9 × 12 = 4 × □를 세웠는가","□ = 27을 구했는가"]},"explanation":["외항끼리, 내항끼리 곱해요.","9 × 12 = 108 = 4 × □예요.","□ = 27 — 사과 27개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#1','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["구하려는 값을 □라 하고 비례식 2：8000 = □：40000을 세워요.","외항의 곱 2 × 40000 = 80000이므로 8000 × □ = 80000이에요.","□ = 80000 ÷ 8000 = 10 — 10이에요."],"variant_rule":{"alt":[{"stem":"직거래 장터에서 쌀 3 kg을 9000원에 팔아요. 27000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 3：9000 = □：27000이에요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 3：9000 = □：27000을 세워요.","외항의 곱 3 × 27000 = 81000이므로 9000 × □ = 81000이에요.","□ = 81000 ÷ 9000 = 9 — 9예요."]},{"stem":"직거래 장터에서 쌀 4 kg을 12000원에 팔아요. 36000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 4：12000 = □：36000이에요. □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 4：12000 = □：36000을 세워요.","외항의 곱 4 × 36000 = 144000이므로 12000 × □ = 144000이에요.","□ = 144000 ÷ 12000 = 12 — 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#2','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 5 kWh의 전기 에너지로 30 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"120 km","correct":true},{"t":"45 km","mis":"M6-2-u4-X14"},{"t":"600 km","mis":"M6-2-u4-X12"},{"t":"240 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：30 = 20：□를 세워요.","내항의 곱 30 × 20 = 600이므로 5 × □ = 600이에요.","□ = 600 ÷ 5 = 120 — 120 km예요."]},{"stem":"어느 전기차는 4 kWh의 전기 에너지로 25 km를 이동해요. 12 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"75 km","correct":true},{"t":"33 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"150 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：25 = 12：□를 세워요.","내항의 곱 25 × 12 = 300이므로 4 × □ = 300이에요.","□ = 300 ÷ 4 = 75 — 75 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#3','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."],"variant_rule":{"alt":[{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 240 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 240：□를 세워요.","내항의 곱 1 × 240 = 240이므로 3 × □ = 240이에요.","□ = 240 ÷ 3 = 80 — 80 g예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 150 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 150：□를 세워요.","내항의 곱 1 × 150 = 150이므로 3 × □ = 150이에요.","□ = 150 ÷ 3 = 50 — 50 g예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#4','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：6","correct":true},{"t":"25：150","mis":"M6-2-u4-X05"},{"t":"6：1","mis":"M6-2-u4-X03"},{"t":"2.5：150","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 25：150이에요.","25와 150의 최대공약수 25로 나누면 1：6이에요.","그래서 가장 간단한 자연수의 비는 1：6이에요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키는 1.5 cm, 첨성대의 높이는 12 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：8","correct":true},{"t":"15：120","mis":"M6-2-u4-X05"},{"t":"8：1","mis":"M6-2-u4-X03"},{"t":"1.5：120","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 15：120이에요.","15와 120의 최대공약수 15로 나누면 1：8이에요.","그래서 가장 간단한 자연수의 비는 1：8이에요."]},{"stem":"사진 속 형의 키는 3.5 cm, 첨성대의 높이는 14 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：4","correct":true},{"t":"35：140","mis":"M6-2-u4-X05"},{"t":"4：1","mis":"M6-2-u4-X03"},{"t":"3.5：140","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 35：140이에요.","35와 140의 최대공약수 35로 나누면 1：4예요.","그래서 가장 간단한 자연수의 비는 1：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#5','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 1：6 = 1.5：□를 세워요.","내항의 곱 6 × 1.5 = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9 — 9예요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：4이고 형의 실제 키는 1.5 m예요. 1：4 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["6"],"explanation":["구하려는 값을 □라 하고 비례식 1：4 = 1.5：□를 세워요.","내항의 곱 4 × 1.5 = 6이므로 1 × □ = 6이에요.","□ = 6 ÷ 1 = 6 — 6이에요."]},{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：8이고 형의 실제 키는 1.5 m예요. 1：8 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 1：8 = 1.5：□를 세워요.","내항의 곱 8 × 1.5 = 12이므로 1 × □ = 12예요.","□ = 12 ÷ 1 = 12 — 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#6','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."],"variant_rule":{"alt":[{"stem":"페인트 3 L로 담장 27 m²를 칠할 수 있어요. 담장 45 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"405 L","mis":"M6-2-u4-X13"},{"t":"21 L","mis":"M6-2-u4-X14"},{"t":"135 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 3：27 = □：45를 세워요.","외항의 곱 3 × 45 = 135이므로 27 × □ = 135예요.","□ = 135 ÷ 27 = 5 — 5 L예요."]},{"stem":"페인트 6 L로 담장 54 m²를 칠할 수 있어요. 담장 72 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"8 L","correct":true},{"t":"648 L","mis":"M6-2-u4-X13"},{"t":"24 L","mis":"M6-2-u4-X14"},{"t":"432 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 6：54 = □：72를 세워요.","외항의 곱 6 × 72 = 432이므로 54 × □ = 432예요.","□ = 432 ÷ 54 = 8 — 8 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#7','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."],"variant_rule":{"alt":[{"stem":"물이 일정하게 나오는 수도로 들이가 10 L인 수조를 가득 채우는 데 18초가 걸려요. 들이가 25 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["45"],"explanation":["구하려는 값을 □라 하고 비례식 10：18 = 25：□를 세워요.","내항의 곱 18 × 25 = 450이므로 10 × □ = 450이에요.","□ = 450 ÷ 10 = 45 — 45초예요."]},{"stem":"물이 일정하게 나오는 수도로 들이가 12 L인 수조를 가득 채우는 데 20초가 걸려요. 들이가 30 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 12：20 = 30：□를 세워요.","내항의 곱 20 × 30 = 600이므로 12 × □ = 600이에요.","□ = 600 ÷ 12 = 50 — 50초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#8','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2：8000의 전항과 후항에 5를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 전항과 후항에 5를 곱한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 비율과 □：40000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["2：8000의 후항 8000에 5를 곱하면 40000이에요.","그래서 전항에도 5를 곱해 □ = 10이에요.","같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"3：9000 = □：27000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3：9000의 전항과 후항에 3을 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 전항과 후항에 3을 곱한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 비율과 □：27000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["3：9000의 후항 9000에 3을 곱하면 27000이에요.","그래서 전항에도 3을 곱해 □ = 9예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]},{"stem":"6：40 = □：160에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6：40의 전항과 후항에 4를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"6：40의 전항과 후항에 4를 곱한다","mis":"M6-2-u4-X19"},{"t":"6：40의 비율과 □：160의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["6：40의 후항 40에 4를 곱하면 160이에요.","그래서 전항에도 4를 곱해 □ = 24예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#9','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."],"variant_rule":{"alt":[{"stem":"사과 6개로 사과주스 4병을 만들 수 있어요. 사과주스 10병을 만들려면 사과가 몇 개 필요한가요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 6：4 = □：10을 세워요.","외항의 곱 6 × 10 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15개예요."]},{"stem":"사과 8개로 사과주스 3병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["32"],"explanation":["구하려는 값을 □라 하고 비례식 8：3 = □：12를 세워요.","외항의 곱 8 × 12 = 96이므로 3 × □ = 96이에요.","□ = 96 ÷ 3 = 32 — 32개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#10','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',3,'mc','auto','쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."],"variant_rule":{"alt":[{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]},{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#1','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'mc','auto','어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"200 km","correct":true},{"t":"71 km","mis":"M6-2-u4-X14"},{"t":"1400 km","mis":"M6-2-u4-X12"},{"t":"400 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 7：50 = 28：□를 세워요.","내항의 곱 50 × 28 = 1400이므로 7 × □ = 1400이에요.","□ = 1400 ÷ 7 = 200 — 200 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 3 kWh의 전기 에너지로 20 km를 이동해요. 15 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"100 km","correct":true},{"t":"32 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"200 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：20 = 15：□를 세워요.","내항의 곱 20 × 15 = 300이므로 3 × □ = 300이에요.","□ = 300 ÷ 3 = 100 — 100 km예요."]},{"stem":"어느 전기차는 8 kWh의 전기 에너지로 60 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"150 km","correct":true},{"t":"72 km","mis":"M6-2-u4-X14"},{"t":"1200 km","mis":"M6-2-u4-X12"},{"t":"300 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 8：60 = 20：□를 세워요.","내항의 곱 60 × 20 = 1200이므로 8 × □ = 1200이에요.","□ = 1200 ÷ 8 = 150 — 150 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#2','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"빵 반죽에 밀가루와 우유를 5：3으로 넣어요. 밀가루를 15컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 5：3 = 15：□를 세워요.","내항의 곱 3 × 15 = 45이므로 5 × □ = 45예요.","□ = 45 ÷ 5 = 9 — 9컵예요."]},{"stem":"빵 반죽에 밀가루와 우유를 4：3으로 넣어요. 밀가루를 20컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 4：3 = 20：□를 세워요.","내항의 곱 3 × 20 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15컵예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#3','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u4-X02','M6-2-u4-X14','M6-2-u4-X13']::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：1에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 3：1로 섞었어요. 용액을 3컵 더 넣어 6컵으로 늘리면서 친구는 물도 3컵 더 넣어 4컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 6컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["3：1에서 용액이 3컵 → 6컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]},{"stem":"비눗방울 용액과 물을 2：3으로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 5컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 6컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：3에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 3 × 2 = 6컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#4','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','공책 4권이 3600원이에요. 공책 9권은 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."],"variant_rule":{"alt":[{"stem":"공책 3권이 2400원이에요. 공책 7권은 얼마인가요?","options":[{"t":"5600원","correct":true},{"t":"2404원","mis":"M6-2-u4-X14"},{"t":"16800원","mis":"M6-2-u4-X12"},{"t":"11200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：2400 = 7：□를 세워요.","내항의 곱 2400 × 7 = 16800이므로 3 × □ = 16800이에요.","□ = 16800 ÷ 3 = 5600 — 5600원예요."]},{"stem":"공책 5권이 6000원이에요. 공책 8권은 얼마인가요?","options":[{"t":"9600원","correct":true},{"t":"6003원","mis":"M6-2-u4-X14"},{"t":"48000원","mis":"M6-2-u4-X12"},{"t":"19200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：6000 = 8：□를 세워요.","내항의 곱 6000 × 8 = 48000이므로 5 × □ = 48000이에요.","□ = 48000 ÷ 5 = 9600 — 9600원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#5','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"지도에서 2 cm는 실제 거리 5 km예요. 지도에서 7 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"17.5 km","correct":true},{"t":"2.8 km","mis":"M6-2-u4-X13"},{"t":"10 km","mis":"M6-2-u4-X14"},{"t":"35 km","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 2：5 = 7：□를 세워요.","내항의 곱 5 × 7 = 35이므로 2 × □ = 35예요.","□ = 35 ÷ 2 = 17.5 — 17.5 km예요."]},{"stem":"지도에서 1 cm는 실제 거리 3 km예요. 지도에서 4.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"13.5 km","correct":true},{"t":"1.5 km","mis":"M6-2-u4-X13"},{"t":"6.5 km","mis":"M6-2-u4-X14"},{"t":"27 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：3 = 4.5：□를 세워요.","내항의 곱 3 × 4.5 = 13.5이므로 1 × □ = 13.5예요.","□ = 13.5 ÷ 1 = 13.5 — 13.5 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#6','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X02','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"6에 3.5를 곱하면 21이니 40에도 3.5를 곱한다","correct":true},{"t":"6에 15를 더하면 21이니 40에도 15를 더한다","mis":"M6-2-u4-X14"},{"t":"6에 3.5를 곱하면 21이니 40은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"40에 21을 곱하고 6으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","6 × 3.5 = 21이에요.","그래서 □ = 40 × 3.5 = 140이에요."],"variant_rule":{"alt":[{"stem":"2：8000 = 10：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"2에 5를 곱하면 10이니 8000에도 5를 곱한다","correct":true},{"t":"2에 8을 더하면 10이니 8000에도 8을 더한다","mis":"M6-2-u4-X14"},{"t":"2에 5를 곱하면 10이니 8000은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"8000에 10을 곱하고 2로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","2 × 5 = 10이에요.","그래서 □ = 8000 × 5 = 40000이에요."]},{"stem":"3：1 = 180：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"3에 60을 곱하면 180이니 1에도 60을 곱한다","correct":true},{"t":"3에 177을 더하면 180이니 1에도 177을 더한다","mis":"M6-2-u4-X14"},{"t":"3에 60을 곱하면 180이니 1은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"1에 180을 곱하고 3으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","3 × 60 = 180이에요.","그래서 □ = 1 × 60 = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#7','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'match','auto','문제와 알맞은 답을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":3,"kind":"match","stem":"문제와 알맞은 답을 이으세요.","pairs":[{"l":"쌀 2 kg에 8000원 — 10 kg은?","r":"40000원"},{"l":"6 kWh로 40 km — 21 kWh로는?","r":"140 km"},{"l":"사과 9개로 주스 4병 — 12병에는?","r":"사과 27개"}],"mis":"M6-2-u4-X13","explanation":["2：8000 = 10：□ → □ = 40000이에요.","6：40 = 21：□ → □ = 140이에요.","9：4 = □：12 → □ = 27이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문제와 알맞은 답을 이으세요.","pairs":[{"l":"페인트 4 L로 48 m² — 60 m²에는?","r":"5 L"},{"l":"15 L에 24초 — 50 L는?","r":"80초"},{"l":"계피와 에탄올 3：1 — 계피 180 g이면?","r":"에탄올 60 g"}],"explanation":["4：48 = □：60 → □ = 5예요.","15：24 = 50：□ → □ = 80이에요.","3：1 = 180：□ → □ = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#8','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'mc','auto','두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?',ARRAY['M6-2-u4-X14']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":4,"kind":"mc","stem":"두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"형은 12살, 동생은 9살일 때 형이 15살이 되면 동생은 몇 살인지 구하기","correct":true},{"t":"쌀 2 kg이 8000원일 때 6 kg의 값 구하기","mis":"M6-2-u4-X14"},{"t":"사과 9개로 주스 4병일 때 8병에 드는 사과 구하기","mis":"M6-2-u4-X14"},{"t":"6 kWh로 40 km를 갈 때 12 kWh로 가는 거리 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"언니는 14살, 나는 10살일 때 언니가 21살이 되면 나는 몇 살인지 구하기","correct":true},{"t":"공책 4권이 3600원일 때 8권의 값 구하기","mis":"M6-2-u4-X14"},{"t":"15 L에 24초가 걸릴 때 30 L에 걸리는 시간 구하기","mis":"M6-2-u4-X14"},{"t":"페인트 4 L로 48 m²를 칠할 때 8 L로 칠하는 넓이 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#9','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 살 수 있는 쌀을 □ kg이라 하면 2：8000 = □：40000이다. ① 외항의 곱 2 × 40000 = 80000과 내항의 곱 8000 × □가 같으므로 □ = 10이다. ② 8000에 5를 곱하면 40000이므로 2에도 5를 곱해 □ = 10이다. 쌀 10 kg을 살 수 있다.","scoring_points":["2：8000 = □：40000을 세웠는가","비례식의 성질로 10을 구했는가","비의 성질로 10을 구했는가"]},"explanation":["2：8000 = □：40000이에요.","2 × 40000 = 8000 × □ → □ = 10이에요.","8000 × 5 = 40000 → □ = 2 × 5 = 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#10','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 필요한 페인트를 □ L라 하면 4：48 = □：60이다. 4 × 60 = 48 × □ = 240이므로 □ = 5, 페인트는 5 L가 필요하다. 칠하는 넓이가 늘면 페인트의 양도 같은 비율로 늘기 때문에 비례식을 세울 수 있다.","scoring_points":["4：48 = □：60을 세웠는가","□ = 5(L)를 구했는가","두 양이 같은 비율로 변한다는 까닭을 썼는가"]},"explanation":["4：48 = □：60이에요.","4 × 60 = 240 = 48 × □ → □ = 5예요.","넓이와 페인트 양이 같은 비율로 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#1','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'sa','auto','삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 12개를 리엘이와 동생이 3：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["9"],"explanation":["비 3：1은 한 묶음이 3 + 1 = 4칸이에요.","앞쪽의 몫은 전체의 ⟨3/4⟩이에요.","12 × ⟨3/4⟩ = 9(개)예요."]},{"stem":"꿀떡 15개를 리엘이와 동생이 2：3으로 나누어 먹어요. 동생은 몇 개를 먹나요?","answer":["9"],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","15 × ⟨3/5⟩ = 9(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#2','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"12개","correct":true},{"t":"16개","mis":"M6-2-u4-X17"},{"t":"4개","mis":"M6-2-u4-X16"},{"t":"21개","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","28 × ⟨3/7⟩ = 12(개)예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 사과 35개를 땄어요. 가족 수의 비 3：4로 나누면 연아네 가족은 몇 개를 가지나요?","options":[{"t":"20개","correct":true},{"t":"15개","mis":"M6-2-u4-X17"},{"t":"5개","mis":"M6-2-u4-X16"},{"t":"25개","mis":"M6-2-u4-X20"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","35 × ⟨4/7⟩ = 20(개)예요."]},{"stem":"정후네 가족 5명과 연아네 가족 3명이 사과 24개를 땄어요. 가족 수의 비 5：3으로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"15개","correct":true},{"t":"9개","mis":"M6-2-u4-X17"},{"t":"3개","mis":"M6-2-u4-X16"},{"t":"40개","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","24 × ⟨5/8⟩ = 15(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#3','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."],"variant_rule":{"alt":[{"stem":"용돈 8000원을 학용품과 장난감을 사는 데 5：3으로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"1600원","mis":"M6-2-u4-X15"},{"t":"3000원","mis":"M6-2-u4-X17"},{"t":"1000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","8000 × ⟨5/8⟩ = 5000(원)예요."]},{"stem":"용돈 12000원을 학용품과 장난감을 사는 데 1：2로 나누어 써요. 장난감에 쓸 용돈은 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"6000원","mis":"M6-2-u4-X15"},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"24000원","mis":"M6-2-u4-X16"}],"explanation":["비 1：2는 한 묶음이 1 + 2 = 3칸이에요.","뒤쪽의 몫은 전체의 ⟨2/3⟩예요.","12000 × ⟨2/3⟩ = 8000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#4','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"수지와 형진이가 3600원짜리 장난감 값을 4：5로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1600원","correct":true},{"t":"900원","mis":"M6-2-u4-X15"},{"t":"2000원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"}],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨4/9⟩예요.","3600 × ⟨4/9⟩ = 1600(원)예요."]},{"stem":"수지와 형진이가 2000원짜리 장난감 값을 2：3으로 나누어 내요. 형진이는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"800원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"3000원","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","2000 × ⟨3/5⟩ = 1200(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#5','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'sa','auto','햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."],"variant_rule":{"alt":[{"stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 64장을 모둠원 수에 따라 나누면 달빛 모둠은 몇 장을 받나요?","answer":["24"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","뒤쪽의 몫은 전체의 ⟨3/8⟩이에요.","64 × ⟨3/8⟩ = 24(장)예요."]},{"stem":"햇빛 모둠은 4명, 달빛 모둠은 3명이에요. 색종이 56장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["32"],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨4/7⟩예요.","56 × ⟨4/7⟩ = 32(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#6','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."],"variant_rule":{"alt":[{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 2：3일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"24분","correct":true},{"t":"30분","mis":"M6-2-u4-X15"},{"t":"36분","mis":"M6-2-u4-X17"},{"t":"12분","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨2/5⟩예요.","60 × ⟨2/5⟩ = 24(분)예요."]},{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 3：7일 때 줄넘기를 한 시간은 몇 분인가요?","options":[{"t":"42분","correct":true},{"t":"18분","mis":"M6-2-u4-X17"},{"t":"6분","mis":"M6-2-u4-X16"},{"t":"140분","mis":"M6-2-u4-X16"}],"explanation":["비 3：7은 한 묶음이 3 + 7 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨7/10⟩이에요.","60 × ⟨7/10⟩ = 42(분)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#7','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."],"variant_rule":{"alt":[{"stem":"찰흙 350 g을 2：5로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"250 g","correct":true},{"t":"70 g","mis":"M6-2-u4-X15"},{"t":"100 g","mis":"M6-2-u4-X17"},{"t":"50 g","mis":"M6-2-u4-X16"}],"explanation":["비 2：5는 한 묶음이 2 + 5 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨5/7⟩예요.","350 × ⟨5/7⟩ = 250( g)예요."]},{"stem":"찰흙 360 g을 4：5로 나누어 거북과 악어를 만들어요. 거북을 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"160 g","correct":true},{"t":"90 g","mis":"M6-2-u4-X15"},{"t":"200 g","mis":"M6-2-u4-X17"},{"t":"40 g","mis":"M6-2-u4-X16"}],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨4/9⟩예요.","360 × ⟨4/9⟩ = 160( g)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#8','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#9','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','꿀떡 9개를 2：1로 나누면 각각 몇 개인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"꿀떡 9개를 2：1로 나누면 각각 몇 개인가요?","options":[{"t":"6개와 3개","correct":true},{"t":"3개와 6개","mis":"M6-2-u4-X17"},{"t":"9개와 0개","mis":"M6-2-u4-X20"},{"t":"6개와 6개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 2 + 1 = 3칸이에요.","9 × ⟨2/3⟩ = 6, 9 × ⟨1/3⟩ = 3이에요.","두 몫을 더하면 9 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 3：2로 나누면 각각 몇 개인가요?","options":[{"t":"12개와 8개","correct":true},{"t":"8개와 12개","mis":"M6-2-u4-X17"},{"t":"16개와 4개","mis":"M6-2-u4-X20"},{"t":"12개와 12개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 3 + 2 = 5칸이에요.","20 × ⟨3/5⟩ = 12, 20 × ⟨2/5⟩ = 8이에요.","두 몫을 더하면 20 — 전체와 같아요."]},{"stem":"스티커 30장을 1：4로 나누면 각각 몇 장인가요?","options":[{"t":"6장과 24장","correct":true},{"t":"24장과 6장","mis":"M6-2-u4-X17"},{"t":"12장과 18장","mis":"M6-2-u4-X20"},{"t":"6장과 30장","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 1 + 4 = 5칸이에요.","30 × ⟨1/5⟩ = 6, 30 × ⟨4/5⟩ = 24예요.","두 몫을 더하면 30 — 전체와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#10','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',3,'ox','auto','꿀떡 9개를 2：1로 나누면 리엘이는 9 ÷ 2개를 먹어요.',ARRAY['M6-2-u4-X15']::text[],true,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":3,"kind":"ox","stem":"꿀떡 9개를 2：1로 나누면 리엘이는 9 ÷ 2개를 먹어요.","answer":"X","reason_options":[{"t":"한 묶음이 2 + 1 = 3칸이라 9 × ⟨2/3⟩ = 6개를 먹기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"mis":"M6-2-u4-X15","explanation":["2：1은 한 묶음이 3칸이에요.","리엘이는 전체의 ⟨2/3⟩를 먹어요.","9 × ⟨2/3⟩ = 6 — 6개예요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 3：2로 나누면 앞쪽은 20 ÷ 3개를 가져요.","answer":"X","reason_options":[{"t":"한 묶음이 3 + 2 = 5칸이라 20 × ⟨3/5⟩ = 12개를 가지기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"explanation":["3：2는 한 묶음이 5칸이에요.","앞쪽은 전체의 ⟨3/5⟩을 가져요.","20 × ⟨3/5⟩ = 12 — 12개예요."]},{"stem":"사탕 24개를 1：3으로 나누면 앞쪽은 24 × ⟨1/4⟩ = 6개를 가져요.","answer":"O","reason_options":[{"t":"한 묶음이 1 + 3 = 4칸이라 앞쪽은 전체의 ⟨1/4⟩이기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"explanation":["1：3은 한 묶음이 4칸이에요.","앞쪽은 전체의 ⟨1/4⟩이에요.","24 × ⟨1/4⟩ = 6 — 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#1','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'sa','auto','연필 45자루를 형과 동생이 4：5로 나누어 가져요. 동생은 몇 자루를 가지나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"연필 45자루를 형과 동생이 4：5로 나누어 가져요. 동생은 몇 자루를 가지나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."],"variant_rule":{"alt":[{"stem":"연필 36자루를 형과 동생이 5：4로 나누어 가져요. 형은 몇 자루를 가지나요?","answer":["20"],"explanation":["비 5：4는 한 묶음이 5 + 4 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨5/9⟩예요.","36 × ⟨5/9⟩ = 20(자루)예요."]},{"stem":"연필 42자루를 형과 동생이 2：5로 나누어 가져요. 동생은 몇 자루를 가지나요?","answer":["30"],"explanation":["비 2：5는 한 묶음이 2 + 5 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨5/7⟩예요.","42 × ⟨5/7⟩ = 30(자루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#2','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'mc','auto','사탕 40개를 3：5로 나누면 각각 몇 개인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"사탕 40개를 3：5로 나누면 각각 몇 개인가요?","options":[{"t":"15개와 25개","correct":true},{"t":"25개와 15개","mis":"M6-2-u4-X17"},{"t":"20개와 20개","mis":"M6-2-u4-X20"},{"t":"15개와 30개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 3 + 5 = 8칸이에요.","40 × ⟨3/8⟩ = 15, 40 × ⟨5/8⟩ = 25예요.","두 몫을 더하면 40 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"사탕 48개를 5：3으로 나누면 각각 몇 개인가요?","options":[{"t":"30개와 18개","correct":true},{"t":"18개와 30개","mis":"M6-2-u4-X17"},{"t":"36개와 12개","mis":"M6-2-u4-X20"},{"t":"30개와 24개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 5 + 3 = 8칸이에요.","48 × ⟨5/8⟩ = 30, 48 × ⟨3/8⟩ = 18이에요.","두 몫을 더하면 48 — 전체와 같아요."]},{"stem":"사탕 63개를 4：3으로 나누면 각각 몇 개인가요?","options":[{"t":"36개와 27개","correct":true},{"t":"27개와 36개","mis":"M6-2-u4-X17"},{"t":"45개와 18개","mis":"M6-2-u4-X20"},{"t":"36개와 36개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 4 + 3 = 7칸이에요.","63 × ⟨4/7⟩ = 36, 63 × ⟨3/7⟩ = 27이에요.","두 몫을 더하면 63 — 전체와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#3','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','어떤 수를 3：4로 비례배분했더니 작은 쪽이 18이 되었어요. 처음 수는 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"어떤 수를 3：4로 비례배분했더니 작은 쪽이 18이 되었어요. 처음 수는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"24","mis":"M6-2-u4-X17"},{"t":"54","mis":"M6-2-u4-X15"},{"t":"72","mis":"M6-2-u4-X16"}],"explanation":["3：4에서 작은 쪽은 한 묶음 7칸 가운데 3칸이에요.","3칸이 18이니 1칸은 6이에요.","전체 7칸은 42예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 2：5로 비례배분했더니 작은 쪽이 14가 되었어요. 처음 수는 얼마인가요?","options":[{"t":"49","correct":true},{"t":"35","mis":"M6-2-u4-X17"},{"t":"28","mis":"M6-2-u4-X15"},{"t":"70","mis":"M6-2-u4-X16"}],"explanation":["2：5에서 작은 쪽은 한 묶음 7칸 가운데 2칸이에요.","2칸이 14니 1칸은 7이에요.","전체 7칸은 49예요."]},{"stem":"어떤 수를 5：3으로 비례배분했더니 작은 쪽이 21이 되었어요. 처음 수는 얼마인가요?","options":[{"t":"56","correct":true},{"t":"35","mis":"M6-2-u4-X17"},{"t":"63","mis":"M6-2-u4-X15"},{"t":"105","mis":"M6-2-u4-X16"}],"explanation":["5：3에서 작은 쪽은 한 묶음 8칸 가운데 3칸이에요.","3칸이 21이니 1칸은 7이에요.","전체 8칸은 56이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#4','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','용돈을 형과 동생이 5：3으로 나누었더니 형이 동생보다 2000원 더 많았어요. 처음 용돈은 모두 얼마인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"용돈을 형과 동생이 5：3으로 나누었더니 형이 동생보다 2000원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"10000원","mis":"M6-2-u4-X15"},{"t":"5000원","mis":"M6-2-u4-X17"},{"t":"16000원","mis":"M6-2-u4-X20"}],"explanation":["형은 5칸, 동생은 3칸 — 2칸만큼 차이가 나요.","2칸이 2000원이니 1칸은 1000원이에요.","전체 8칸은 8000원이에요."],"variant_rule":{"alt":[{"stem":"용돈을 형과 동생이 4：1로 나누었더니 형이 동생보다 3000원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"12000원","mis":"M6-2-u4-X15"},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"10000원","mis":"M6-2-u4-X20"}],"explanation":["형은 4칸, 동생은 1칸 — 3칸만큼 차이가 나요.","3칸이 3000원이니 1칸은 1000원이에요.","전체 5칸은 5000원이에요."]},{"stem":"용돈을 형과 동생이 7：4로 나누었더니 형이 동생보다 1500원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"5500원","correct":true},{"t":"10500원","mis":"M6-2-u4-X15"},{"t":"3500원","mis":"M6-2-u4-X17"},{"t":"11000원","mis":"M6-2-u4-X20"}],"explanation":["형은 7칸, 동생은 4칸 — 3칸만큼 차이가 나요.","3칸이 1500원이니 1칸은 500원이에요.","전체 11칸은 5500원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#5','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'ox','auto','전체를 가：나로 비례배분하면 두 몫의 합은 언제나 전체와 같아요.',ARRAY['M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":3,"kind":"ox","stem":"전체를 가：나로 비례배분하면 두 몫의 합은 언제나 전체와 같아요.","answer":"O","reason_options":[{"t":"전체를 (가+나)칸으로 갈라 가칸과 나칸으로 나누기 때문에","correct":true},{"t":"가 × 나만큼 나누기 때문에","mis":"M6-2-u4-X16"}],"mis":"M6-2-u4-X16","explanation":["비례배분은 전체를 (가+나)칸으로 갈라요.","두 몫은 가칸과 나칸이에요.","가칸 + 나칸 = (가+나)칸 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"24를 1：3으로 비례배분하면 24 × ⟨1/3⟩ = 8과 나머지 16이에요.","answer":"X","reason_options":[{"t":"한 묶음이 1 + 3 = 4칸이라 24 × ⟨1/4⟩ = 6과 18이기 때문에","correct":true},{"t":"(가 ÷ 나)를 곱해 앞쪽 몫을 구하기 때문에","mis":"M6-2-u4-X16"}],"explanation":["1：3은 한 묶음이 4칸이에요.","앞쪽은 ⟨1/4⟩, 뒤쪽은 ⟨3/4⟩이에요.","24 × ⟨1/4⟩ = 6, 24 × ⟨3/4⟩ = 18이에요."]},{"stem":"35를 2：5로 비례배분하면 35 × ⟨2/5⟩ = 14와 나머지 21이에요.","answer":"X","reason_options":[{"t":"한 묶음이 2 + 5 = 7칸이라 35 × ⟨2/7⟩ = 10과 25이기 때문에","correct":true},{"t":"(가 ÷ 나)를 곱해 앞쪽 몫을 구하기 때문에","mis":"M6-2-u4-X16"}],"explanation":["2：5는 한 묶음이 7칸이에요.","앞쪽은 ⟨2/7⟩, 뒤쪽은 ⟨5/7⟩예요.","35 × ⟨2/7⟩ = 10, 35 × ⟨5/7⟩ = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#6','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','구슬 60개를 세 사람이 1：2：3으로 나누어 가져요. 셋째 사람은 몇 개를 가지나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"구슬 60개를 세 사람이 1：2：3으로 나누어 가져요. 셋째 사람은 몇 개를 가지나요?","options":[{"t":"30개","correct":true},{"t":"20개","mis":"M6-2-u4-X15"},{"t":"10개","mis":"M6-2-u4-X16"},{"t":"40개","mis":"M6-2-u4-X20"}],"explanation":["1：2：3은 한 묶음이 6칸이에요.","셋째 사람은 3칸 — 전체의 ⟨3/6⟩이에요.","60 × ⟨3/6⟩ = 30(개)예요."],"variant_rule":{"alt":[{"stem":"구슬 48개를 세 사람이 1：3：4로 나누어 가져요. 둘째 사람은 몇 개를 가지나요?","options":[{"t":"18개","correct":true},{"t":"16개","mis":"M6-2-u4-X15"},{"t":"6개","mis":"M6-2-u4-X16"},{"t":"24개","mis":"M6-2-u4-X20"}],"explanation":["1：3：4는 한 묶음이 8칸이에요.","둘째 사람은 3칸 — 전체의 ⟨3/8⟩이에요.","48 × ⟨3/8⟩ = 18(개)예요."]},{"stem":"구슬 72개를 세 사람이 2：3：4로 나누어 가져요. 첫째 사람은 몇 개를 가지나요?","options":[{"t":"16개","correct":true},{"t":"24개","mis":"M6-2-u4-X15"},{"t":"8개","mis":"M6-2-u4-X16"},{"t":"36개","mis":"M6-2-u4-X15"}],"explanation":["2：3：4는 한 묶음이 9칸이에요.","첫째 사람은 2칸 — 전체의 ⟨2/9⟩예요.","72 × ⟨2/9⟩ = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#7','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'match','auto','20을 비례배분했을 때 앞쪽 몫을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":3,"kind":"match","stem":"20을 비례배분했을 때 앞쪽 몫을 이으세요.","pairs":[{"l":"20을 1：4로","r":"4"},{"l":"20을 2：3으로","r":"8"},{"l":"20을 3：1로","r":"15"}],"mis":"M6-2-u4-X16","explanation":["1：4는 5칸 — 20 × ⟨1/5⟩ = 4예요.","2：3은 5칸 — 20 × ⟨2/5⟩ = 8이에요.","3：1은 4칸 — 20 × ⟨3/4⟩ = 15예요."],"variant_rule":{"alt":[{"stem":"30을 비례배분했을 때 앞쪽 몫을 이으세요.","pairs":[{"l":"30을 1：2로","r":"10"},{"l":"30을 3：2로","r":"18"},{"l":"30을 1：5로","r":"5"}],"explanation":["1：2는 3칸 — 30 × ⟨1/3⟩ = 10이에요.","3：2는 5칸 — 30 × ⟨3/5⟩ = 18이에요.","1：5는 6칸 — 30 × ⟨1/6⟩ = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#8','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'mc','auto','둘레가 48 cm인 직사각형의 가로와 세로의 비가 5：3이에요. 가로는 몇 cm인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":4,"kind":"mc","stem":"둘레가 48 cm인 직사각형의 가로와 세로의 비가 5：3이에요. 가로는 몇 cm인가요?","options":[{"t":"15 cm","correct":true},{"t":"30 cm","mis":"M6-2-u4-X20"},{"t":"9 cm","mis":"M6-2-u4-X17"},{"t":"3 cm","mis":"M6-2-u4-X16"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 48 ÷ 2 = 24 (cm)예요.","24를 5：3으로 비례배분해요.","24 × ⟨5/8⟩ = 15 (cm)예요."],"variant_rule":{"alt":[{"stem":"둘레가 56 cm인 직사각형의 가로와 세로의 비가 3：4예요. 세로는 몇 cm인가요?","options":[{"t":"16 cm","correct":true},{"t":"32 cm","mis":"M6-2-u4-X20"},{"t":"12 cm","mis":"M6-2-u4-X17"},{"t":"7 cm","mis":"M6-2-u4-X15"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 56 ÷ 2 = 28 (cm)예요.","28을 3：4로 비례배분해요.","28 × ⟨4/7⟩ = 16 (cm)예요."]},{"stem":"둘레가 60 cm인 직사각형의 가로와 세로의 비가 7：3이에요. 가로는 몇 cm인가요?","options":[{"t":"21 cm","correct":true},{"t":"42 cm","mis":"M6-2-u4-X20"},{"t":"9 cm","mis":"M6-2-u4-X17"},{"t":"3 cm","mis":"M6-2-u4-X16"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 60 ÷ 2 = 30 (cm)예요.","30을 7：3으로 비례배분해요.","30 × ⟨7/10⟩ = 21 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#9','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','1200을 2：3으로 비례배분하려는데 친구가 1200 ÷ 2 = 600으로 계산했어요. 이 방법이 왜 잘못되었는지 쓰고, 바르게 비례배분해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"1200을 2：3으로 비례배분하려는데 친구가 1200 ÷ 2 = 600으로 계산했어요. 이 방법이 왜 잘못되었는지 쓰고, 바르게 비례배분해 보세요.","answer_guide":{"answer":"예: 2：3은 한 묶음이 2 + 3 = 5칸이라는 뜻이어서 전체를 5칸으로 갈라야 한다. 1200 ÷ 2는 한 항으로만 나눈 것이다. 바르게 하면 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이다.","scoring_points":["한 묶음이 5칸임을 밝혔는가","480을 구했는가","720을 구했는가"]},"explanation":["2：3은 5칸이에요.","1200 × ⟨2/5⟩ = 480이에요.","1200 × ⟨3/5⟩ = 720이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#10','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비로 나누면 두 가족이 각각 몇 개씩 가지는지 구하고, 구한 두 몫이 맞는지 확인하는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비로 나누면 두 가족이 각각 몇 개씩 가지는지 구하고, 구한 두 몫이 맞는지 확인하는 방법을 써 보세요.","answer_guide":{"answer":"예: 3：4는 한 묶음이 7칸이므로 정후네는 28 × ⟨3/7⟩ = 12개, 연아네는 28 × ⟨4/7⟩ = 16개이다. 두 몫을 더하면 28로 전체와 같고, 12：16을 4로 나누면 3：4가 되어 맞다.","scoring_points":["12개를 구했는가","16개를 구했는가","합이 28·비가 3：4임으로 확인했는가"]},"explanation":["3：4는 7칸이에요.","28 × ⟨3/7⟩ = 12, 28 × ⟨4/7⟩ = 16이에요.","12 + 16 = 28, 12：16 = 3：4로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#1','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"150000원","correct":true},{"t":"350000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"200000원","mis":"M6-2-u4-X20"}],"explanation":["비 7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨3/10⟩이에요.","500000 × ⟨3/10⟩ = 150000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"180000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"420000원","mis":"M6-2-u4-X17"},{"t":"60000원","mis":"M6-2-u4-X16"}],"explanation":["비 7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨3/10⟩이에요.","600000 × ⟨3/10⟩ = 180000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"160000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"240000원","mis":"M6-2-u4-X17"},{"t":"80000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨2/5⟩예요.","400000 × ⟨2/5⟩ = 160000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#2','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리는 12000원, 동하는 8000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":2,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리는 12000원, 동하는 8000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"6000：4000","mis":"M6-2-u4-X05"},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：8000","mis":"M6-2-u4-X02"}],"explanation":["12000과 8000의 최대공약수는 4000이에요.","전항과 후항을 똑같이 4000으로 나누면 3：2예요.","3과 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"태리는 10000원, 동하는 6000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"5000：3000","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：6000","mis":"M6-2-u4-X02"}],"explanation":["10000과 6000의 최대공약수는 2000이에요.","전항과 후항을 똑같이 2000으로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"태리는 15000원, 동하는 6000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"7500：3000","mis":"M6-2-u4-X05"},{"t":"2：5","mis":"M6-2-u4-X03"},{"t":"5：6000","mis":"M6-2-u4-X02"}],"explanation":["15000과 6000의 최대공약수는 3000이에요.","전항과 후항을 똑같이 3000으로 나누면 5：2예요.","5와 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#3','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','두 친구가 얻은 150000원을 낸 사용료의 비 3：2로 나누면 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"두 친구가 얻은 150000원을 낸 사용료의 비 3：2로 나누면 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 160000원을 낸 사용료의 비 5：3으로 나누면 태리는 몇 원을 받나요?","options":[{"t":"100000원","correct":true},{"t":"32000원","mis":"M6-2-u4-X15"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","160000 × ⟨5/8⟩ = 100000(원)예요."]},{"stem":"두 친구가 얻은 180000원을 낸 사용료의 비 5：4로 나누면 태리는 몇 원을 받나요?","options":[{"t":"100000원","correct":true},{"t":"36000원","mis":"M6-2-u4-X15"},{"t":"80000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：4는 한 묶음이 5 + 4 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨5/9⟩예요.","180000 × ⟨5/9⟩ = 100000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#4','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리는 그림 4장, 동하는 2장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":4,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리는 그림 4장, 동하는 2장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：2","mis":"M6-2-u4-X02"},{"t":"4：1","mis":"M6-2-u4-X02"}],"explanation":["4와 2의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"태리는 그림 6장, 동하는 4장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：4","mis":"M6-2-u4-X02"},{"t":"6：2","mis":"M6-2-u4-X02"}],"explanation":["6과 4의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 3：2예요.","3과 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"태리는 그림 8장, 동하는 6장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：3","correct":true},{"t":"3：4","mis":"M6-2-u4-X03"},{"t":"4：6","mis":"M6-2-u4-X02"},{"t":"8：3","mis":"M6-2-u4-X02"}],"explanation":["8과 6의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 4：3이에요.","4와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#5','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','두 친구가 얻은 150000원을 그린 그림 수의 비 2：1로 나누면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 얻은 150000원을 그린 그림 수의 비 2：1로 나누면 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"150000원","mis":"M6-2-u4-X15"},{"t":"100000원","mis":"M6-2-u4-X17"},{"t":"75000원","mis":"M6-2-u4-X16"}],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽의 몫은 전체의 ⟨1/3⟩이에요.","150000 × ⟨1/3⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 150000원을 그린 그림 수의 비 3：2로 나누면 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"75000원","mis":"M6-2-u4-X15"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨2/5⟩예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"두 친구가 얻은 140000원을 그린 그림 수의 비 4：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"80000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"},{"t":"105000원","mis":"M6-2-u4-X16"}],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨3/7⟩이에요.","140000 × ⟨3/7⟩ = 60000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#6','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M6-2-u4-X19','M6-2-u4-X17']::text[],true,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 90000원, 그림 수의 비로 나누면 100000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 90000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 3：2 — 태리 90000원, 동하 60000원이에요.","그림 수의 비 2：1 — 태리 100000원, 동하 50000원이에요.","나누는 비가 달라 결과도 달라요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 160000원을 낸 사용료(태리 10000원, 동하 6000원)의 비와 그린 그림 수(태리 6장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 100000원, 그림 수의 비로 나누면 120000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 100000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 5：3 — 태리 100000원, 동하 60000원이에요.","그림 수의 비 3：1 — 태리 120000원, 동하 40000원이에요.","나누는 비가 달라 결과도 달라요."]},{"stem":"두 친구가 받은 180000원을 낸 사용료(태리 8000원, 동하 4000원)의 비와 그린 그림 수(태리 5장, 동하 4장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 120000원, 그림 수의 비로 나누면 100000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 120000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 2：1 — 태리 120000원, 동하 60000원이에요.","그림 수의 비 5：4 — 태리 100000원, 동하 80000원이에요.","나누는 비가 달라 결과도 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#7','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'sa','auto','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":2,"kind":"sa","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?","answer":["25"],"explanation":["낸 금액의 비 1500：600을 간단히 하면 5：2예요.","한 묶음은 7칸 — 전체의 ⟨5/7⟩예요.","35 × ⟨5/7⟩ = 25(장)예요."],"variant_rule":{"alt":[{"stem":"다현이가 1200원, 윤수가 800원을 내서 도화지 40장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?","answer":["24"],"explanation":["낸 금액의 비 1200：800을 간단히 하면 3：2예요.","한 묶음은 5칸 — 전체의 ⟨3/5⟩이에요.","40 × ⟨3/5⟩ = 24(장)예요."]},{"stem":"다현이가 2000원, 윤수가 1000원을 내서 도화지 36장을 샀어요. 낸 금액의 비로 나누면 윤수는 몇 장을 가져야 하나요?","answer":["12"],"explanation":["낸 금액의 비 2000：1000을 간단히 하면 2：1이에요.","한 묶음은 3칸 — 전체의 ⟨1/3⟩이에요.","36 × ⟨1/3⟩ = 12(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#8','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":8,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#9','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"나누는 방법이 달라도 각자 받는 금액은 언제나 같다","correct":true},{"t":"작품에 낸 금액만큼 나누면 공정하다고 생각할 수 있다","mis":"M6-2-u4-X19"},{"t":"그린 그림 수만큼 나누면 공정하다고 생각할 수 있다","mis":"M6-2-u4-X19"},{"t":"어느 방법이 공정한지는 사람마다 생각이 다를 수 있다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"낸 금액이 많은 사람은 언제나 그림도 많이 그린다","correct":true},{"t":"낸 금액의 비로 나누는 방법이 있다","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비로 나누는 방법이 있다","mis":"M6-2-u4-X19"},{"t":"나누기 전에 기준을 함께 정하면 좋다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"비례배분을 하면 두 사람의 몫은 언제나 똑같다","correct":true},{"t":"비가 다르면 두 사람의 몫도 달라진다","mis":"M6-2-u4-X19"},{"t":"어떤 기준으로 나눌지 먼저 정해야 한다","mis":"M6-2-u4-X19"},{"t":"두 사람의 몫을 더하면 나눈 전체 금액이 된다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#10','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',3,'ox','auto','두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 동하가 태리보다 많이 받아요.',ARRAY['M6-2-u4-X17']::text[],true,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":3,"kind":"ox","stem":"두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 동하가 태리보다 많이 받아요.","answer":"X","reason_options":[{"t":"4：2 = 2：1이라 태리 100000원, 동하 50000원이기 때문에","correct":true},{"t":"그림 수가 적을수록 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"mis":"M6-2-u4-X17","explanation":["4：2를 간단히 하면 2：1이에요.","태리는 150000 × ⟨2/3⟩ = 100000(원)이에요.","동하는 50000원 — 태리가 더 많이 받아요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누면 동하가 태리보다 많이 받아요.","answer":"X","reason_options":[{"t":"12000：8000 = 3：2라 태리 90000원, 동하 60000원이기 때문에","correct":true},{"t":"사용료를 적게 낸 사람이 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"explanation":["12000：8000을 간단히 하면 3：2예요.","태리는 150000 × ⟨3/5⟩ = 90000(원)이에요.","동하는 60000원 — 태리가 더 많이 받아요."]},{"stem":"두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 태리가 동하의 2배를 받아요.","answer":"O","reason_options":[{"t":"4：2 = 2：1이라 태리 100000원, 동하 50000원이기 때문에","correct":true},{"t":"그림 수가 적을수록 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"explanation":["4：2를 간단히 하면 2：1이에요.","태리 100000원, 동하 50000원이에요.","100000은 50000의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#1','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":1,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"150000원","correct":true},{"t":"600000원","mis":"M6-2-u4-X18"},{"t":"50000원","mis":"M6-2-u4-X17"},{"t":"200000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨3/4⟩ = 150000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 900000원을 회사와 사용자가 2：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 6000원, 동하 4000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"180000원","correct":true},{"t":"540000원","mis":"M6-2-u4-X18"},{"t":"120000원","mis":"M6-2-u4-X17"},{"t":"300000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 900000 × ⟨1/3⟩ = 300000(원)예요.","6000원：4000원을 간단히 하면 3：2예요.","300000 × ⟨3/5⟩ = 180000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#2','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',2,'mc','auto','두 친구가 얻은 200000원을 낸 사용료의 비 3：1로 나누면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 얻은 200000원을 낸 사용료의 비 3：1로 나누면 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["비 3：1은 한 묶음이 3 + 1 = 4칸이에요.","뒤쪽의 몫은 전체의 ⟨1/4⟩이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 210000원을 낸 사용료의 비 4：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"70000원","mis":"M6-2-u4-X15"},{"t":"120000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨3/7⟩이에요.","210000 × ⟨3/7⟩ = 90000(원)예요."]},{"stem":"두 친구가 얻은 240000원을 낸 사용료의 비 5：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"80000원","mis":"M6-2-u4-X15"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","뒤쪽의 몫은 전체의 ⟨3/8⟩이에요.","240000 × ⟨3/8⟩ = 90000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#3','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','두 친구가 받은 150000원을 나눌 때 태리(사용료 12000원·그림 4장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 2장이에요.',ARRAY['M6-2-u4-X17','M6-2-u4-X19','M6-2-u4-X20']::text[],true,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"두 친구가 받은 150000원을 나눌 때 태리(사용료 12000원·그림 4장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 2장이에요.","options":[{"t":"그린 그림 수의 비 — 10000원 더 많이 받아요","correct":true},{"t":"낸 사용료의 비 — 10000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비 — 20000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 90000원이에요.","그림 수의 비로 나누면 태리는 100000원이에요.","그린 그림 수의 비로 나눌 때 10000원 더 많아요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 160000원을 나눌 때 태리(사용료 6000원·그림 5장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 10000원·그림 3장이에요.","options":[{"t":"그린 그림 수의 비 — 40000원 더 많이 받아요","correct":true},{"t":"낸 사용료의 비 — 40000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비 — 80000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 60000원이에요.","그림 수의 비로 나누면 태리는 100000원이에요.","그린 그림 수의 비로 나눌 때 40000원 더 많아요."]},{"stem":"두 친구가 받은 180000원을 나눌 때 태리(사용료 10000원·그림 2장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 4장이에요.","options":[{"t":"낸 사용료의 비 — 40000원 더 많이 받아요","correct":true},{"t":"그린 그림 수의 비 — 40000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"낸 사용료의 비 — 80000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 100000원이에요.","그림 수의 비로 나누면 태리는 60000원이에요.","낸 사용료의 비로 나눌 때 40000원 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#4','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','두 친구가 받은 150000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X18','M6-2-u4-X05']::text[],true,'{"seq":4,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"두 친구가 받은 150000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"5：2","mis":"M6-2-u4-X18"},{"t":"9：6","mis":"M6-2-u4-X05"}],"explanation":["태리는 150000 − 60000 = 90000(원)을 받았어요.","태리：동하 = 90000：60000이에요.","간단히 하면 3：2예요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 150000원 가운데 동하가 50000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X18"},{"t":"10：5","mis":"M6-2-u4-X05"}],"explanation":["태리는 150000 − 50000 = 100000(원)을 받았어요.","태리：동하 = 100000：50000이에요.","간단히 하면 2：1이에요."]},{"stem":"두 친구가 받은 160000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"8：3","mis":"M6-2-u4-X18"},{"t":"10：6","mis":"M6-2-u4-X05"}],"explanation":["태리는 160000 − 60000 = 100000(원)을 받았어요.","태리：동하 = 100000：60000이에요.","간단히 하면 5：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#5','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','세 사람이 3000원, 2000원, 1000원을 내어 얻은 수익 120000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"세 사람이 3000원, 2000원, 1000원을 내어 얻은 수익 120000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"40000원","mis":"M6-2-u4-X15"},{"t":"20000원","mis":"M6-2-u4-X16"},{"t":"120000원","mis":"M6-2-u4-X20"}],"explanation":["3000원：2000원：1000원을 간단히 하면 3：2：1이에요.","한 묶음은 6칸 — 첫째 사람은 3칸이에요.","120000 × ⟨3/6⟩ = 60000(원)예요."],"variant_rule":{"alt":[{"stem":"세 사람이 4000원, 3000원, 2000원을 내어 얻은 수익 90000원을 낸 금액의 비로 나누어요. 돈을 둘째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"30000원","correct":true},{"t":"10000원","mis":"M6-2-u4-X16"},{"t":"60000원","mis":"M6-2-u4-X20"},{"t":"40000원","mis":"M6-2-u4-X20"}],"explanation":["4000원：3000원：2000원을 간단히 하면 4：3：2예요.","한 묶음은 9칸 — 둘째 사람은 3칸이에요.","90000 × ⟨3/9⟩ = 30000(원)예요."]},{"stem":"세 사람이 5000원, 3000원, 2000원을 내어 얻은 수익 150000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"75000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"15000원","mis":"M6-2-u4-X16"},{"t":"150000원","mis":"M6-2-u4-X20"}],"explanation":["5000원：3000원：2000원을 간단히 하면 5：3：2예요.","한 묶음은 10칸 — 첫째 사람은 5칸이에요.","150000 × ⟨5/10⟩ = 75000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#6','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'ox','auto','전체 수익 500000원을 바로 낸 사용료의 비 3：2로 나누면 태리의 몫 90000원을 구할 수 있어요.',ARRAY['M6-2-u4-X18']::text[],true,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":3,"kind":"ox","stem":"전체 수익 500000원을 바로 낸 사용료의 비 3：2로 나누면 태리의 몫 90000원을 구할 수 있어요.","answer":"X","reason_options":[{"t":"먼저 회사와 7：3으로 나눈 두 친구의 몫 150000원을 3：2로 나누어야 하기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"mis":"M6-2-u4-X18","explanation":["500000원을 바로 3：2로 나누면 태리는 300000원이 되어 버려요.","먼저 두 친구의 몫 500000 × ⟨3/10⟩ = 150000(원)을 구해요.","150000 × ⟨3/5⟩ = 90000(원)이에요."],"variant_rule":{"alt":[{"stem":"전체 수익 500000원을 바로 그린 그림 수의 비 2：1로 나누면 태리의 몫 100000원을 구할 수 있어요.","answer":"X","reason_options":[{"t":"먼저 회사와 7：3으로 나눈 두 친구의 몫 150000원을 2：1로 나누어야 하기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"explanation":["500000원을 바로 2：1로 나누면 태리는 약 333333원이 되어 버려요.","먼저 두 친구의 몫 150000원을 구해요.","150000 × ⟨2/3⟩ = 100000(원)이에요."]},{"stem":"두 번 나누는 문제에서는 먼저 전체에서 두 친구의 몫을 구한 뒤 그 몫을 두 친구의 비로 나누어요.","answer":"O","reason_options":[{"t":"두 친구가 나누는 것은 전체가 아니라 회사 몫을 뺀 두 친구의 몫이기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"explanation":["전체 수익은 먼저 회사와 사용자가 나눠요.","두 친구는 사용자 몫만 나누어 가져요.","그래서 두 단계로 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#7','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'match','auto','나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 150000원).','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":3,"kind":"match","stem":"나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 150000원).","pairs":[{"l":"낸 사용료의 비 3：2","r":"90000원"},{"l":"그린 그림 수의 비 2：1","r":"100000원"},{"l":"똑같이 1：1","r":"75000원"}],"mis":"M6-2-u4-X17","explanation":["150000 × ⟨3/5⟩ = 90000(원)이에요.","150000 × ⟨2/3⟩ = 100000(원)이에요.","150000 × ⟨1/2⟩ = 75000(원)이에요."],"variant_rule":{"alt":[{"stem":"나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 120000원).","pairs":[{"l":"낸 사용료의 비 5：3","r":"75000원"},{"l":"그린 그림 수의 비 1：1","r":"60000원"},{"l":"참여한 시간의 비 3：1","r":"90000원"}],"explanation":["120000 × ⟨5/8⟩ = 75000(원)이에요.","120000 × ⟨1/2⟩ = 60000(원)이에요.","120000 × ⟨3/4⟩ = 90000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#8','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'mc','auto','두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20','M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?","options":[{"t":"55000원","correct":true},{"t":"95000원","mis":"M6-2-u4-X17"},{"t":"110000원","mis":"M6-2-u4-X20"},{"t":"60000원","mis":"M6-2-u4-X19"}],"explanation":["동하의 두 몫은 60000원과 50000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(60000 + 50000) ÷ 2 = 55000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 태리는 몇 원을 받나요?","options":[{"t":"95000원","correct":true},{"t":"55000원","mis":"M6-2-u4-X17"},{"t":"190000원","mis":"M6-2-u4-X20"},{"t":"90000원","mis":"M6-2-u4-X19"}],"explanation":["태리의 두 몫은 90000원과 100000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(90000 + 100000) ÷ 2 = 95000(원)예요."]},{"stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 75000원·동하 45000원, 그림 수의 비로 나누면 태리 80000원·동하 40000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?","options":[{"t":"42500원","correct":true},{"t":"77500원","mis":"M6-2-u4-X17"},{"t":"85000원","mis":"M6-2-u4-X20"},{"t":"45000원","mis":"M6-2-u4-X19"}],"explanation":["동하의 두 몫은 45000원과 40000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(45000 + 40000) ÷ 2 = 42500(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#9','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','태리와 동하의 협동 작품 수익 500000원을 회사와 사용자가 7：3으로 나눠요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 보고, 어느 방법이 더 공정하다고 생각하는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하의 협동 작품 수익 500000원을 회사와 사용자가 7：3으로 나눠요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 보고, 어느 방법이 더 공정하다고 생각하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000원이다. 사용료의 비 3：2로 나누면 태리 90000원, 동하 60000원이고, 그림 수의 비 2：1로 나누면 태리 100000원, 동하 50000원이다. (예) 그림을 많이 그린 노력이 작품에 더 크게 들어갔으므로 그림 수의 비가 공정하다고 생각한다 — 또는 돈을 낸 만큼 나누는 사용료의 비가 공정하다고 볼 수도 있다.","scoring_points":["두 친구의 몫 150000원을 구했는가","두 방법의 몫을 모두 바르게 구했는가","자기 생각과 그 까닭을 썼는가"]},"explanation":["먼저 150000원을 구해요.","사용료 비 → 90000·60000, 그림 수 비 → 100000·50000이에요.","어느 쪽이 공정한지는 까닭을 들어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#10','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 도화지를 나누는 과정을 쓰고, 두 사람이 똑같이 나누는 것과 견주어 어느 쪽이 공정한지 생각을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 도화지를 나누는 과정을 쓰고, 두 사람이 똑같이 나누는 것과 견주어 어느 쪽이 공정한지 생각을 써 보세요.","answer_guide":{"answer":"예: 1500：600을 간단히 하면 5：2이고 한 묶음은 7칸이다. 다현이는 35 × ⟨5/7⟩ = 25장, 윤수는 35 × ⟨2/7⟩ = 10장이다. 똑같이 나누면 17장과 18장으로 딱 나누어지지 않고 돈을 더 낸 다현이에게 불리하므로 낸 금액의 비로 나누는 것이 공정하다고 생각한다.","scoring_points":["5：2로 간단히 했는가","25장과 10장을 구했는가","똑같이 나누는 것과 견주어 자기 생각을 썼는가"]},"explanation":["1500：600 = 5：2예요.","35 × ⟨5/7⟩ = 25, 35 × ⟨2/7⟩ = 10이에요.","낸 만큼 나누는 방법을 견주어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#1','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',1,'sa','auto','3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."],"variant_rule":{"alt":[{"stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."]},{"stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#2','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',1,'sa','auto','35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."],"variant_rule":{"alt":[{"stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."]},{"stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#3','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',2,'mc','auto','2：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#4','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',3,'ox','auto','2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#5','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C2',1,'mc','auto','54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#6','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C2',2,'mc','auto','84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#7','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C3',1,'sa','auto','0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."],"variant_rule":{"alt":[{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]},{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#8','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C3',2,'mc','auto','2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]},{"stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#9','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',2,'mc','auto','⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]},{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#10','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',3,'mc','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."],"variant_rule":{"alt":[{"stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."]},{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#11','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 8：7 = 24：21에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."],"variant_rule":{"alt":[{"stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."]},{"stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#12','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#13','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',3,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]},{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#14','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]},{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#15','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',2,'sa','auto','4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."],"variant_rule":{"alt":[{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]},{"stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#16','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',3,'mc','auto','8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."],"variant_rule":{"alt":[{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]},{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#17','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',1,'sa','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."],"variant_rule":{"alt":[{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."]},{"stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#18','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',2,'mc','auto','어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."],"variant_rule":{"alt":[{"stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."]},{"stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#19','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',3,'mc','auto','쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."],"variant_rule":{"alt":[{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]},{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#20','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',1,'sa','auto','꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."]},{"stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#21','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',2,'mc','auto','찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."],"variant_rule":{"alt":[{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."]},{"stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#22','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',3,'mc','auto','1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#23','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#24','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 4장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 4장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000원이다. 사용료의 비 3：2로 나누면 태리 90000원, 동하 60000원이다. 그림 수의 비 2：1로 나누면 태리 100000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 150000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 150000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#25','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',4,'essay','teacher','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 9：4 = □：12이다. ① 외항의 곱과 내항의 곱이 같으므로 9 × 12 = 4 × □, □ = 27이다. ② 후항에 3을 곱했으므로 전항에도 3을 곱해 □ = 27이다.","scoring_points":["9：4 = □：12를 세웠는가","비례식의 성질로 27을 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["9：4 = □：12예요.","9 × 12 = 4 × □ → □ = 27이에요.","3배 해도 □ = 27이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#1','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',1,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."]},{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#2','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',1,'sa','auto','45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."],"variant_rule":{"alt":[{"stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."]},{"stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#3','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',2,'mc','auto','4：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#4','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',3,'ox','auto','3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."]},{"stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#5','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C2',1,'mc','auto','28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#6','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C2',2,'mc','auto','48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#7','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',1,'sa','auto','3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."],"variant_rule":{"alt":[{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]},{"stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#8','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',2,'mc','auto','1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."],"variant_rule":{"alt":[{"stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]},{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#9','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C4',2,'mc','auto','⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]},{"stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#10','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C4',3,'mc','auto','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."],"variant_rule":{"alt":[{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]},{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#11','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 56：21 = 8：3에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."]},{"stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#12','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#13','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',3,'mc','auto','3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]},{"stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#14','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]},{"stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#15','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',2,'sa','auto','10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."],"variant_rule":{"alt":[{"stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."]},{"stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#16','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',3,'mc','auto','4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."],"variant_rule":{"alt":[{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]},{"stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#17','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',1,'sa','auto','계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."],"variant_rule":{"alt":[{"stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."]},{"stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#18','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',2,'mc','auto','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14','M6-2-u4-X12']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."],"variant_rule":{"alt":[{"stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."]},{"stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#19','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',3,'mc','auto','전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."],"variant_rule":{"alt":[{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]},{"stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#20','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',1,'sa','auto','색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."],"variant_rule":{"alt":[{"stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]},{"stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#21','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',2,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."],"variant_rule":{"alt":[{"stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."]},{"stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#22','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',3,'mc','auto','1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#23','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#24','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 10000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 6장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 10000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 6장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000원이다. 사용료의 비 5：3으로 나누면 태리 112500원, 동하 67500원이다. 그림 수의 비 3：1로 나누면 태리 135000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 180000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 180000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#25','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',4,'essay','teacher','쌀 2 kg으로 떡 3판을 만들 수 있어요. 떡 12판을 만들려면 쌀이 몇 kg 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"쌀 2 kg으로 떡 3판을 만들 수 있어요. 떡 12판을 만들려면 쌀이 몇 kg 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 2：3 = □：12이다. ① 외항의 곱과 내항의 곱이 같으므로 2 × 12 = 3 × □, □ = 8이다. ② 후항에 4를 곱했으므로 전항에도 4를 곱해 □ = 8이다.","scoring_points":["2：3 = □：12를 세웠는가","비례식의 성질로 8을 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["2：3 = □：12예요.","2 × 12 = 3 × □ → □ = 8이에요.","4배 해도 □ = 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#1','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',1,'sa','auto','4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."],"variant_rule":{"alt":[{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]},{"stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#2','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',1,'sa','auto','48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."],"variant_rule":{"alt":[{"stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."]},{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#3','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',2,'mc','auto','5：2와 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#4','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',3,'ox','auto','5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#5','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C2',1,'mc','auto','12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#6','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C2',2,'mc','auto','90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#7','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C3',1,'sa','auto','0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."],"variant_rule":{"alt":[{"stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."]},{"stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#8','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C3',2,'mc','auto','0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."],"variant_rule":{"alt":[{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]},{"stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#9','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',2,'mc','auto','⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."],"variant_rule":{"alt":[{"stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."]},{"stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#10','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',3,'mc','auto','0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]},{"stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#11','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 9：12 = 3：4에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."]},{"stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#12','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#13','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',3,'mc','auto','2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."]},{"stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#14','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."]},{"stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#15','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',2,'sa','auto','3：11 = □：22에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."],"variant_rule":{"alt":[{"stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]},{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#16','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',3,'mc','auto','6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."],"variant_rule":{"alt":[{"stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."]},{"stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#17','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',1,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."],"variant_rule":{"alt":[{"stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."]},{"stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#18','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',2,'mc','auto','공책 4권이 3600원이에요. 공책 9권은 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."],"variant_rule":{"alt":[{"stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."]},{"stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#19','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',3,'mc','auto','사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."],"variant_rule":{"alt":[{"stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."]},{"stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#20','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',1,'sa','auto','사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."],"variant_rule":{"alt":[{"stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."]},{"stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#21','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',2,'mc','auto','1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."],"variant_rule":{"alt":[{"stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."]},{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#22','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',3,'mc','auto','2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#23','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#24','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 800000원을 회사와 사용자가 3：1로 나누어요. 두 친구의 몫을 낸 사용료(태리 6000원, 동하 10000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 5장, 동하 3장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 800000원을 회사와 사용자가 3：1로 나누어요. 두 친구의 몫을 낸 사용료(태리 6000원, 동하 10000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 5장, 동하 3장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000원이다. 사용료의 비 3：5로 나누면 태리 75000원, 동하 125000원이다. 그림 수의 비 5：3으로 나누면 태리 125000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 200000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 200000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#25','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',4,'essay','teacher','밀가루 3컵로 빵 2개를 만들 수 있어요. 빵 10개를 만들려면 밀가루가 몇 컵 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"밀가루 3컵로 빵 2개를 만들 수 있어요. 빵 10개를 만들려면 밀가루가 몇 컵 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 3：2 = □：10이다. ① 외항의 곱과 내항의 곱이 같으므로 3 × 10 = 2 × □, □ = 15이다. ② 후항에 5를 곱했으므로 전항에도 5를 곱해 □ = 15이다.","scoring_points":["3：2 = □：10을 세웠는가","비례식의 성질로 15를 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["3：2 = □：10이에요.","3 × 10 = 2 × □ → □ = 15예요.","5배 해도 □ = 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#1','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',1,'sa','auto','5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."],"variant_rule":{"alt":[{"stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."]},{"stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#2','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',1,'sa','auto','56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."],"variant_rule":{"alt":[{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]},{"stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#3','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',2,'mc','auto','3：7과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#4','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',3,'ox','auto','4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#5','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',1,'mc','auto','36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#6','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',2,'mc','auto','96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#7','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C3',1,'sa','auto','1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."],"variant_rule":{"alt":[{"stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."]},{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#8','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C3',2,'mc','auto','0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."],"variant_rule":{"alt":[{"stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."]},{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#9','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C4',2,'mc','auto','⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."]},{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#10','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C4',3,'mc','auto','⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."]},{"stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#11','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 6：8 = 9：12에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."],"variant_rule":{"alt":[{"stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."]},{"stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#12','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#13','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',3,'mc','auto','4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."]},{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#14','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."]},{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#15','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]},{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#16','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',3,'mc','auto','9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."],"variant_rule":{"alt":[{"stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."]},{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#17','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',1,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#18','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',2,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."]},{"stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#19','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',3,'mc','auto','페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."],"variant_rule":{"alt":[{"stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."]},{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#20','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',1,'sa','auto','연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]},{"stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#21','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',2,'mc','auto','2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."]},{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#22','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',3,'mc','auto','1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#23','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#24','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 400000 × ⟨2/5⟩ = 160000원이다. 사용료의 비 3：2로 나누면 태리 96000원, 동하 64000원이다. 그림 수의 비 1：1로 나누면 태리 80000원이므로 사용료의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 160000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 160000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#25','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',4,'essay','teacher','설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 4：5 = □：15이다. ① 외항의 곱과 내항의 곱이 같으므로 4 × 15 = 5 × □, □ = 12이다. ② 후항에 3을 곱했으므로 전항에도 3을 곱해 □ = 12이다.","scoring_points":["4：5 = □：15를 세웠는가","비례식의 성질로 12를 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["4：5 = □：15예요.","4 × 15 = 5 × □ → □ = 12예요.","3배 해도 □ = 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C1','math',6,2,'u5',2,'원주 — 원의 중심·반지름·지름을 되짚고 원의 둘레를 원주라 하며, 원 안 정육각형(지름의 3배)과 원 밖 정사각형(지름의 4배)으로 원주가 지름의 3배보다 길고 4배보다 짧음을 알기',ARRAY['6수03-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C2','math',6,2,'u5',3,'원주율 — 원의 지름에 대한 원주의 비율이 모든 원에서 일정함을 알고 (원주율) = (원주) ÷ (지름), 끝없이 이어지는 소수라 3.14로 어림해 쓰기',ARRAY['6수03-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C3','math',6,2,'u5',4,'원주 구하기 — (원주) = (지름) × (원주율), 반지름만 알면 2를 먼저 곱해 지름을 만든 뒤 원주율을 곱하고, 굴러간 거리 문제에 쓰기',ARRAY['6수03-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C4','math',6,2,'u5',4,'지름·반지름 구하기 — (지름) = (원주) ÷ (원주율)로 곱셈을 되짚어 지름과 반지름을 구하고, 원주·지름·반지름이 섞인 원의 크기를 견주기',ARRAY['6수03-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C5','math',6,2,'u5',5,'원의 넓이 어림하기 — 모눈 칸(온전한 칸·걸친 칸)과 원 안·밖 정사각형으로 넓이가 들어갈 범위를 찾고, (반지름) × (반지름)의 2배와 4배 사이(약 3배)임을 알기',ARRAY['6수03-12']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C6','math',6,2,'u5',6,'원의 넓이 구하기 — 원을 한없이 잘라 이어 붙인 직사각형(가로 원주의 반, 세로 반지름)으로 (원의 넓이) = (반지름) × (반지름) × (원주율)을 이끌어 내고 쓰기',ARRAY['6수03-12']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C7','math',6,2,'u5',7,'원의 넓이 활용 — 고리 모양은 큰 원에서 작은 원을 빼고, 잘라 옮겨도 넓이는 그대로이며, 반원·사분원·조각은 원의 넓이를 나누어 구하기',ARRAY['6수03-12']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C8','math',6,2,'u5',8,'반지름과 넓이의 관계 — 반지름이 □배가 되면 원주는 □배, 원의 넓이는 반지름을 두 번 곱하므로 □ × □배가 됨을 알고 쓰기',ARRAY['6수03-12']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X01','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C6']::text[],'원의 중심·반지름·지름을 혼동하거나 (지름) = (반지름) × 2 관계를 거꾸로 쓴다','지름은 반지름 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X02','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2']::text[],'원주를 지름·반지름 같은 선분과 혼동하거나, 원주가 지름의 3배(4배)와 정확히 같다고 단정하거나, 다각형처럼 변을 더해 구하려 한다','3배보다 길고 4배보다 짧아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X03','math',6,'u5',ARRAY['M6-2-u5-C1']::text[],'원 안 정육각형의 한 변을 지름으로, 원 밖 정사각형의 한 변을 반지름으로 바꾸어 본다','육각형 한 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X04','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원주율을 (지름) ÷ (원주)나 (원주) ÷ (반지름)으로 구한다(기준량을 잘못 잡음)','기준량은 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X05','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원이 커지면 원주율도 커진다고, 또는 원마다 원주율이 다르다고 본다','원주율은 늘 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X06','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'3.14가 원주율의 정확한 값이라 보거나, 잰 값의 작은 차이를 원주율이 달라서라고 본다','3.14는 어림한 값') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X07','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'반지름만 주어졌을 때 2를 곱하지 않고 반지름에 바로 원주율을 곱한다','반지름 × 2부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X08','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'원주를 구할 때 나누거나 지름을 구할 때 곱하는 등 곱셈·나눗셈을 거꾸로 쓴다','지름 × 3.14 = 원주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X10','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'넓이 어림에서 온전한 칸과 걸친 칸을 바꾸거나, 범위를 벗어난 값을 고르거나, 어림을 정확한 값으로 단정한다','어림은 범위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X11','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'원 안·밖 정사각형의 넓이가 (반지름) × (반지름)의 몇 배인지(2배·4배) 혼동한다','안은 2개, 밖은 4개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X12','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'원의 넓이를 원주 식((지름) × (원주율))으로 구하거나 원주와 넓이 식을 바꾸어 쓴다','넓이는 반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X13','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7']::text[],'원의 넓이를 구할 때 반지름 대신 지름을 두 번 곱한다','지름 말고 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X14','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C8']::text[],'원의 넓이를 구할 때 반지름을 한 번만 곱한다((반지름) × (원주율))','반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X15','math',6,'u5',ARRAY['M6-2-u5-C6']::text[],'원을 잘라 이어 붙인 직사각형의 가로를 원주 전체로, 세로를 지름으로 본다','가로는 원주의 반') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X16','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'고리 모양의 넓이를 반지름의 차로 만든 원의 넓이로 구하거나 작은 원을 빼지 않는다','큰 원 - 작은 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X17','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'잘라 옮기면 넓이가 변한다고 보거나, 반원·사분원·조각에서 나누기를 빠뜨리거나 잘못 나눈다','몇 조각 중 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X18','math',6,'u5',ARRAY['M6-2-u5-C2','M6-2-u5-C8']::text[],'반지름(지름)이 □배일 때 원주·넓이가 몇 배인지 잘못 본다(넓이도 □배, 원주도 □ × □배, 차이로 늘리기)','넓이는 □ × □배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X19','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 큰↔작은','물음의 「잘못·않은」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X20','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'소수 곱셈·나눗셈의 자릿수나 단위(cm·m)를 바꾸는 계산을 잘못한다','어림해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#1','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#2','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["8"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","16 ÷ 2 = 8 — 반지름은 8 m예요."],"variant_rule":{"alt":[{"stem":"원 모양 얼음판의 지름은 24 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["12"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","24 ÷ 2 = 12 — 반지름은 12 m예요."]},{"stem":"원 모양 얼음판의 지름은 30 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["15"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","30 ÷ 2 = 15 — 반지름은 15 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#3','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["12"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","6 × 2 = 12 — 지름은 12 cm예요."]},{"stem":"반지름이 9 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["18"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","9 × 2 = 18 — 지름은 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#4','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["12"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2이고 변이 6개이니 둘레는 2 × 6이에요.","2 × 6 = 12 — 지름의 3배인 12 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 3이고 변이 6개이니 둘레는 3 × 6이에요.","3 × 6 = 18 — 지름의 3배인 18 cm예요."]},{"stem":"지름이 8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4이고 변이 6개이니 둘레는 4 × 6이에요.","4 × 6 = 24 — 지름의 3배인 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#5','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'sa','auto','지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 4 cm이고 변이 4개예요.","4 × 4 = 16 — 지름의 4배인 16 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 6 cm이고 변이 4개예요.","6 × 4 = 24 — 지름의 4배인 24 cm예요."]},{"stem":"지름이 7 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 7 cm이고 변이 4개예요.","7 × 4 = 28 — 지름의 4배인 28 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#6','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?',ARRAY['M6-2-u5-X03','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정육각형은 원의 중심을 꼭짓점으로 하는 정삼각형 6개로 나뉘어요.","정삼각형의 두 변이 반지름이니 정육각형의 한 변도 반지름과 같아요.","그래서 정육각형의 둘레는 반지름의 6배, 곧 지름의 3배예요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정사각형이 원을 꼭 감싸면 마주 보는 두 변 사이가 원의 지름만큼 떨어져 있어요.","그래서 정사각형의 한 변은 지름과 같아요.","정사각형의 둘레는 지름의 4배예요."]},{"stem":"원 안에 꼭 맞는 정육각형의 둘레는 원의 지름의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M6-2-u5-X03"},{"t":"2배","mis":"M6-2-u5-X03"},{"t":"4배","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 한 변은 반지름과 같아요.","변이 6개이니 둘레는 반지름의 6배예요.","반지름 2개가 지름이니 반지름의 6배는 지름의 3배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#7','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"12 cm보다 길고 16 cm보다 짧아요","correct":true},{"t":"8 cm보다 길고 12 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"16 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 12 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 12 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 16 cm예요.","원주는 그 사이 — 12 cm보다 길고 16 cm보다 짧아요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"18 cm보다 길고 24 cm보다 짧아요","correct":true},{"t":"12 cm보다 길고 18 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"24 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 18 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 18 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 24 cm예요.","원주는 그 사이 — 18 cm보다 길고 24 cm보다 짧아요."]},{"stem":"지름이 10 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"30 cm보다 길고 40 cm보다 짧아요","correct":true},{"t":"20 cm보다 길고 30 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"40 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 30 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 30 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 40 cm예요.","원주는 그 사이 — 30 cm보다 길고 40 cm보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#8','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'ox','auto','원주는 지름의 정확히 3배예요.',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":2,"kind":"ox","stem":"원주는 지름의 정확히 3배예요.","answer":"X","reason_options":[{"t":"원주는 원 안 정육각형의 둘레(지름의 3배)보다 길기 때문에","correct":true},{"t":"원 안 정육각형의 둘레가 지름의 3배이기 때문에","mis":"M6-2-u5-X02"}],"mis":"M6-2-u5-X02","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 원 밖에 꼭 맞는 정사각형의 둘레보다 짧아요.","answer":"O","reason_options":[{"t":"꺾인 선보다 원의 굽은 선이 더 짧기 때문에","correct":true},{"t":"정사각형의 한 변이 반지름과 같기 때문에","mis":"M6-2-u5-X03"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"원의 둘레도 다각형처럼 변의 길이를 더해 구할 수 있어요.","answer":"X","reason_options":[{"t":"원에는 곧은 변이 하나도 없기 때문에","correct":true},{"t":"원의 변은 지름 하나뿐이라서 지름을 두 번 더하면 되기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#9','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','지름이 4 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 12 cm, 4개는 16 cm예요.","3개로는 못 미쳤으니 원주는 12 cm보다 길어요.","4개면 넘어섰으니 16 cm보다 짧아요 — 지름의 3배와 4배 사이예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 18 cm, 4개는 24 cm예요.","3개로는 못 미쳤으니 원주는 18 cm보다 길어요.","4개면 넘어섰으니 24 cm보다 짧아요 — 지름의 3배와 4배 사이예요."]},{"stem":"지름이 5 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 15 cm, 4개는 20 cm예요.","3개로는 못 미쳤으니 원주는 15 cm보다 길어요.","4개면 넘어섰으니 20 cm보다 짧아요 — 지름의 3배와 4배 사이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#10','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',3,'mc','auto','지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"29 cm","mis":"M6-2-u5-X02"},{"t":"42 cm","mis":"M6-2-u5-X02"},{"t":"10 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 10 cm이면 원주는 30 cm와 40 cm 사이예요.","보기 가운데 그 사이에 있는 것은 31.4 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"17 cm","mis":"M6-2-u5-X02"},{"t":"26 cm","mis":"M6-2-u5-X02"},{"t":"6 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 6 cm이면 원주는 18 cm와 24 cm 사이예요.","보기 가운데 그 사이에 있는 것은 18.84 cm뿐이에요."]},{"stem":"지름이 20 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"59 cm","mis":"M6-2-u5-X02"},{"t":"82 cm","mis":"M6-2-u5-X02"},{"t":"20 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 20 cm이면 원주는 60 cm와 80 cm 사이예요.","보기 가운데 그 사이에 있는 것은 62.8 cm뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#1','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'sa','auto','지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 5이고 변이 6개이니 둘레는 5 × 6이에요.","5 × 6 = 30 — 지름의 3배인 30 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 6이고 변이 6개이니 둘레는 6 × 6이에요.","6 × 6 = 36 — 지름의 3배인 36 cm예요."]},{"stem":"지름이 14 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["42"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 7이고 변이 6개이니 둘레는 7 × 6이에요.","7 × 6 = 42 — 지름의 3배인 42 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#2','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'mc','auto','지름이 8 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 8 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"23 cm","mis":"M6-2-u5-X02"},{"t":"34 cm","mis":"M6-2-u5-X02"},{"t":"8 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 8 cm이면 원주는 24 cm와 32 cm 사이예요.","보기 가운데 그 사이에 있는 것은 25.12 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"35 cm","mis":"M6-2-u5-X02"},{"t":"50 cm","mis":"M6-2-u5-X02"},{"t":"12 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 12 cm이면 원주는 36 cm와 48 cm 사이예요.","보기 가운데 그 사이에 있는 것은 37.68 cm뿐이에요."]},{"stem":"지름이 5 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"14 cm","mis":"M6-2-u5-X02"},{"t":"22 cm","mis":"M6-2-u5-X02"},{"t":"5 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 5 cm이면 원주는 15 cm와 20 cm 사이예요.","보기 가운데 그 사이에 있는 것은 15.7 cm뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#3','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'error','auto','지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":3,"kind":"error","stem":"지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원주는 정확히 지름의 3배인 18 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"나린 — 「원 안 정육각형의 둘레는 18 cm야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원 밖 정사각형의 둘레는 24 cm야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 18 cm보다 길고 24 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 18 cm, 원 밖 정사각형의 둘레는 24 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 18 cm라는 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원주는 정확히 지름의 3배인 24 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"하린 — 「원 안 정육각형의 둘레는 24 cm야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원 밖 정사각형의 둘레는 32 cm야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 24 cm보다 길고 32 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 24 cm, 원 밖 정사각형의 둘레는 32 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 24 cm라는 수아의 말이 잘못되었어요."]},{"stem":"지름이 10 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「원주는 정확히 지름의 3배인 30 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"지호 — 「원 안 정육각형의 둘레는 30 cm야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원 밖 정사각형의 둘레는 40 cm야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주는 30 cm보다 길고 40 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 30 cm, 원 밖 정사각형의 둘레는 40 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 30 cm라는 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#4','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 한 변","r":"반지름"},{"l":"원 밖 정사각형의 한 변","r":"지름"},{"l":"원 위를 한 바퀴 돈 거리","r":"원주"}],"mis":"M6-2-u5-X01","explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심과 원 위의 한 점을 이은 선분","r":"반지름"},{"l":"원의 중심을 지나 원 위의 두 점을 이은 선분","r":"지름"},{"l":"원의 둘레","r":"원주"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 둘레","r":"지름의 3배"},{"l":"원 밖 정사각형의 둘레","r":"지름의 4배"},{"l":"지름","r":"반지름의 2배"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#5','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'ox','auto','원 안에 꼭 맞는 정육각형의 둘레는 원주보다 짧아요.',ARRAY['M6-2-u5-X03']::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":3,"kind":"ox","stem":"원 안에 꼭 맞는 정육각형의 둘레는 원주보다 짧아요.","answer":"O","reason_options":[{"t":"두 점 사이를 이을 때 곧은 선이 굽은 선보다 짧기 때문에","correct":true},{"t":"정육각형의 한 변이 지름과 같기 때문에","mis":"M6-2-u5-X03"}],"mis":"M6-2-u5-X03","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 지름의 4배보다 길어요.","answer":"X","reason_options":[{"t":"원주는 원 밖 정사각형의 둘레(지름의 4배)보다 짧기 때문에","correct":true},{"t":"원이 정사각형을 감싸고 있기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"지름이 다르면 원주도 달라요.","answer":"O","reason_options":[{"t":"지름이 길수록 원의 둘레도 길어지기 때문에","correct":true},{"t":"원주는 지름과 상관없이 늘 같기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#6','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'mc','auto','반지름이 9 cm인 원과 지름이 16 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"반지름이 9 cm인 원과 지름이 16 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"반지름이 9 cm인 원","correct":true},{"t":"지름이 16 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 9 cm인 원의 지름은 18 cm예요.","지름이 긴 원이 원주도 길어요 — 반지름이 9 cm인 원예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원과 지름이 15 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"반지름이 7 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 7 cm인 원의 지름은 14 cm예요.","지름이 긴 원이 원주도 길어요 — 지름이 15 cm인 원예요."]},{"stem":"반지름이 12 cm인 원과 지름이 22 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"반지름이 12 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 12 cm인 원의 지름은 24 cm예요.","지름이 긴 원이 원주도 길어요 — 반지름이 12 cm인 원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#7','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'mc','auto','지름이 16 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 16 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"48 cm보다 길고 64 cm보다 짧아요","correct":true},{"t":"32 cm보다 길고 48 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"64 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 48 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 48 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 64 cm예요.","원주는 그 사이 — 48 cm보다 길고 64 cm보다 짧아요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"36 cm보다 길고 48 cm보다 짧아요","correct":true},{"t":"24 cm보다 길고 36 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"48 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 36 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 36 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 48 cm예요.","원주는 그 사이 — 36 cm보다 길고 48 cm보다 짧아요."]},{"stem":"지름이 20 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"60 cm보다 길고 80 cm보다 짧아요","correct":true},{"t":"40 cm보다 길고 60 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"80 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 60 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 60 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 80 cm예요.","원주는 그 사이 — 60 cm보다 길고 80 cm보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#8','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'sa','auto','어떤 원 안에 꼭 맞는 정육각형의 둘레가 24 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":4,"kind":"sa","stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 24 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["32"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","24 ÷ 3 = 8 — 지름은 8 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 8 × 4 = 32 cm예요."],"variant_rule":{"alt":[{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 18 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","18 ÷ 3 = 6 — 지름은 6 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 6 × 4 = 24 cm예요."]},{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 36 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["48"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","36 ÷ 3 = 12 — 지름은 12 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 12 × 4 = 48 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#9','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 둘레가 48 cm예요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":4,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 48 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["6"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","48 ÷ 4 = 12 — 지름은 12 cm예요.","반지름은 지름의 반 — 12 ÷ 2 = 6 cm예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 40 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","40 ÷ 4 = 10 — 지름은 10 cm예요.","반지름은 지름의 반 — 10 ÷ 2 = 5 cm예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 64 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","64 ÷ 4 = 16 — 지름은 16 cm예요.","반지름은 지름의 반 — 16 ÷ 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#10','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'essay','teacher','원주가 지름의 3배보다 길고 4배보다 짧은 까닭을 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":4,"kind":"essay","stem":"원주가 지름의 3배보다 길고 4배보다 짧은 까닭을 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 이용하여 설명해 보세요.","answer_guide":{"answer":"예: 원 안 정육각형의 한 변은 반지름과 같아 둘레가 지름의 3배이고, 곧은 선보다 굽은 선이 길어 원주는 그보다 길다. 원 밖 정사각형의 한 변은 지름과 같아 둘레가 지름의 4배이고, 꺾인 선보다 원의 굽은 선이 짧아 원주는 그보다 짧다.","scoring_points":["정육각형의 둘레가 지름의 3배임을 밝혔는가","정사각형의 둘레가 지름의 4배임을 밝혔는가","원주가 두 둘레 사이에 있는 까닭을 썼는가"]},"explanation":["정육각형의 한 변 = 반지름 → 둘레는 지름의 3배예요.","정사각형의 한 변 = 지름 → 둘레는 지름의 4배예요.","원주는 그 사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#1','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','원주율을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]},{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#2','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','공학 도구로 반지름이 3 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"공학 도구로 반지름이 3 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["6"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","3 × 2 = 6 — 지름은 6 cm예요."],"variant_rule":{"alt":[{"stem":"공학 도구로 반지름이 7 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["14"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","7 × 2 = 14 — 지름은 14 cm예요."]},{"stem":"공학 도구로 반지름이 12 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["24"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","12 × 2 = 24 — 지름은 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#3','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','어떤 원의 원주가 15.7 cm, 지름이 5 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"어떤 원의 원주가 15.7 cm, 지름이 5 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"10.7","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","15.7 ÷ 5 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원 모양 시계의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원 모양 쟁반의 원주가 62.8 cm, 지름이 20 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"42.8","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#4','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'ox','auto','지름이 길어지면 원주율도 커져요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"ox","stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#5','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'sa','auto','지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"sa","stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?","answer":["2"],"explanation":["12.56 ÷ 6.28 = 2예요.","지름이 2배가 되니 원주도 2배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 8 cm일 때 원주는 25.12 cm예요. 지름이 4배가 될 때 원주는 몇 배가 되나요?","answer":["4"],"explanation":["25.12 ÷ 6.28 = 4예요.","지름이 4배가 되니 원주도 4배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]},{"stem":"지름이 3 cm일 때 원주는 9.42 cm, 지름이 9 cm일 때 원주는 28.26 cm예요. 지름이 3배가 될 때 원주는 몇 배가 되나요?","answer":["3"],"explanation":["28.26 ÷ 9.42 = 3이에요.","지름이 3배가 되니 원주도 3배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#6','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#7','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."],"variant_rule":{"alt":[{"stem":"물병의 (원주) ÷ (지름)은 3.13846…, 연필꽂이의 값은 3.14473…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]},{"stem":"연필꽂이의 (원주) ÷ (지름)은 3.14473…, 냄비 뚜껑의 값은 3.142857…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#8','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#9','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원의 원주는 15.7 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","15.7 ÷ 5 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#10','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',3,'sa','auto','원주가 지름보다 21.4 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":3,"kind":"sa","stem":"원주가 지름보다 21.4 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 21.4예요.","21.4 ÷ 2.14 = 10 — 지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 지름보다 10.7 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["5"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 10.7이에요.","10.7 ÷ 2.14 = 5 — 지름은 5 cm예요."]},{"stem":"원주가 지름보다 42.8 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["20"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 42.8이에요.","42.8 ÷ 2.14 = 20 — 지름은 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#1','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'sa','auto','지름이 3 cm일 때 원주는 9.42 cm, 지름이 15 cm일 때 원주는 47.1 cm예요. 지름이 5배가 될 때 원주는 몇 배가 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":2,"kind":"sa","stem":"지름이 3 cm일 때 원주는 9.42 cm, 지름이 15 cm일 때 원주는 47.1 cm예요. 지름이 5배가 될 때 원주는 몇 배가 되나요?","answer":["5"],"explanation":["47.1 ÷ 9.42 = 5예요.","지름이 5배가 되니 원주도 5배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 20 cm일 때 원주는 62.8 cm예요. 지름이 10배가 될 때 원주는 몇 배가 되나요?","answer":["10"],"explanation":["62.8 ÷ 6.28 = 10이에요.","지름이 10배가 되니 원주도 10배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]},{"stem":"지름이 4 cm일 때 원주는 12.56 cm, 지름이 12 cm일 때 원주는 37.68 cm예요. 지름이 3배가 될 때 원주는 몇 배가 되나요?","answer":["3"],"explanation":["37.68 ÷ 12.56 = 3이에요.","지름이 3배가 되니 원주도 3배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#2','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'mc','auto','원 모양 쟁반의 원주가 25.12 cm, 지름이 8 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원 모양 쟁반의 원주가 25.12 cm, 지름이 8 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"17.12","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","25.12 ÷ 8 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원 모양 탬버린의 원주가 47.1 cm, 지름이 15 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"32.1","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원 모양 거울의 원주가 37.68 cm, 지름이 12 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"25.68","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","37.68 ÷ 12 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#3','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'error','auto','원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":3,"kind":"error","stem":"원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「큰 원은 원주율도 더 커.」","correct":true,"mis_target":"M6-2-u5-X05"},{"t":"나린 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원주율은 (지름) ÷ (원주)로 구해.」","correct":true,"mis_target":"M6-2-u5-X04"},{"t":"하린 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 수아의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「3.14는 원주율의 정확한 값이야.」","correct":true,"mis_target":"M6-2-u5-X06"},{"t":"지호 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#4','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'ox','auto','반지름에 대한 원주의 비율도 3.14예요.',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":3,"kind":"ox","stem":"반지름에 대한 원주의 비율도 3.14예요.","answer":"X","reason_options":[{"t":"원주는 반지름의 약 6.28배이기 때문에","correct":true},{"t":"반지름도 원의 길이니 비율이 같기 때문에","mis":"M6-2-u5-X04"}],"mis":"M6-2-u5-X04","explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."],"variant_rule":{"alt":[{"stem":"원주가 31.4 cm인 원의 지름은 10 cm예요.","answer":"O","reason_options":[{"t":"31.4 ÷ 3.14 = 10이기 때문에","correct":true},{"t":"31.4 × 3.14가 10이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."]},{"stem":"원주가 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"원주가 길어지면 지름도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"원주율은 원주에 비례하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#5','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"원의 둘레"},{"l":"원주율","r":"(원주) ÷ (지름)"},{"l":"지름","r":"(원주) ÷ (원주율)"}],"mis":"M6-2-u5-X04","explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"(지름) × (원주율)"},{"l":"원주율","r":"약 3.14"},{"l":"반지름","r":"(지름) ÷ 2"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 10 cm인 원의 원주","r":"31.4 cm"},{"l":"지름 10 cm인 원의 원주율","r":"3.14"},{"l":"원주 31.4 cm인 원의 반지름","r":"5 cm"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#6','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','세 물건의 원주와 지름을 재었어요. ㉠ 원주 31.4 cm, 지름 10 cm · ㉡ 원주 47 cm, 지름 15 cm · ㉢ 원주 40 cm, 지름 10 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?',ARRAY['M6-2-u5-X06']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 31.4 cm, 지름 10 cm · ㉡ 원주 47 cm, 지름 15 cm · ㉢ 원주 40 cm, 지름 10 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M6-2-u5-X06"},{"t":"㉡","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 3.14 · ㉡ 3.13 · ㉢ 4예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉢는 잘못 잰 거예요."],"variant_rule":{"alt":[{"stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 25 cm, 지름 10 cm · ㉡ 원주 62.8 cm, 지름 20 cm · ㉢ 원주 18.9 cm, 지름 6 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M6-2-u5-X06"},{"t":"㉢","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 2.5 · ㉡ 3.14 · ㉢ 3.15예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉠는 잘못 잰 거예요."]},{"stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 9.4 cm, 지름 3 cm · ㉡ 원주 50 cm, 지름 10 cm · ㉢ 원주 37.7 cm, 지름 12 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u5-X06"},{"t":"㉢","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 3.13 · ㉡ 5 · ㉢ 3.14예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉡는 잘못 잰 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#7','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','지름이 6 cm인 원의 원주는 18.84 cm예요. 지름이 18 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"지름이 6 cm인 원의 원주는 18.84 cm예요. 지름이 18 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"30.84 cm","mis":"M6-2-u5-X18"},{"t":"169.56 cm","mis":"M6-2-u5-X18"},{"t":"28.26 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 3배가 되었어요.","원주율이 일정하니 원주도 3배가 돼요.","18.84 × 3 = 56.52 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주는 12.56 cm예요. 지름이 20 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"28.56 cm","mis":"M6-2-u5-X18"},{"t":"314 cm","mis":"M6-2-u5-X18"},{"t":"31.4 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 5배가 되었어요.","원주율이 일정하니 원주도 5배가 돼요.","12.56 × 5 = 62.8 cm예요."]},{"stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 지름이 40 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"125.6 cm","correct":true},{"t":"61.4 cm","mis":"M6-2-u5-X18"},{"t":"502.4 cm","mis":"M6-2-u5-X18"},{"t":"62.8 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 4배가 되었어요.","원주율이 일정하니 원주도 4배가 돼요.","31.4 × 4 = 125.6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#8','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'sa','auto','원주가 지름보다 64.2 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":4,"kind":"sa","stem":"원주가 지름보다 64.2 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["30"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 64.2예요.","64.2 ÷ 2.14 = 30 — 지름은 30 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 지름보다 32.1 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["15"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 32.1이에요.","32.1 ÷ 2.14 = 15 — 지름은 15 cm예요."]},{"stem":"원주가 지름보다 53.5 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 53.5예요.","53.5 ÷ 2.14 = 25 — 지름은 25 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#9','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','작은 동전과 큰 냄비 뚜껑은 크기가 아주 다른데도 (원주) ÷ (지름)이 둘 다 약 3.14로 나와요. 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"작은 동전과 큰 냄비 뚜껑은 크기가 아주 다른데도 (원주) ÷ (지름)이 둘 다 약 3.14로 나와요. 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원이 커져 지름이 길어지면 원주도 같은 배수만큼 함께 길어진다. 그래서 원주를 지름으로 나눈 비율은 변하지 않고, 모든 원에서 원주율은 약 3.14로 일정하다.","scoring_points":["지름이 길어지면 원주도 함께 길어짐을 밝혔는가","비율((원주) ÷ (지름))이 변하지 않음을 썼는가","원주율이 모든 원에서 일정하다고 결론지었는가"]},"explanation":["원이 커지면 원주와 지름이 함께 늘어요.","함께 늘면 나눈 값은 그대로예요.","그래서 원주율은 늘 약 3.14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#10','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','냄비 뚜껑을 재어 구한 (원주) ÷ (지름)은 3.142857…, 물병은 3.13846…이었어요. 두 값이 다르다고 원주율이 원마다 다르다고 말할 수 있는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"냄비 뚜껑을 재어 구한 (원주) ÷ (지름)은 3.142857…, 물병은 3.13846…이었어요. 두 값이 다르다고 원주율이 원마다 다르다고 말할 수 있는지 설명해 보세요.","answer_guide":{"answer":"예: 말할 수 없다. 원주와 지름을 줄자·자로 정확하게 재기 어려워 생긴 작은 차이이다. 반올림하면 둘 다 3.14이고, 원주율은 모든 원에서 일정하다.","scoring_points":["원주율이 원마다 다르지 않다고 답했는가","재는 과정의 오차 때문이라고 설명했는가","반올림하면 3.14로 같음을 보였는가"]},"explanation":["원주율은 모든 원에서 일정해요.","잰 값의 작은 차이는 재기 어려워 생긴 것이에요.","반올림하면 둘 다 3.14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#1','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(지름) ÷ (원주율)","mis":"M6-2-u5-X08"},{"t":"(지름) + (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (지름)","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","거꾸로 하면 (원주) = (지름) × (원주율)이에요.","지름에 3.14를 곱하면 원주가 나와요."],"variant_rule":{"alt":[{"stem":"원주를 알 때 지름을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (원주율)","correct":true},{"t":"(원주) × (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주) - (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (원주)","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","곱셈으로 간 길을 나눗셈으로 되짚어요.","그래서 (지름) = (원주) ÷ (원주율)이에요."]},{"stem":"반지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X07"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(반지름) ÷ (원주율)","mis":"M6-2-u5-X08"}],"explanation":["원주는 지름에 원주율을 곱해요.","반지름만 알면 2를 먼저 곱해 지름을 만들어요.","그래서 (반지름) × 2 × (원주율)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#2','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',1,'sa','auto','원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#3','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','지름이 10 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]},{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#4','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":4,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]},{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#5','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','자전거 바퀴의 지름은 80 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":5,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"자전거 바퀴의 지름은 80 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"251.2 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X01"},{"t":"502.4 cm","mis":"M6-2-u5-X01"},{"t":"5024 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","80 × 3.14를 계산해요.","80 × 3.14 = 251.2 — 원주는 251.2 cm예요."],"variant_rule":{"alt":[{"stem":"유모차 바퀴의 지름은 60 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"188.4 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"376.8 cm","mis":"M6-2-u5-X01"},{"t":"2826 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","60 × 3.14를 계산해요.","60 × 3.14 = 188.4 — 원주는 188.4 cm예요."]},{"stem":"수레바퀴의 지름은 70 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"219.8 cm","correct":true},{"t":"109.9 cm","mis":"M6-2-u5-X01"},{"t":"439.6 cm","mis":"M6-2-u5-X01"},{"t":"3846.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","70 × 3.14를 계산해요.","70 × 3.14 = 219.8 — 원주는 219.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#6','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]},{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#7','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#8','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]},{"stem":"꽃밭에 줄을 이용하여 원주가 37.68 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["6"],"explanation":["먼저 지름을 구해요: 37.68 ÷ 3.14 = 12예요.","반지름은 지름의 반이에요.","12 ÷ 2 = 6 — 반지름은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#9','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','원 모양 시계의 원주가 28.26 cm예요. 이 시계의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원 모양 시계의 원주가 28.26 cm예요. 이 시계의 지름은 몇 cm인가요?","answer":["9"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","28.26 ÷ 3.14를 계산해요.","28.26 ÷ 3.14 = 9예요."],"variant_rule":{"alt":[{"stem":"원 모양 쟁반의 원주가 47.1 cm예요. 이 쟁반의 지름은 몇 cm인가요?","answer":["15"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","47.1 ÷ 3.14를 계산해요.","47.1 ÷ 3.14 = 15예요."]},{"stem":"원 모양 거울의 원주가 37.68 cm예요. 이 거울의 지름은 몇 cm인가요?","answer":["12"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","37.68 ÷ 3.14를 계산해요.","37.68 ÷ 3.14 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#10','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',3,'error','auto','반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"error","stem":"반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「6 × 3.14 = 18.84, 원주는 18.84 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"나린 — 「지름이 12 cm니 12 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「6 × 2 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 37.68 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 6 cm에 2를 먼저 곱해 지름 12 cm를 만들어야 해요.","가온는 반지름에 바로 3.14를 곱했어요 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「4 × 3.14 = 12.56, 원주는 12.56 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"하린 — 「지름이 8 cm니 8 × 3.14 = 25.12야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「4 × 2 × 3.14 = 25.12야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 25.12 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 4 cm에 2를 먼저 곱해 지름 8 cm를 만들어야 해요.","수아는 반지름에 바로 3.14를 곱했어요 — 원주는 25.12 cm예요."]},{"stem":"반지름이 7 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「7 × 3.14 = 21.98, 원주는 21.98 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"지호 — 「지름이 14 cm니 14 × 3.14 = 43.96이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「7 × 2 × 3.14 = 43.96이야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주는 43.96 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 7 cm에 2를 먼저 곱해 지름 14 cm를 만들어야 해요.","서아는 반지름에 바로 3.14를 곱했어요 — 원주는 43.96 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#1','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',2,'mc','auto','지름이 10 cm인 원과 지름이 15 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원과 지름이 15 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u5-X02"},{"t":"31.4 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 15 - 10 = 5 cm예요.","5 × 3.14 = 15.7 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원과 지름이 12 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"4 cm","mis":"M6-2-u5-X02"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 12 - 8 = 4 cm예요.","4 × 3.14 = 12.56 cm예요."]},{"stem":"지름이 20 cm인 원과 지름이 25 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u5-X02"},{"t":"31.4 cm","mis":"M6-2-u5-X01"},{"t":"141.3 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 25 - 20 = 5 cm예요.","5 × 3.14 = 15.7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#2','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',2,'sa','auto','원주가 43.96 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]},{"stem":"원주가 69.08 cm인 원의 반지름은 몇 cm인가요?","answer":["11"],"explanation":["먼저 지름을 구해요: 69.08 ÷ 3.14 = 22예요.","반지름은 지름의 반이에요.","22 ÷ 2 = 11 — 반지름은 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#3','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#4','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'ox','auto','반지름이 같은 두 원은 원주도 같아요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":4,"concept":"M6-2-u5-C3","difficulty":3,"kind":"ox","stem":"반지름이 같은 두 원은 원주도 같아요.","answer":"O","reason_options":[{"t":"반지름이 같으면 지름이 같아 지름 × 3.14도 같기 때문에","correct":true},{"t":"반지름이 같아도 원주는 원마다 다르기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."],"variant_rule":{"alt":[{"stem":"지름이 2배인 원은 원주도 2배예요.","answer":"O","reason_options":[{"t":"원주는 지름에 3.14를 곱한 값이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]},{"stem":"반지름이 5 cm인 원의 원주는 5 × 3.14 = 15.7 cm예요.","answer":"X","reason_options":[{"t":"반지름에 2를 먼저 곱해 지름 10 cm로 계산해야 하기 때문에","correct":true},{"t":"원주는 반지름에 원주율을 곱한 값이기 때문에","mis":"M6-2-u5-X07"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#5','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C3","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"원주 12.56 cm"},{"l":"지름 5 cm","r":"원주 15.7 cm"},{"l":"반지름 4 cm","r":"원주 25.12 cm"}],"mis":"M6-2-u5-X07","explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 3 cm","r":"원주 9.42 cm"},{"l":"반지름 3 cm","r":"원주 18.84 cm"},{"l":"지름 8 cm","r":"원주 25.12 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주 31.4 cm","r":"지름 10 cm"},{"l":"원주 62.8 cm","r":"지름 20 cm"},{"l":"원주 15.7 cm","r":"지름 5 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#6','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'error','auto','반지름이 5 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X19']::text[],true,'{"seq":6,"concept":"M6-2-u5-C3","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"세호 — 「5 × 3.14 = 15.7, 원주는 15.7 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"여울 — 「지름이 10 cm니 10 × 3.14 = 31.4야.」","mis":"M6-2-u5-X19"},{"t":"달곰 — 「5 × 2 × 3.14 = 31.4야.」","mis":"M6-2-u5-X19"},{"t":"순달 — 「원주는 31.4 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 5 cm에 2를 먼저 곱해 지름 10 cm를 만들어야 해요.","세호는 반지름에 바로 3.14를 곱했어요 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「8 × 3.14 = 25.12, 원주는 25.12 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"나린 — 「지름이 16 cm니 16 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「8 × 2 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 50.24 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 8 cm에 2를 먼저 곱해 지름 16 cm를 만들어야 해요.","가온는 반지름에 바로 3.14를 곱했어요 — 원주는 50.24 cm예요."]},{"stem":"반지름이 3 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「3 × 3.14 = 9.42, 원주는 9.42 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"하린 — 「지름이 6 cm니 6 × 3.14 = 18.84야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「3 × 2 × 3.14 = 18.84야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 18.84 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 3 cm에 2를 먼저 곱해 지름 6 cm를 만들어야 해요.","수아는 반지름에 바로 3.14를 곱했어요 — 원주는 18.84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#7','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',3,'sa','auto','원 모양 연못의 둘레가 94.2 m예요. 연못의 지름은 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":3,"kind":"sa","stem":"원 모양 연못의 둘레가 94.2 m예요. 연못의 지름은 몇 m인가요?","answer":["30"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","94.2 ÷ 3.14를 계산해요.","94.2 ÷ 3.14 = 30이에요."],"variant_rule":{"alt":[{"stem":"원 모양 광장의 둘레가 125.6 m예요. 광장의 지름은 몇 m인가요?","answer":["40"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","125.6 ÷ 3.14를 계산해요.","125.6 ÷ 3.14 = 40이에요."]},{"stem":"원 모양 분수대의 둘레가 78.5 m예요. 분수대의 지름은 몇 m인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#8','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',4,'mc','auto','지름이 50 cm인 바퀴로 471 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":4,"kind":"mc","stem":"지름이 50 cm인 바퀴로 471 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"300바퀴","correct":true},{"t":"600바퀴","mis":"M6-2-u5-X07"},{"t":"150바퀴","mis":"M6-2-u5-X01"},{"t":"3바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","471 m = 47100 cm예요.","47100 ÷ 157 = 300 — 300바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 바퀴로 628 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"500바퀴","correct":true},{"t":"1000바퀴","mis":"M6-2-u5-X07"},{"t":"250바퀴","mis":"M6-2-u5-X01"},{"t":"5바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","628 m = 62800 cm예요.","62800 ÷ 125.6 = 500 — 500바퀴예요."]},{"stem":"지름이 50 cm인 바퀴로 314 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"200바퀴","correct":true},{"t":"400바퀴","mis":"M6-2-u5-X07"},{"t":"100바퀴","mis":"M6-2-u5-X01"},{"t":"2바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","314 m = 31400 cm예요.","31400 ÷ 157 = 200 — 200바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#9','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'sa','auto','원주가 94.2 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":4,"kind":"sa","stem":"원주가 94.2 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["90"],"explanation":["지름은 94.2 ÷ 3.14 = 30 cm예요.","정육각형의 둘레는 지름의 3배예요.","30 × 3 = 90 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 62.8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["60"],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm예요.","정육각형의 둘레는 지름의 3배예요.","20 × 3 = 60 cm예요."]},{"stem":"원주가 31.4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","정육각형의 둘레는 지름의 3배예요.","10 × 3 = 30 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#10','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'essay','teacher','원 모양 호수의 둘레가 157 m예요. 호수를 직접 재지 않고 중심을 지나는 다리의 길이를 구하는 방법과 답을 쓰고, 왜 나누면 지름이 나오는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"원 모양 호수의 둘레가 157 m예요. 호수를 직접 재지 않고 중심을 지나는 다리의 길이를 구하는 방법과 답을 쓰고, 왜 나누면 지름이 나오는지 설명해 보세요.","answer_guide":{"answer":"예: 다리의 길이는 호수의 지름과 같다. (지름) = (원주) ÷ (원주율)이므로 157 ÷ 3.14 = 50 m이다. 지름에 원주율을 곱해 원주가 되었으니, 원주를 원주율로 나누면 다시 지름으로 돌아온다.","scoring_points":["다리의 길이가 지름임을 밝혔는가","157 ÷ 3.14 = 50 m를 구했는가","곱셈을 나눗셈으로 되짚는다는 까닭을 썼는가"]},"explanation":["다리는 중심을 지나니 지름이에요.","157 ÷ 3.14 = 50 m예요.","(원주) = (지름) × (원주율)을 거꾸로 되짚은 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#1','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 60칸이고, 원에 걸친 칸은 28칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 60칸이고, 원에 걸친 칸은 28칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["88"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","60 + 28 = 88칸이에요.","그래서 원의 넓이는 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 52칸이고, 원에 걸친 칸은 36칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["88"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","52 + 36 = 88칸이에요.","그래서 원의 넓이는 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 44칸이고, 원에 걸친 칸은 30칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["74"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","44 + 30 = 74칸이에요.","그래서 원의 넓이는 74 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#2','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#3','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 7 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 14 cm예요. 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","14 × 14 ÷ 2 = 98이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#4','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 2 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["16"],"explanation":["원 밖 정사각형의 한 변은 지름 4 cm예요.","4 × 4 = 16이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#5','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','지름이 16 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 16 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"128 cm²보다 넓고 256 cm²보다 좁아요","correct":true},{"t":"64 cm²보다 넓고 128 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"256 cm²보다 넓고 512 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"16 cm²보다 넓고 32 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 8 cm예요.","원 안 정사각형은 8 × 8 × 2 = 128 cm², 원 밖 정사각형은 8 × 8 × 4 = 256 cm²예요.","원의 넓이는 그 사이 — 128 cm²보다 넓고 256 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."]},{"stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#6','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','반지름이 5 cm인 원 모양 메달을 만들려고 해요. 메달의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10','M6-2-u5-X01']::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원 모양 메달을 만들려고 해요. 메달의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"75 cm²","correct":true},{"t":"25 cm²","mis":"M6-2-u5-X11"},{"t":"140 cm²","mis":"M6-2-u5-X10"},{"t":"10 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","5 × 5 = 25니 넓이는 50 cm²와 100 cm² 사이예요.","그 한가운데쯤인 약 3배 — 75 cm²가 가장 가까워요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 방석을 만들려고 해요. 방석의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"300 cm²","correct":true},{"t":"100 cm²","mis":"M6-2-u5-X11"},{"t":"515 cm²","mis":"M6-2-u5-X10"},{"t":"20 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","10 × 10 = 100이니 넓이는 200 cm²와 400 cm² 사이예요.","그 한가운데쯤인 약 3배 — 300 cm²가 가장 가까워요."]},{"stem":"반지름이 4 cm인 원 모양 컵받침을 만들려고 해요. 컵받침의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"48 cm²","correct":true},{"t":"16 cm²","mis":"M6-2-u5-X11"},{"t":"95 cm²","mis":"M6-2-u5-X10"},{"t":"8 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","4 × 4 = 16이니 넓이는 32 cm²와 64 cm² 사이예요.","그 한가운데쯤인 약 3배 — 48 cm²가 가장 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#7','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"2개","correct":true},{"t":"4개","mis":"M6-2-u5-X11"},{"t":"1개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형을 두 대각선으로 자르면 직각삼각형 4개예요.","반지름을 한 변으로 하는 정사각형 하나는 그 삼각형 2개예요.","그래서 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"},{"t":"8개","mis":"M6-2-u5-X11"}],"explanation":["원 밖 정사각형의 한 변은 지름 — 반지름의 2배예요.","가로로 2개, 세로로 2개 들어가요.","그래서 정사각형 4개와 넓이가 같아요."]},{"stem":"원의 넓이는 반지름을 한 변으로 하는 정사각형 몇 개의 넓이와 가장 비슷한가요?","options":[{"t":"약 3개","correct":true},{"t":"약 1개","mis":"M6-2-u5-X11"},{"t":"약 6개","mis":"M6-2-u5-X10"},{"t":"약 5개","mis":"M6-2-u5-X10"}],"explanation":["원의 넓이는 반지름 정사각형 2개보다 넓어요.","또 4개보다 좁아요.","그 한가운데쯤인 약 3개와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#8','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'ox','auto','원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":2,"kind":"ox","stem":"원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","answer":"O","reason_options":[{"t":"원 안 정사각형은 2배, 원 밖 정사각형은 4배와 넓이가 같기 때문에","correct":true},{"t":"원의 넓이는 반지름의 4배와 정확히 같기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 넓이는 (반지름) × (반지름)의 2배예요.","answer":"X","reason_options":[{"t":"원 밖 정사각형의 한 변은 지름이라 반지름 정사각형 4개와 같기 때문에","correct":true},{"t":"원 밖 정사각형의 한 변이 반지름이기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"모눈으로 어림한 넓이는 원의 정확한 넓이예요.","answer":"X","reason_options":[{"t":"어림은 넓이가 들어갈 범위를 찾는 것이기 때문에","correct":true},{"t":"칸을 빠짐없이 셌으니 정확하기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#9','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','반지름이 6 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"70 cm²","mis":"M6-2-u5-X10"},{"t":"150 cm²","mis":"M6-2-u5-X10"},{"t":"36 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 6 × 6 × 2 = 72 cm²보다 넓어요.","또 6 × 6 × 4 = 144 cm²보다 좁아요.","그 사이에 있는 것은 113.04 cm²뿐이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"48 cm²","mis":"M6-2-u5-X10"},{"t":"106 cm²","mis":"M6-2-u5-X10"},{"t":"25 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 5 × 5 × 2 = 50 cm²보다 넓어요.","또 5 × 5 × 4 = 100 cm²보다 좁아요.","그 사이에 있는 것은 78.5 cm²뿐이에요."]},{"stem":"반지름이 4 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"30 cm²","mis":"M6-2-u5-X10"},{"t":"70 cm²","mis":"M6-2-u5-X10"},{"t":"16 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 4 × 4 × 2 = 32 cm²보다 넓어요.","또 4 × 4 × 4 = 64 cm²보다 좁아요.","그 사이에 있는 것은 50.24 cm²뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#10','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',3,'mc','auto','반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 88 - 60 = 28 cm²예요.","정사각형으로 얻은 범위의 폭은 100 - 50 = 50 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원의 넓이를 모눈으로 세었더니 276 cm²보다 넓고 344 cm²보다 좁았고, 정사각형으로 어림했더니 200 cm²보다 넓고 400 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 344 - 276 = 68 cm²예요.","정사각형으로 얻은 범위의 폭은 400 - 200 = 200 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."]},{"stem":"반지름이 4 cm인 원의 넓이를 모눈으로 세었더니 32 cm²보다 넓고 60 cm²보다 좁았고, 정사각형으로 어림했더니 32 cm²보다 넓고 64 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 60 - 32 = 28 cm²예요.","정사각형으로 얻은 범위의 폭은 64 - 32 = 32 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#1','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'mc','auto','지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."]},{"stem":"지름이 18 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"162 cm²보다 넓고 324 cm²보다 좁아요","correct":true},{"t":"81 cm²보다 넓고 162 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"324 cm²보다 넓고 648 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"18 cm²보다 넓고 36 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 9 cm예요.","원 안 정사각형은 9 × 9 × 2 = 162 cm², 원 밖 정사각형은 9 × 9 × 4 = 324 cm²예요.","원의 넓이는 그 사이 — 162 cm²보다 넓고 324 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#2','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'sa','auto','반지름이 4 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 8 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 4 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 8 cm예요. 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","8 × 8 ÷ 2 = 32예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 6 cm예요. 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","6 × 6 ÷ 2 = 18이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#3','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'error','auto','반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원의 넓이는 100 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"나린 — 「원 안 정사각형의 넓이는 50 cm²야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원 밖 정사각형의 넓이는 100 cm²야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원의 넓이는 약 75 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 50 cm², 원 밖 정사각형은 100 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 100 cm²보다 넓다는 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원의 넓이는 144 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"하린 — 「원 안 정사각형의 넓이는 72 cm²야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원 밖 정사각형의 넓이는 144 cm²야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원의 넓이는 약 108 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 72 cm², 원 밖 정사각형은 144 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 144 cm²보다 넓다는 수아의 말이 잘못되었어요."]},{"stem":"반지름이 4 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「원의 넓이는 64 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"지호 — 「원 안 정사각형의 넓이는 32 cm²야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원 밖 정사각형의 넓이는 64 cm²야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원의 넓이는 약 48 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 32 cm², 원 밖 정사각형은 64 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 64 cm²보다 넓다는 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#4','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'ox','auto','원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":3,"kind":"ox","stem":"원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.","answer":"O","reason_options":[{"t":"원 안 정사각형이 원 밖 정사각형의 반이고 원은 그보다 넓기 때문에","correct":true},{"t":"원이 원 밖 정사각형보다 넓기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 안에 꼭 맞는 정사각형의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반이에요.","answer":"O","reason_options":[{"t":"반지름 정사각형 2개와 4개이기 때문에","correct":true},{"t":"두 정사각형의 넓이가 같기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"원의 넓이는 원 안에 꼭 맞는 정사각형보다 좁아요.","answer":"X","reason_options":[{"t":"정사각형이 원 안에 들어 있으니 원이 더 넓기 때문에","correct":true},{"t":"정사각형은 모서리가 있어 더 넓기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#5','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'match','auto','원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":3,"kind":"match","stem":"원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 3 cm","r":"18 cm²보다 넓고 36 cm²보다 좁아요"},{"l":"반지름 4 cm","r":"32 cm²보다 넓고 64 cm²보다 좁아요"},{"l":"반지름 6 cm","r":"72 cm²보다 넓고 144 cm²보다 좁아요"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"8 cm²보다 넓고 16 cm²보다 좁아요"},{"l":"반지름 5 cm","r":"50 cm²보다 넓고 100 cm²보다 좁아요"},{"l":"반지름 7 cm","r":"98 cm²보다 넓고 196 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 1 cm","r":"2 cm²보다 넓고 4 cm²보다 좁아요"},{"l":"반지름 8 cm","r":"128 cm²보다 넓고 256 cm²보다 좁아요"},{"l":"반지름 10 cm","r":"200 cm²보다 넓고 400 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#6','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','반지름이 7 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 7 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u5-X10"},{"t":"202 cm²","mis":"M6-2-u5-X10"},{"t":"49 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 7 × 7 × 2 = 98 cm²보다 넓어요.","또 7 × 7 × 4 = 196 cm²보다 좁아요.","그 사이에 있는 것은 153.86 cm²뿐이에요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"126 cm²","mis":"M6-2-u5-X10"},{"t":"262 cm²","mis":"M6-2-u5-X10"},{"t":"64 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 8 × 8 × 2 = 128 cm²보다 넓어요.","또 8 × 8 × 4 = 256 cm²보다 좁아요.","그 사이에 있는 것은 200.96 cm²뿐이에요."]},{"stem":"반지름이 9 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"160 cm²","mis":"M6-2-u5-X10"},{"t":"330 cm²","mis":"M6-2-u5-X10"},{"t":"81 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 9 × 9 × 2 = 162 cm²보다 넓어요.","또 9 × 9 × 4 = 324 cm²보다 좁아요.","그 사이에 있는 것은 254.34 cm²뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#7','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','반지름이 8 cm인 원 모양 시계를 만들려고 해요. 시계의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10','M6-2-u5-X01']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 8 cm인 원 모양 시계를 만들려고 해요. 시계의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"192 cm²","correct":true},{"t":"64 cm²","mis":"M6-2-u5-X11"},{"t":"335 cm²","mis":"M6-2-u5-X10"},{"t":"16 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","8 × 8 = 64니 넓이는 128 cm²와 256 cm² 사이예요.","그 한가운데쯤인 약 3배 — 192 cm²가 가장 가까워요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 모양 케이크를 만들려고 해요. 케이크의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"108 cm²","correct":true},{"t":"36 cm²","mis":"M6-2-u5-X11"},{"t":"195 cm²","mis":"M6-2-u5-X10"},{"t":"12 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","6 × 6 = 36이니 넓이는 72 cm²와 144 cm² 사이예요.","그 한가운데쯤인 약 3배 — 108 cm²가 가장 가까워요."]},{"stem":"반지름이 9 cm인 원 모양 쟁반을 만들려고 해요. 쟁반의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"243 cm²","correct":true},{"t":"81 cm²","mis":"M6-2-u5-X11"},{"t":"420 cm²","mis":"M6-2-u5-X10"},{"t":"18 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","9 × 9 = 81이니 넓이는 162 cm²와 324 cm² 사이예요.","그 한가운데쯤인 약 3배 — 243 cm²가 가장 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#8','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 넓이가 64 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":4,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 64 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","64 ÷ 2 = 32 cm²예요."],"variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 36 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","36 ÷ 2 = 18 cm²예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 16 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["8"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","16 ÷ 2 = 8 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#9','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','반지름이 5 cm인 원의 넓이가 약 75 cm²쯤이라고 어림할 수 있는 까닭을 원 안과 밖에 꼭 맞는 정사각형으로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 원의 넓이가 약 75 cm²쯤이라고 어림할 수 있는 까닭을 원 안과 밖에 꼭 맞는 정사각형으로 설명해 보세요.","answer_guide":{"answer":"예: 원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²이다. 원의 넓이는 50 cm²보다 넓고 100 cm²보다 좁으니, 그 한가운데쯤인 (반지름) × (반지름)의 약 3배, 곧 약 75 cm²로 어림할 수 있다.","scoring_points":["원 안 정사각형 50 cm²를 구했는가","원 밖 정사각형 100 cm²를 구했는가","그 사이의 약 3배로 75 cm²를 어림했는가"]},"explanation":["원 안 정사각형은 50 cm²예요.","원 밖 정사각형은 100 cm²예요.","그 사이 한가운데쯤 — 약 75 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#10','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','모눈 칸 세기와 정사각형 어림, 두 방법으로 원의 넓이를 어림했어요. 두 방법의 좋은 점을 하나씩 쓰고, 어림이 무엇을 찾는 일인지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"모눈 칸 세기와 정사각형 어림, 두 방법으로 원의 넓이를 어림했어요. 두 방법의 좋은 점을 하나씩 쓰고, 어림이 무엇을 찾는 일인지 설명해 보세요.","answer_guide":{"answer":"예: 모눈 칸 세기는 범위를 더 좁게 찾을 수 있고, 정사각형 어림은 칸을 세지 않고 반지름만으로 빠르게 범위를 구할 수 있다. 어림은 정확한 값이 아니라 넓이가 들어갈 범위를 찾는 일이다.","scoring_points":["모눈 칸 세기의 좋은 점을 썼는가","정사각형 어림의 좋은 점을 썼는가","어림은 범위를 찾는 일이라고 밝혔는가"]},"explanation":["모눈은 범위가 좁아요.","정사각형은 반지름만으로 빨라요.","어림은 넓이가 들어갈 범위를 찾는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#1','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?","options":[{"t":"원주의 반","correct":true},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"반지름","mis":"M6-2-u5-X15"}],"explanation":["잘라 낸 부채꼴이 위아래로 번갈아 놓여요.","원주의 반은 위쪽에, 나머지 반은 아래쪽에 놓여요.","그래서 가로는 원주의 반이에요."],"variant_rule":{"alt":[{"stem":"원을 한없이 잘라서 이어 붙여 만든 직사각형에서 세로는 원의 무엇과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"원주의 반","mis":"M6-2-u5-X15"}],"explanation":["부채꼴 한 조각의 길이가 반지름이에요.","조각을 세워 이어 붙이니 높이가 반지름이 돼요.","그래서 세로는 반지름이에요."]},{"stem":"원을 한없이 잘라 이어 붙여 만든 직사각형의 넓이는 처음 원의 넓이와 견주어 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"더 넓어요","mis":"M6-2-u5-X17"},{"t":"더 좁아요","mis":"M6-2-u5-X17"},{"t":"두 배예요","mis":"M6-2-u5-X15"}],"explanation":["원을 자르고 이어 붙였을 뿐이에요.","조각을 더하거나 덜어 내지 않았어요.","그래서 직사각형의 넓이는 원의 넓이와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#2','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X14']::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × (반지름) × (원주율)","correct":true},{"t":"(지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(지름) × (지름) × (원주율)","mis":"M6-2-u5-X13"},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X14"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","가로는 원주의 반 — (반지름) × (원주율), 세로는 반지름이에요.","그래서 (원의 넓이) = (반지름) × (반지름) × (원주율)이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5 × 5 × 3.14","correct":true},{"t":"10 × 3.14","mis":"M6-2-u5-X12"},{"t":"10 × 10 × 3.14","mis":"M6-2-u5-X13"},{"t":"5 × 3.14","mis":"M6-2-u5-X14"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름 5를 두 번 곱하고 3.14를 곱해요.","10 × 3.14는 원주를 구하는 식이에요."]},{"stem":"반지름이 3 cm인 원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 3 × 3.14","correct":true},{"t":"6 × 3.14","mis":"M6-2-u5-X12"},{"t":"6 × 6 × 3.14","mis":"M6-2-u5-X13"},{"t":"3 × 3.14","mis":"M6-2-u5-X14"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름 3을 두 번 곱하고 3.14를 곱해요.","6 × 3.14는 원주를 구하는 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#3','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#4','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','반지름이 10 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#5','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','지름이 24 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#6','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 5 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 15.7 cm, 세로 5 cm","correct":true},{"t":"가로 31.4 cm, 세로 5 cm","mis":"M6-2-u5-X15"},{"t":"가로 15.7 cm, 세로 10 cm","mis":"M6-2-u5-X15"},{"t":"가로 31.4 cm, 세로 10 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 10 × 3.14 = 31.4 cm예요.","가로는 원주의 반 — 15.7 cm예요.","세로는 반지름 — 5 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 9.42 cm, 세로 3 cm","correct":true},{"t":"가로 18.84 cm, 세로 3 cm","mis":"M6-2-u5-X15"},{"t":"가로 9.42 cm, 세로 6 cm","mis":"M6-2-u5-X15"},{"t":"가로 18.84 cm, 세로 6 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 6 × 3.14 = 18.84 cm예요.","가로는 원주의 반 — 9.42 cm예요.","세로는 반지름 — 3 cm예요."]},{"stem":"반지름이 10 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 31.4 cm, 세로 10 cm","correct":true},{"t":"가로 62.8 cm, 세로 10 cm","mis":"M6-2-u5-X15"},{"t":"가로 31.4 cm, 세로 20 cm","mis":"M6-2-u5-X15"},{"t":"가로 62.8 cm, 세로 20 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 20 × 3.14 = 62.8 cm예요.","가로는 원주의 반 — 31.4 cm예요.","세로는 반지름 — 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#7','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"원 모양 거울","correct":true},{"t":"직사각형 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 30 × 30 × 3.14 = 2826 cm²예요.","직사각형 모양 거울은 70 × 40 = 2800 cm²예요.","그래서 원 모양 거울이 더 넓어요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 거울과 가로 18 cm, 세로 18 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"직사각형 모양 거울","correct":true},{"t":"원 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 10 × 10 × 3.14 = 314 cm²예요.","직사각형 모양 거울은 18 × 18 = 324 cm²예요.","그래서 직사각형 모양 거울이 더 넓어요."]},{"stem":"반지름이 20 cm인 원 모양 거울과 가로 40 cm, 세로 30 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"원 모양 거울","correct":true},{"t":"직사각형 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 20 × 20 × 3.14 = 1256 cm²예요.","직사각형 모양 거울은 40 × 30 = 1200 cm²예요.","그래서 원 모양 거울이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#8','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 넓이를 구하는 식이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(반지름) × 2 × (원주율)은 넓이를 구하는 식이 아니에요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (지름) × (원주율)은 넓이를 구하는 식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#9','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 30 cm인 원 모양 거울이 있어요. 이 거울의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 30 cm인 원 모양 거울이 있어요. 이 거울의 넓이는 몇 cm²인가요?","options":[{"t":"2826 cm²","correct":true},{"t":"188.4 cm²","mis":"M6-2-u5-X12"},{"t":"94.2 cm²","mis":"M6-2-u5-X14"},{"t":"11304 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","30 × 30 × 3.14를 계산해요.","30 × 30 × 3.14 = 2826 — 넓이는 2826 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 20 cm인 원 모양 식탁보가 있어요. 이 식탁보의 넓이는 몇 cm²인가요?","options":[{"t":"1256 cm²","correct":true},{"t":"125.6 cm²","mis":"M6-2-u5-X12"},{"t":"62.8 cm²","mis":"M6-2-u5-X14"},{"t":"5024 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","20 × 20 × 3.14를 계산해요.","20 × 20 × 3.14 = 1256 — 넓이는 1256 cm²예요."]},{"stem":"반지름이 15 cm인 원 모양 매트가 있어요. 이 매트의 넓이는 몇 cm²인가요?","options":[{"t":"706.5 cm²","correct":true},{"t":"94.2 cm²","mis":"M6-2-u5-X12"},{"t":"47.1 cm²","mis":"M6-2-u5-X14"},{"t":"2826 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","15 × 15 × 3.14를 계산해요.","15 × 15 × 3.14 = 706.5 — 넓이는 706.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#10','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',3,'sa','auto','넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]},{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#1','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'mc','auto','반지름이 7 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 7 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"43.96 cm²","mis":"M6-2-u5-X12"},{"t":"21.98 cm²","mis":"M6-2-u5-X14"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","7 × 7 × 3.14를 계산해요.","7 × 7 × 3.14 = 153.86 — 넓이는 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]},{"stem":"반지름이 9 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X12"},{"t":"28.26 cm²","mis":"M6-2-u5-X14"},{"t":"1017.36 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","9 × 9 × 3.14를 계산해요.","9 × 9 × 3.14 = 254.34 — 넓이는 254.34 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#2','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'sa','auto','넓이가 314 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":2,"kind":"sa","stem":"넓이가 314 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["20"],"explanation":["314 ÷ 3.14 = 100 — (반지름) × (반지름) = 100이에요.","반지름은 10 cm예요.","지름은 반지름의 2배 — 20 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 50.24 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["8"],"explanation":["50.24 ÷ 3.14 = 16 — (반지름) × (반지름) = 16이에요.","반지름은 4 cm예요.","지름은 반지름의 2배 — 8 cm예요."]},{"stem":"넓이가 113.04 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["12"],"explanation":["113.04 ÷ 3.14 = 36 — (반지름) × (반지름) = 36이에요.","반지름은 6 cm예요.","지름은 반지름의 2배 — 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#3','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'error','auto','반지름이 4 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":3,"kind":"error","stem":"반지름이 4 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「8 × 8 × 3.14 = 200.96이야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"나린 — 「4 × 4 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「12.56 × 4 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「넓이는 50.24 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","가온는 지름 8 cm를 두 번 곱했어요.","바른 넓이는 4 × 4 × 3.14 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「10 × 10 × 3.14 = 314야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"하린 — 「5 × 5 × 3.14 = 78.5야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「15.7 × 5 = 78.5야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「넓이는 78.5 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","수아는 지름 10 cm를 두 번 곱했어요.","바른 넓이는 5 × 5 × 3.14 = 78.5 cm²예요."]},{"stem":"반지름이 3 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「6 × 6 × 3.14 = 113.04야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"지호 — 「3 × 3 × 3.14 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「9.42 × 3 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「넓이는 28.26 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","서아는 지름 6 cm를 두 번 곱했어요.","바른 넓이는 3 × 3 × 3.14 = 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#4','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'ox','auto','원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":3,"kind":"ox","stem":"원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.","answer":"O","reason_options":[{"t":"이어 붙인 직사각형의 가로가 원주의 반, 세로가 반지름이기 때문에","correct":true},{"t":"원주의 반이 넓이이기 때문에","mis":"M6-2-u5-X15"}],"mis":"M6-2-u5-X15","explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."],"variant_rule":{"alt":[{"stem":"원의 넓이는 (지름) × (원주율)로 구해요.","answer":"X","reason_options":[{"t":"(지름) × (원주율)은 원주를 구하는 식이기 때문에","correct":true},{"t":"넓이도 둘레처럼 지름에 원주율을 곱하기 때문에","mis":"M6-2-u5-X12"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]},{"stem":"반지름이 5 cm인 원의 넓이는 5 × 3.14로 구해요.","answer":"X","reason_options":[{"t":"반지름을 두 번 곱해 5 × 5 × 3.14로 구해야 하기 때문에","correct":true},{"t":"반지름에 원주율을 한 번 곱하면 넓이이기 때문에","mis":"M6-2-u5-X14"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#5','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'match','auto','반지름과 원의 넓이를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":3,"kind":"match","stem":"반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 1 cm","r":"3.14 cm²"},{"l":"반지름 2 cm","r":"12.56 cm²"},{"l":"반지름 5 cm","r":"78.5 cm²"}],"mis":"M6-2-u5-X14","explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","1 × 1 × 3.14 = 3.14 · 2 × 2 × 3.14 = 12.56이에요.","5 × 5 × 3.14 = 78.5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 3 cm","r":"28.26 cm²"},{"l":"반지름 4 cm","r":"50.24 cm²"},{"l":"반지름 10 cm","r":"314 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","3 × 3 × 3.14 = 28.26 · 4 × 4 × 3.14 = 50.24예요.","10 × 10 × 3.14 = 314예요."]},{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 6 cm","r":"113.04 cm²"},{"l":"반지름 7 cm","r":"153.86 cm²"},{"l":"반지름 8 cm","r":"200.96 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","6 × 6 × 3.14 = 113.04 · 7 × 7 × 3.14 = 153.86이에요.","8 × 8 × 3.14 = 200.96이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#6','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 18.84 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X13"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm, 반지름은 3 cm예요.","넓이는 3 × 3 × 3.14예요.","3 × 3 × 3.14 = 28.26 cm²예요."]},{"stem":"원주가 62.8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm, 반지름은 10 cm예요.","넓이는 10 × 10 × 3.14예요.","10 × 10 × 3.14 = 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#7','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','원을 한없이 잘라 이어 붙였더니 가로 15.7 cm, 세로 5 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X15','M6-2-u5-X12','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원을 한없이 잘라 이어 붙였더니 가로 15.7 cm, 세로 5 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"157 cm²","mis":"M6-2-u5-X15"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"20.7 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 15.7 × 5예요.","15.7 × 5 = 78.5 — 원의 넓이도 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"원을 한없이 잘라 이어 붙였더니 가로 9.42 cm, 세로 3 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X15"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"12.42 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 9.42 × 3이에요.","9.42 × 3 = 28.26 — 원의 넓이도 28.26 cm²예요."]},{"stem":"원을 한없이 잘라 이어 붙였더니 가로 31.4 cm, 세로 10 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"628 cm²","mis":"M6-2-u5-X15"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"41.4 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 31.4 × 10이에요.","31.4 × 10 = 314 — 원의 넓이도 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#8','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]},{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#9','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'mc','auto','길이가 62.8 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X14','M6-2-u5-X19']::text[],true,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"길이가 62.8 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 20 cm, 반지름 10 cm — 넓이 314 cm²예요.","정사각형은 한 변 15.7 cm — 넓이 246.49 cm²예요.","둘레가 같을 때 원이 더 넓어요."],"variant_rule":{"alt":[{"stem":"길이가 125.6 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 40 cm, 반지름 20 cm — 넓이 1256 cm²예요.","정사각형은 한 변 31.4 cm — 넓이 985.96 cm²예요.","둘레가 같을 때 원이 더 넓어요."]},{"stem":"길이가 31.4 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 10 cm, 반지름 5 cm — 넓이 78.5 cm²예요.","정사각형은 한 변 7.85 cm — 넓이 61.6225 cm²예요.","둘레가 같을 때 원이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#10','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'essay','teacher','원을 한없이 잘라 이어 붙인 직사각형을 이용하여 (원의 넓이) = (반지름) × (반지름) × (원주율)이 되는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"원을 한없이 잘라 이어 붙인 직사각형을 이용하여 (원의 넓이) = (반지름) × (반지름) × (원주율)이 되는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원을 한없이 잘라 이어 붙이면 가로가 원주의 반, 세로가 반지름인 직사각형이 된다. 넓이는 (원주) × ⟨1/2⟩ × (반지름)이고, 원주는 (지름) × (원주율)이며 지름의 반은 반지름이므로 (반지름) × (반지름) × (원주율)이 된다.","scoring_points":["직사각형의 가로가 원주의 반, 세로가 반지름임을 밝혔는가","원주 = (지름) × (원주율)을 넣었는가","지름의 반이 반지름임을 써서 식을 완성했는가"]},"explanation":["가로는 원주의 반, 세로는 반지름이에요.","원주의 반은 (지름) × (원주율) × ⟨1/2⟩ = (반지름) × (원주율)이에요.","그래서 넓이는 (반지름) × (반지름) × (원주율)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#1','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','달곰이 작품의 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X17']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"달곰이 작품의 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?","options":[{"t":"3.14 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X13"},{"t":"1.57 cm²","mis":"M6-2-u5-X17"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","1 × 1 × 3.14를 계산해요.","1 × 1 × 3.14 = 3.14 — 넓이는 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"여울이 작품의 한가운데는 반지름이 2 cm인 원이에요. 이 부분의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"순달이 작품의 한가운데는 반지름이 3 cm인 원이에요. 이 부분의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#2','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"25.12 cm²","correct":true},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"31.4 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","28.26 - 3.14 = 25.12 cm²예요."]},{"stem":"반지름이 5 cm인 원에서 반지름이 2 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"65.94 cm²","correct":true},{"t":"78.5 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"91.06 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","작은 원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","78.5 - 12.56 = 65.94 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#3','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":1,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."],"variant_rule":{"alt":[{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 8 cm, 세로 4 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","8 × 4 = 32 cm²예요."]},{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 12 cm, 세로 6 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","12 × 6 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#4','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."],"variant_rule":{"alt":[{"stem":"반원 하나를 잘라 반대쪽에 붙여 새 모양을 만들었어요. 처음 모양과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]},{"stem":"부채꼴 조각을 번갈아 뒤집어 이어 붙였어요. 처음 원과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#5','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','다 부분은 반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"다 부분은 반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]},{"stem":"반지름이 8 cm인 원에서 반지름이 5 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"122.46 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"279.46 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 8 × 8 × 3.14 = 200.96 cm²예요.","작은 원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","200.96 - 78.5 = 122.46 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#6','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','반지름이 4 cm인 반원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"25.12 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X13"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","50.24 ÷ 2 = 25.12 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X17"},{"t":"28.26 cm²","mis":"M6-2-u5-X17"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","113.04 ÷ 2 = 56.52 cm²예요."]},{"stem":"반지름이 10 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","314 ÷ 4 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#7','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]},{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#8','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 4 × 4 × 3.14 = 50.24 m²예요.","나는 8 × 8 × 3.14 ÷ 4 = 50.24 m²예요.","두 꽃밭의 넓이는 같아요."],"variant_rule":{"alt":[{"stem":"꽃밭 가는 반지름이 3 m인 원 모양이고, 꽃밭 나는 반지름이 6 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 3 × 3 × 3.14 = 28.26 m²예요.","나는 6 × 6 × 3.14 ÷ 4 = 28.26 m²예요.","두 꽃밭의 넓이는 같아요."]},{"stem":"꽃밭 가는 반지름이 5 m인 원 모양이고, 꽃밭 나는 반지름이 10 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 5 × 5 × 3.14 = 78.5 m²예요.","나는 10 × 10 × 3.14 ÷ 4 = 78.5 m²예요.","두 꽃밭의 넓이는 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#9','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','반지름이 10 cm인 큰 원 안에 반지름이 5 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 10 cm인 큰 원 안에 반지름이 5 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"157 cm²","correct":true},{"t":"235.5 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"78.5 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","작은 원 하나는 5 × 5 × 3.14 = 78.5 cm², 두 개는 157 cm²예요.","314 - 157 = 157 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 큰 원 안에 반지름이 4 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"100.48 cm²","correct":true},{"t":"150.72 cm²","mis":"M6-2-u5-X17"},{"t":"200.96 cm²","mis":"M6-2-u5-X16"},{"t":"50.24 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 8 × 8 × 3.14 = 200.96 cm²예요.","작은 원 하나는 4 × 4 × 3.14 = 50.24 cm², 두 개는 100.48 cm²예요.","200.96 - 100.48 = 100.48 cm²예요."]},{"stem":"반지름이 6 cm인 큰 원 안에 반지름이 3 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"84.78 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원 하나는 3 × 3 × 3.14 = 28.26 cm², 두 개는 56.52 cm²예요.","113.04 - 56.52 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#10','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#1','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'mc','auto','라 부분은 반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"라 부분은 반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"141.3 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"367.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 9 × 9 × 3.14 = 254.34 cm²예요.","작은 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","254.34 - 113.04 = 141.3 cm²예요."]},{"stem":"반지름이 12 cm인 원에서 반지름이 10 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"138.16 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"766.16 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","452.16 - 314 = 138.16 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#2','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'mc','auto','반지름이 8 cm인 사분원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 8 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 8 × 8 × 3.14 = 200.96 cm²예요.","200.96 ÷ 4 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 12 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","452.16 ÷ 2 = 226.08 cm²예요."]},{"stem":"반지름이 2 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"3.14 cm²","correct":true},{"t":"12.56 cm²","mis":"M6-2-u5-X17"},{"t":"6.28 cm²","mis":"M6-2-u5-X17"},{"t":"25.12 cm²","mis":"M6-2-u5-X20"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","12.56 ÷ 4 = 3.14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#3','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'error','auto','반지름이 5 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「5 - 3 = 2니 2 × 2 × 3.14 = 12.56이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"나린 — 「78.5 - 28.26 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「(5 × 5 - 3 × 3) × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「넓이는 50.24 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 50.24 cm² — 가온의 방법이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 2 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「6 - 2 = 4니 4 × 4 × 3.14 = 50.24야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"하린 — 「113.04 - 12.56 = 100.48이야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「(6 × 6 - 2 × 2) × 3.14 = 100.48이야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「넓이는 100.48 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 100.48 cm² — 수아의 방법이 잘못되었어요."]},{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「7 - 4 = 3이니 3 × 3 × 3.14 = 28.26이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"지호 — 「153.86 - 50.24 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「(7 × 7 - 4 × 4) × 3.14 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「넓이는 103.62 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 103.62 cm² — 서아의 방법이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#4','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'ox','auto','반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":3,"kind":"ox","stem":"반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.","answer":"O","reason_options":[{"t":"8 × 8 × 3.14 ÷ 4 = 4 × 4 × 3.14이기 때문에","correct":true},{"t":"사분원은 원의 반이기 때문에","mis":"M6-2-u5-X17"}],"mis":"M6-2-u5-X17","explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."],"variant_rule":{"alt":[{"stem":"고리 모양의 넓이는 두 반지름의 차를 반지름으로 하는 원의 넓이와 같아요.","answer":"X","reason_options":[{"t":"큰 원의 넓이에서 작은 원의 넓이를 빼야 하기 때문에","correct":true},{"t":"고리의 폭이 반지름의 차이기 때문에","mis":"M6-2-u5-X16"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]},{"stem":"원을 잘라 다른 자리에 옮겨 붙이면 넓이가 넓어져요.","answer":"X","reason_options":[{"t":"조각을 더하거나 덜지 않고 자리만 옮겼기 때문에","correct":true},{"t":"모양이 바뀌면 넓이도 바뀌기 때문에","mis":"M6-2-u5-X17"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#5','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'match','auto','반지름이 2 cm인 도형과 넓이를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":3,"kind":"match","stem":"반지름이 2 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"12.56 cm²"},{"l":"반원","r":"6.28 cm²"},{"l":"사분원","r":"3.14 cm²"}],"mis":"M6-2-u5-X17","explanation":["원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","반원은 그 반 — 6.28 cm²예요.","사분원은 4로 나눈 하나 — 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"50.24 cm²"},{"l":"반원","r":"25.12 cm²"},{"l":"사분원","r":"12.56 cm²"}],"explanation":["원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","반원은 그 반 — 25.12 cm²예요.","사분원은 4로 나눈 하나 — 12.56 cm²예요."]},{"stem":"반지름이 10 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"314 cm²"},{"l":"반원","r":"157 cm²"},{"l":"사분원","r":"78.5 cm²"}],"explanation":["원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","반원은 그 반 — 157 cm²예요.","사분원은 4로 나눈 하나 — 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#6','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','가로 20 cm, 세로 10 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"가로 20 cm, 세로 10 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"278.5 cm²","correct":true},{"t":"239.25 cm²","mis":"M6-2-u5-X17"},{"t":"357 cm²","mis":"M6-2-u5-X17"},{"t":"514 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 20 × 10 = 200 cm²예요.","양쪽 반원 두 개를 모으면 반지름 5 cm인 원 하나 — 78.5 cm²예요.","200 + 78.5 = 278.5 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 30 cm, 세로 20 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"914 cm²","correct":true},{"t":"757 cm²","mis":"M6-2-u5-X17"},{"t":"1228 cm²","mis":"M6-2-u5-X17"},{"t":"1856 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 30 × 20 = 600 cm²예요.","양쪽 반원 두 개를 모으면 반지름 10 cm인 원 하나 — 314 cm²예요.","600 + 314 = 914 cm²예요."]},{"stem":"가로 10 cm, 세로 8 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"130.24 cm²","correct":true},{"t":"105.12 cm²","mis":"M6-2-u5-X17"},{"t":"180.48 cm²","mis":"M6-2-u5-X17"},{"t":"280.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 10 × 8 = 80 cm²예요.","양쪽 반원 두 개를 모으면 반지름 4 cm인 원 하나 — 50.24 cm²예요.","80 + 50.24 = 130.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#7','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','바깥쪽 원의 반지름이 6 cm이고 폭이 2 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X01']::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 반지름이 6 cm이고 폭이 2 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"62.8 cm²","correct":true},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"100.48 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 6 - 2 = 4 cm예요.","큰 원 113.04 cm²에서 작은 원 50.24 cm²를 빼요.","113.04 - 50.24 = 62.8 cm²예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 반지름이 10 cm이고 폭이 3 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"285.74 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 10 - 3 = 7 cm예요.","큰 원 314 cm²에서 작은 원 153.86 cm²를 빼요.","314 - 153.86 = 160.14 cm²예요."]},{"stem":"바깥쪽 원의 반지름이 5 cm이고 폭이 1 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"3.14 cm²","mis":"M6-2-u5-X16"},{"t":"78.5 cm²","mis":"M6-2-u5-X16"},{"t":"75.36 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 5 - 1 = 4 cm예요.","큰 원 78.5 cm²에서 작은 원 50.24 cm²를 빼요.","78.5 - 50.24 = 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#8','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'mc','auto','반지름이 10 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X17']::text[],true,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":4,"kind":"mc","stem":"반지름이 10 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"114 cm²","correct":true},{"t":"86 cm²","mis":"M6-2-u5-X11"},{"t":"214 cm²","mis":"M6-2-u5-X11"},{"t":"314 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","원 안 정사각형은 대각선이 20 cm — 20 × 20 ÷ 2 = 200 cm²예요.","314 - 200 = 114 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"28.5 cm²","correct":true},{"t":"21.5 cm²","mis":"M6-2-u5-X11"},{"t":"53.5 cm²","mis":"M6-2-u5-X11"},{"t":"78.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","원 안 정사각형은 대각선이 10 cm — 10 × 10 ÷ 2 = 50 cm²예요.","78.5 - 50 = 28.5 cm²예요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"41.04 cm²","correct":true},{"t":"30.96 cm²","mis":"M6-2-u5-X11"},{"t":"77.04 cm²","mis":"M6-2-u5-X11"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","원 안 정사각형은 대각선이 12 cm — 12 × 12 ÷ 2 = 72 cm²예요.","113.04 - 72 = 41.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#9','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'mc','auto','달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 다 부분과 라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 4 cm인 원을 뺀 부분)는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":4,"kind":"mc","stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 다 부분과 라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 4 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"263.76 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"364.24 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","314 - 50.24 = 263.76 cm²예요."],"variant_rule":{"alt":[{"stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 나 부분과 다 부분을 합한 넓이(반지름 7 cm인 원에서 반지름 1 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"150.72 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"157 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","153.86 - 3.14 = 150.72 cm²예요."]},{"stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 나·다·라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 1 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"310.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"254.34 cm²","mis":"M6-2-u5-X16"},{"t":"317.14 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","314 - 3.14 = 310.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#10','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'essay','teacher','반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구하고, 친구가 (7 - 4) × (7 - 4) × 3.14로 구한 방법이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구하고, 친구가 (7 - 4) × (7 - 4) × 3.14로 구한 방법이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 고리의 넓이는 7 × 7 × 3.14 - 4 × 4 × 3.14 = 153.86 - 50.24 = 103.62 cm²이다. 반지름의 차 3 cm로 그린 원은 넓이가 28.26 cm²로 고리보다 훨씬 좁다. 고리는 큰 원에서 작은 원을 빼야 한다.","scoring_points":["고리의 넓이 103.62 cm²를 구했는가","반지름의 차로 만든 원의 넓이가 다름을 보였는가","큰 원에서 작은 원을 빼야 한다고 설명했는가"]},"explanation":["큰 원 153.86 cm² - 작은 원 50.24 cm² = 103.62 cm²예요.","(7 - 4) × (7 - 4) × 3.14 = 28.26 cm²로 달라요.","고리는 큰 원에서 작은 원을 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#1','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'mc','auto','동물 보호소에 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":1,"kind":"mc","stem":"동물 보호소에 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"동물 보호소에 반지름이 20 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"1256 cm²","correct":true},{"t":"125.6 cm²","mis":"M6-2-u5-X12"},{"t":"62.8 cm²","mis":"M6-2-u5-X14"},{"t":"5024 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","20 × 20 × 3.14를 계산해요.","20 × 20 × 3.14 = 1256 — 넓이는 1256 cm²예요."]},{"stem":"동물 보호소에 반지름이 5 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#2','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["1256 ÷ 314 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 10 cm인 방석의 넓이는 314 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["314 ÷ 78.5 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]},{"stem":"반지름이 3 cm인 방석의 넓이는 28.26 cm², 반지름이 6 cm인 방석의 넓이는 113.04 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["113.04 ÷ 28.26 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#3','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'mc','auto','반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X05','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":1,"kind":"mc","stem":"반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 2 × 2 = 4배가 되어서","correct":true},{"t":"반지름에 2를 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 2배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 4배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 곱하는 두 반지름이 모두 2배예요.","그래서 넓이는 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"반지름이 3배가 될 때 원의 넓이가 9배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 3 × 3 = 9배가 되어서","correct":true},{"t":"반지름에 3을 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 3배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 9배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 곱하는 두 반지름이 모두 3배예요.","그래서 넓이는 3 × 3 = 9배예요."]},{"stem":"반지름이 4배가 될 때 원의 넓이가 16배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 4 × 4 = 16배가 되어서","correct":true},{"t":"반지름에 4를 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 4배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 16배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 곱하는 두 반지름이 모두 4배예요.","그래서 넓이는 4 × 4 = 16배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#4','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]},{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#5','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','동물 보호소에 반지름이 30 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"동물 보호소에 반지름이 30 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"2826 cm²","correct":true},{"t":"188.4 cm²","mis":"M6-2-u5-X12"},{"t":"94.2 cm²","mis":"M6-2-u5-X14"},{"t":"11304 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","30 × 30 × 3.14를 계산해요.","30 × 30 × 3.14 = 2826 — 넓이는 2826 cm²예요."],"variant_rule":{"alt":[{"stem":"동물 보호소에 반지름이 15 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"706.5 cm²","correct":true},{"t":"94.2 cm²","mis":"M6-2-u5-X12"},{"t":"47.1 cm²","mis":"M6-2-u5-X14"},{"t":"2826 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","15 × 15 × 3.14를 계산해요.","15 × 15 × 3.14 = 706.5 — 넓이는 706.5 cm²예요."]},{"stem":"동물 보호소에 반지름이 25 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"1962.5 cm²","correct":true},{"t":"157 cm²","mis":"M6-2-u5-X12"},{"t":"78.5 cm²","mis":"M6-2-u5-X14"},{"t":"7850 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","25 × 25 × 3.14를 계산해요.","25 × 25 × 3.14 = 1962.5 — 넓이는 1962.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#6','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'sa','auto','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 30 cm인 방석의 넓이는 2826 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":2,"kind":"sa","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 30 cm인 방석의 넓이는 2826 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["2826 ÷ 314 = 9예요.","반지름이 3배가 되니 넓이는 3 × 3 = 9배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 15 cm인 방석의 넓이는 706.5 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["706.5 ÷ 78.5 = 9예요.","반지름이 3배가 되니 넓이는 3 × 3 = 9배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]},{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 4배가 되면 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["1256 ÷ 78.5 = 16이에요.","반지름이 4배가 되니 넓이는 4 × 4 = 16배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#7','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."],"variant_rule":{"alt":[{"stem":"반지름이 36 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 36 ÷ 12 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 4069.44 ÷ 452.16 = 9예요."]},{"stem":"반지름이 20 cm인 원의 넓이는 반지름이 5 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"16배","correct":true},{"t":"4배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X18"},{"t":"64배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 20 ÷ 5 = 4배예요.","넓이는 반지름을 두 번 곱하니 4 × 4 = 16배예요.","계산해 봐도 1256 ÷ 78.5 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#8','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?',ARRAY['M6-2-u5-X18','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"16배","mis":"M6-2-u5-X01"},{"t":"8배","mis":"M6-2-u5-X20"}],"explanation":["지름이 2배면 반지름도 2배예요.","넓이는 반지름을 두 번 곱해요.","2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"36배","mis":"M6-2-u5-X01"}],"explanation":["지름이 3배면 반지름도 3배예요.","넓이는 반지름을 두 번 곱해요.","3 × 3 = 9배예요."]},{"stem":"원의 지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"25배","correct":true},{"t":"5배","mis":"M6-2-u5-X18"},{"t":"10배","mis":"M6-2-u5-X18"},{"t":"100배","mis":"M6-2-u5-X01"}],"explanation":["지름이 5배면 반지름도 5배예요.","넓이는 반지름을 두 번 곱해요.","5 × 5 = 25배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#9','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X18"},{"t":"8개","mis":"M6-2-u5-X20"},{"t":"6개","mis":"M6-2-u5-X18"}],"explanation":["반지름이 2배인 방석이에요.","넓이는 2 × 2 = 4배예요.","그래서 작은 방석 4개를 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"반지름이 30 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"9개","correct":true},{"t":"3개","mis":"M6-2-u5-X18"},{"t":"6개","mis":"M6-2-u5-X18"},{"t":"18개","mis":"M6-2-u5-X20"}],"explanation":["반지름이 3배인 방석이에요.","넓이는 3 × 3 = 9배예요.","그래서 작은 방석 9개를 만들 수 있어요."]},{"stem":"반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 5 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"16개","correct":true},{"t":"4개","mis":"M6-2-u5-X18"},{"t":"8개","mis":"M6-2-u5-X18"},{"t":"32개","mis":"M6-2-u5-X20"}],"explanation":["반지름이 4배인 방석이에요.","넓이는 4 × 4 = 16배예요.","그래서 작은 방석 16개를 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#10','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',3,'error','auto','반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":3,"kind":"error","stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세호 — 「2배일 때 4배였으니 3배면 6배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"여울 — 「반지름을 두 번 곱하니 3 × 3 = 9배야.」","mis":"M6-2-u5-X19"},{"t":"달곰 — 「계산해 보면 넓이가 9배로 나와.」","mis":"M6-2-u5-X19"},{"t":"순달 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 3배면 넓이는 3 × 3 = 9배예요.","세호는 2배씩 늘린다고 생각했어요 — 6배가 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 4배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2배일 때 4배였으니 4배면 8배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"나린 — 「반지름을 두 번 곱하니 4 × 4 = 16배야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「계산해 보면 넓이가 16배로 나와.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 4배면 넓이는 4 × 4 = 16배예요.","가온는 2배씩 늘린다고 생각했어요 — 8배가 아니에요."]},{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 5배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「2배일 때 4배였으니 5배면 10배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"하린 — 「반지름을 두 번 곱하니 5 × 5 = 25배야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「계산해 보면 넓이가 25배로 나와.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 5배면 넓이는 5 × 5 = 25배예요.","수아는 2배씩 늘린다고 생각했어요 — 10배가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#1','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'sa','auto','원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":2,"kind":"sa","stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 6배가 되면 원의 넓이는 몇 배가 되나요?","answer":["36"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 6배면 두 번 곱하는 반지름이 모두 6배예요.","6 × 6 = 36배가 돼요."]},{"stem":"원의 반지름이 7배가 되면 원의 넓이는 몇 배가 되나요?","answer":["49"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 7배면 두 번 곱하는 반지름이 모두 7배예요.","7 × 7 = 49배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#2','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'mc','auto','원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 2배, 넓이는 4배","correct":true},{"t":"원주는 2배, 넓이는 2배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 4배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 2배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 3배, 넓이는 9배","correct":true},{"t":"원주는 3배, 넓이는 3배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 9배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 3배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요."]},{"stem":"원의 반지름이 4배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 4배, 넓이는 16배","correct":true},{"t":"원주는 4배, 넓이는 4배","mis":"M6-2-u5-X18"},{"t":"원주는 16배, 넓이는 16배","mis":"M6-2-u5-X18"},{"t":"원주는 16배, 넓이는 4배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 4배예요.","넓이는 반지름을 두 번 곱하니 4 × 4 = 16배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#3','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'error','auto','반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 6배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":3,"kind":"error","stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 6배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「2배일 때 4배였으니 6배면 12배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"지호 — 「반지름을 두 번 곱하니 6 × 6 = 36배야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「계산해 보면 넓이가 36배로 나와.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 6배면 넓이는 6 × 6 = 36배예요.","서아는 2배씩 늘린다고 생각했어요 — 12배가 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 4배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「2배일 때 4배였으니 4배면 8배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"하린 — 「반지름을 두 번 곱하니 4 × 4 = 16배야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「계산해 보면 넓이가 16배로 나와.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 4배면 넓이는 4 × 4 = 16배예요.","수아는 2배씩 늘린다고 생각했어요 — 8배가 아니에요."]},{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2배일 때 4배였으니 3배면 6배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"나린 — 「반지름을 두 번 곱하니 3 × 3 = 9배야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「계산해 보면 넓이가 9배로 나와.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 3배면 넓이는 3 × 3 = 9배예요.","가온는 2배씩 늘린다고 생각했어요 — 6배가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#4','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'ox','auto','반지름이 3배가 되면 원주는 9배가 돼요.',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":3,"kind":"ox","stem":"반지름이 3배가 되면 원주는 9배가 돼요.","answer":"X","reason_options":[{"t":"원주는 길이를 한 번 곱하므로 3배가 되기 때문에","correct":true},{"t":"넓이처럼 원주도 3 × 3배가 되기 때문에","mis":"M6-2-u5-X18"}],"mis":"M6-2-u5-X18","explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."],"variant_rule":{"alt":[{"stem":"반지름이 2배가 되면 원의 넓이는 4배가 돼요.","answer":"O","reason_options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하기 때문에","correct":true},{"t":"반지름에 2를 두 번 더하기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]},{"stem":"지름이 2배가 되면 원의 넓이도 2배가 돼요.","answer":"X","reason_options":[{"t":"지름이 2배면 반지름도 2배라 넓이는 2 × 2 = 4배이기 때문에","correct":true},{"t":"지름과 넓이는 같은 배수로 늘기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#5','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'match','auto','반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":3,"kind":"match","stem":"반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 4배","r":"넓이 16배"}],"mis":"M6-2-u5-X18","explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 3 × 3 = 9 · 4 × 4 = 16이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 5배","r":"넓이 25배"},{"l":"반지름 6배","r":"넓이 36배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","3 × 3 = 9 · 5 × 5 = 25 · 6 × 6 = 36이에요."]},{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 4배","r":"넓이 16배"},{"l":"반지름 10배","r":"넓이 100배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 4 × 4 = 16 · 10 × 10 = 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#6','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["3"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 9인 수를 찾아요.","3 × 3 = 9 — 반지름은 3배예요."],"variant_rule":{"alt":[{"stem":"원의 넓이가 16배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["4"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 16인 수를 찾아요.","4 × 4 = 16 — 반지름은 4배예요."]},{"stem":"원의 넓이가 25배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["5"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 25인 수를 찾아요.","5 × 5 = 25 — 반지름은 5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#7','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["20"],"explanation":["넓이가 4배가 되려면 반지름은 □ × □ = 4인 □배예요.","□ = 2예요.","10 × 2 = 20 — 반지름을 20 cm로 해요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 9배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["30"],"explanation":["넓이가 9배가 되려면 반지름은 □ × □ = 9인 □배예요.","□ = 3이에요.","10 × 3 = 30 — 반지름을 30 cm로 해요."]},{"stem":"반지름이 15 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["30"],"explanation":["넓이가 4배가 되려면 반지름은 □ × □ = 4인 □배예요.","□ = 2예요.","15 × 2 = 30 — 반지름을 30 cm로 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#8','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'mc','auto','반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":4,"kind":"mc","stem":"반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"942 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X19"},{"t":"1570 cm²","mis":"M6-2-u5-X20"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 2배라 넓이가 4배 — 1256 cm²예요.","1256 - 314 = 942 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 방석과 반지름이 30 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"2512 cm²","correct":true},{"t":"628 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X16"},{"t":"2826 cm²","mis":"M6-2-u5-X19"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 3배라 넓이가 9배 — 2826 cm²예요.","2826 - 314 = 2512 cm²예요."]},{"stem":"반지름이 5 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"1177.5 cm²","correct":true},{"t":"235.5 cm²","mis":"M6-2-u5-X18"},{"t":"706.5 cm²","mis":"M6-2-u5-X16"},{"t":"1256 cm²","mis":"M6-2-u5-X19"}],"explanation":["작은 방석은 5 × 5 × 3.14 = 78.5 cm²예요.","큰 방석은 반지름이 4배라 넓이가 16배 — 1256 cm²예요.","1256 - 78.5 = 1177.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#9','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','순달이는 「반지름이 2배일 때 넓이가 4배였으니, 3배면 그 한 배 반인 6배가 되겠지!」라고 예상했어요. 반지름 10 cm와 30 cm인 방석의 넓이를 구해 예상을 확인하고, 바른 규칙을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"순달이는 「반지름이 2배일 때 넓이가 4배였으니, 3배면 그 한 배 반인 6배가 되겠지!」라고 예상했어요. 반지름 10 cm와 30 cm인 방석의 넓이를 구해 예상을 확인하고, 바른 규칙을 설명해 보세요.","answer_guide":{"answer":"예: 반지름 10 cm인 방석은 10 × 10 × 3.14 = 314 cm², 30 cm인 방석은 30 × 30 × 3.14 = 2826 cm²이다. 2826 ÷ 314 = 9이므로 6배가 아니라 9배이다. 넓이를 구할 때 반지름을 두 번 곱하므로 반지름이 □배면 넓이는 □ × □배가 된다.","scoring_points":["두 방석의 넓이 314 cm²와 2826 cm²를 구했는가","9배임을 보여 예상이 틀렸음을 밝혔는가","반지름을 두 번 곱하므로 □ × □배라는 규칙을 썼는가"]},"explanation":["314 cm²와 2826 cm²예요.","2826 ÷ 314 = 9 — 9배예요.","반지름을 두 번 곱하니 3 × 3 = 9배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#10','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','반지름이 2배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 2배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 2배, 넓이는 4배가 된다. 원주는 (지름) × (원주율)로 길이를 한 번만 곱하지만, 넓이는 (반지름) × (반지름) × (원주율)로 반지름을 두 번 곱하기 때문에 2 × 2 = 4배가 된다.","scoring_points":["원주 2배를 썼는가","넓이 4배를 썼는가","길이를 한 번 곱하는지 두 번 곱하는지로 까닭을 설명했는가"]},"explanation":["원주는 2배예요.","넓이는 2 × 2 = 4배예요.","넓이는 반지름을 두 번 곱하기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#1','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#2','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."]},{"stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#3','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."]},{"stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#4','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',1,'mc','auto','원주율을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]},{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#5','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',2,'ox','auto','지름이 길어지면 원주율도 커져요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#6','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',3,'mc','auto','냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#7','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 10 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]},{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#8','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 4 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]},{"stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#9','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]},{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#10','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#11','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',1,'sa','auto','길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."],"variant_rule":{"alt":[{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]},{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#12','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',2,'sa','auto','체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]},{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#13','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#14','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#15','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#16','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#17','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 24 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#18','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]},{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#19','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]},{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#20','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."]},{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#21','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',3,'mc','auto','세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]},{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#22','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#23','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."]},{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#24','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C8',4,'essay','teacher','세호는 「반지름이 4배가 되면 넓이도 4배야.」라고 말했어요. 세호의 말이 맞는지 판단하고, 반지름이 1 cm와 4 cm인 원의 넓이를 구해 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"세호는 「반지름이 4배가 되면 넓이도 4배야.」라고 말했어요. 세호의 말이 맞는지 판단하고, 반지름이 1 cm와 4 cm인 원의 넓이를 구해 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 반지름 1 cm인 원은 3.14 cm², 4 cm인 원은 50.24 cm²로 50.24 ÷ 3.14 = 16배이다. 넓이는 반지름을 두 번 곱하므로 4 × 4 = 16배가 된다.","scoring_points":["세호의 말이 틀렸다고 판단했는가","두 넓이를 구해 16배를 보였는가","두 번 곱하는 규칙을 썼는가"]},"explanation":["3.14 cm²와 50.24 cm²예요.","50.24 ÷ 3.14 = 16배예요.","4 × 4 = 16배 — 4배가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#25','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',4,'essay','teacher','반지름이 6 cm인 원의 원주를 6 × 3.14 = 18.84 cm로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"반지름이 6 cm인 원의 원주를 6 × 3.14 = 18.84 cm로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.","answer_guide":{"answer":"예: 반지름에 바로 원주율을 곱했다. 원주는 (지름) × (원주율)이므로 반지름에 2를 곱한 지름 12 cm를 써서 12 × 3.14 = 37.68 cm이다.","scoring_points":["반지름에 바로 곱한 것이 잘못임을 밝혔는가","지름 12 cm를 만들었는가","37.68 cm를 구했는가"]},"explanation":["반지름에 바로 3.14를 곱하면 안 돼요.","지름은 12 cm예요.","12 × 3.14 = 37.68 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#1','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',1,'mc','auto','원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#2','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."]},{"stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#3','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."]},{"stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#4','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',1,'mc','auto','원의 지름에 대한 원주의 비율을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."],"variant_rule":{"alt":[{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]},{"stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#5','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',2,'ox','auto','작은 동전과 큰 접시의 원주율은 같아요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#6','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',3,'mc','auto','물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#7','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 7 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]},{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#8','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 9 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]},{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#9','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]},{"stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#10','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]},{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#11','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."],"variant_rule":{"alt":[{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]},{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#12','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',2,'sa','auto','원주가 43.96 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]},{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#13','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#14','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#15','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#16','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 2 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X14','M6-2-u5-X13','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]},{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#17','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 10 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]},{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#18','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]},{"stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#19','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]},{"stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#20','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."]},{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#21','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',3,'mc','auto','하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]},{"stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#22','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',3,'sa','auto','가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]},{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#23','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]},{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#24','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',4,'essay','teacher','반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석의 넓이는 작은 방석의 몇 배인지 두 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석의 넓이는 작은 방석의 몇 배인지 두 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: ① 넓이를 직접 구하면 314 cm²와 1256 cm²이고 1256 ÷ 314 = 4배이다. ② 반지름이 2배이고 넓이는 반지름을 두 번 곱하므로 2 × 2 = 4배이다.","scoring_points":["두 넓이를 구해 4배를 보였는가","반지름이 2배임을 밝혔는가","두 번 곱하는 규칙으로 4배를 설명했는가"]},"explanation":["314 cm²와 1256 cm²예요.","1256 ÷ 314 = 4예요.","반지름 2배 → 2 × 2 = 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#25','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',4,'essay','teacher','길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름을 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름을 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 종이띠의 길이가 원주이다. (지름) = (원주) ÷ (원주율)이므로 78.5 ÷ 3.14 = 25 cm이고, 반지름은 25 ÷ 2 = 12.5 cm이다.","scoring_points":["종이띠의 길이가 원주임을 밝혔는가","지름 25 cm를 구했는가","반지름 12.5 cm를 구했는가"]},"explanation":["종이띠의 길이가 원주예요.","78.5 ÷ 3.14 = 25 cm예요.","반지름은 12.5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#1','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',1,'mc','auto','원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#2','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."]},{"stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#3','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."]},{"stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#4','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',1,'mc','auto','원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?',ARRAY['M6-2-u5-X06','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."],"variant_rule":{"alt":[{"stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#5','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',2,'ox','auto','원주율 3.14는 정확한 값이에요.',ARRAY['M6-2-u5-X06']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"mis":"M6-2-u5-X06","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."]},{"stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#6','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',3,'mc','auto','연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]},{"stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#7','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 15 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]},{"stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#8','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 5 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]},{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#9','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."]},{"stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#10','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#11','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#12','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',2,'sa','auto','원주가 50.24 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]},{"stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#13','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#14','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#15','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#16','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 4 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]},{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#17','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 16 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]},{"stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#18','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."]},{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#19','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."]},{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#20','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]},{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#21','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',3,'mc','auto','도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."],"variant_rule":{"alt":[{"stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."]},{"stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#22','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#23','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]},{"stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#24','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C8',4,'essay','teacher','넓이가 9배인 원 모양 방석을 만들려면 반지름을 몇 배로 해야 하는지 구하고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"넓이가 9배인 원 모양 방석을 만들려면 반지름을 몇 배로 해야 하는지 구하고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 3배로 해야 한다. 넓이는 반지름을 두 번 곱하므로 반지름이 □배면 넓이는 □ × □배이고, □ × □ = 9인 □는 3이다.","scoring_points":["3배라고 답했는가","넓이가 □ × □배라는 규칙을 썼는가","□ × □ = 9에서 3을 찾았는가"]},"explanation":["넓이는 반지름을 두 번 곱해요.","□ × □ = 9예요.","□ = 3 — 반지름을 3배로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#25','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',4,'essay','teacher','세 원 ㉠ 원주 47.1 cm, ㉡ 지름 16 cm, ㉢ 반지름 9 cm의 크기를 견주려고 해요. 어떻게 견주면 좋을지 쓰고 큰 원부터 차례로 놓아 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"세 원 ㉠ 원주 47.1 cm, ㉡ 지름 16 cm, ㉢ 반지름 9 cm의 크기를 견주려고 해요. 어떻게 견주면 좋을지 쓰고 큰 원부터 차례로 놓아 보세요.","answer_guide":{"answer":"예: 셋을 모두 지름으로 바꾸어 견준다. ㉠은 47.1 ÷ 3.14 = 15 cm, ㉡은 16 cm, ㉢은 9 × 2 = 18 cm이므로 큰 원부터 ㉢, ㉡, ㉠이다.","scoring_points":["같은 것(지름)으로 바꾸어 견준다고 썼는가","세 지름 15·16·18 cm를 구했는가","㉢, ㉡, ㉠ 차례를 썼는가"]},"explanation":["모두 지름으로 바꾸어요.","㉠ 15 cm, ㉡ 16 cm, ㉢ 18 cm예요.","큰 원부터 ㉢, ㉡, ㉠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#1','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',1,'mc','auto','원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#2','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."]},{"stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#3','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."]},{"stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#4','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',1,'mc','auto','어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]},{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#5','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',2,'ox','auto','원주는 지름의 약 3.14배예요.',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"mis":"M6-2-u5-X08","explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."],"variant_rule":{"alt":[{"stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#6','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',3,'mc','auto','냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."],"variant_rule":{"alt":[{"stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#7','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 4 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X08']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]},{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#8','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]},{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#9','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."]},{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#10','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]},{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#11','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."],"variant_rule":{"alt":[{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]},{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#12','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',2,'sa','auto','운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."]},{"stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#13','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#14','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#15','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#16','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 6 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]},{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#17','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 20 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."]},{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#18','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]},{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#19','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]},{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#20','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."]},{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#21','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',3,'mc','auto','여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."]},{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#22','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',3,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."]},{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#23','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."]},{"stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#24','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C8',4,'essay','teacher','반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 3배, 넓이는 9배가 된다. 원주는 길이를 한 번 곱해 구하지만 넓이는 반지름을 두 번 곱하므로 3 × 3 = 9배가 된다.","scoring_points":["원주 3배를 썼는가","넓이 9배를 썼는가","한 번·두 번 곱하는 차이로 설명했는가"]},"explanation":["원주는 3배예요.","넓이는 3 × 3 = 9배예요.","넓이는 반지름을 두 번 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#25','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',4,'essay','teacher','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 원주이므로 48 × 3.14 = 150.72 cm이다. 5바퀴면 150.72 × 5 = 753.6 cm이고, 100 cm = 1 m이므로 7.536 m이다.","scoring_points":["한 바퀴 거리가 원주임을 밝혔는가","753.6 cm를 구했는가","m로 바꾸어 7.536 m를 구했는가"]},"explanation":["원주는 150.72 cm예요.","5바퀴는 753.6 cm예요.","7.536 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C1','math',6,2,'u6',2,'원기둥의 뜻 — 각기둥·각뿔을 되짚고, 서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라 하며 직사각형을 한 변을 기준으로 한 바퀴 돌려 만들 수 있음을 알기',ARRAY['6수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C2','math',6,2,'u6',3,'원기둥의 구성 요소 — 서로 평행하고 합동인 두 원(밑면 2개), 두 밑면과 만나는 굽은 면(옆면), 두 밑면 사이의 거리(높이)를 알고 높이는 밑면에 수직으로 재기',ARRAY['6수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C3','math',6,2,'u6',4,'원기둥의 전개도 — 합동인 원 2개와 직사각형 1개로 이루어지고, 옆면의 가로는 밑면의 둘레((지름) × (원주율)), 세로는 원기둥의 높이와 같음을 알고 길이 구하기',ARRAY['6수03-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C4','math',6,2,'u6',5,'원기둥의 전개도 가려내기 — 옆면이 직사각형이고, 두 밑면이 서로 합동인 원이며, 옆면을 사이에 두고 마주 보는 위치에 있어야 전개도가 됨을 알기',ARRAY['6수03-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C5','math',6,2,'u6',6,'원뿔의 뜻 — 한 원을 면으로 하는 입체도형을 원뿔이라 하고, 직각삼각형을 직각을 낀 한 변을 기준으로 한 바퀴 돌려 만들 수 있으며 원기둥·각뿔과 구별하기',ARRAY['6수03-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C6','math',6,2,'u6',7,'원뿔의 구성 요소 — 밑면(1개)·옆면·원뿔의 꼭짓점·모선(꼭짓점과 밑면 둘레의 한 점을 이은 선분, 무수히 많고 길이가 같음)·높이(꼭짓점에서 밑면에 수직으로 내린 선분의 길이)를 알고 모선이 높이보다 긺을 알기',ARRAY['6수03-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C7','math',6,2,'u6',8,'구 — 반원을 지름을 기준으로 한 바퀴 돌려 만든 입체도형을 구라 하고, 구의 중심(1개)·구의 반지름(무수히 많고 길이가 같음)을 알며 원기둥·원뿔·구를 위·앞·옆에서 본 모양을 견주기',ARRAY['6수03-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C8','math',6,2,'u6',9,'앞에서 본 모양 — 원뿔은 삼각형(밑변 = 밑면의 지름, 높이 = 원뿔의 높이), 원기둥은 직사각형(가로 = 밑면의 지름, 세로 = 높이)임을 알고 넓이·둘레를 구하거나 넓이로 모르는 길이를 되짚기',ARRAY['6수03-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X01','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'각기둥·각뿔과 원기둥·원뿔을 혼동한다(밑면이 다각형인지 원인지 보지 않는다)','밑면이 원인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X02','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C4']::text[],'원기둥의 두 원이 서로 평행하고 합동이어야 한다는 조건 가운데 하나를 빠뜨린다','평행하고 합동인 두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X03','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5','M6-2-u6-C7']::text[],'한 바퀴 돌려 만드는 평면도형을 혼동한다(직사각형→원기둥, 직각삼각형→원뿔, 반원→구)','무엇을 돌렸나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X04','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'돌릴 때 막대에 붙인 변과 뻗어 나간 변의 역할(높이·밑면의 반지름)을 바꾸거나 반지름을 지름으로 본다','뻗은 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X05','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6']::text[],'밑면을 「밑에 있는 면」으로만 보거나 원기둥(2개)·원뿔(1개)의 밑면 수를 혼동한다','원기둥 2개, 원뿔 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X06','math',6,'u6',ARRAY['M6-2-u6-C2']::text[],'원기둥의 높이를 비스듬히 재거나 밑면의 지름·옆면의 둘레와 혼동한다','밑면에 수직으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X07','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6','M6-2-u6-C7']::text[],'원기둥·구에 꼭짓점·모서리가 있다고 보거나 원뿔의 꼭짓점 수를 잘못 센다','굽은 면엔 모서리가 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X08','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로를 밑면의 지름이나 (반지름) × (원주율)로 본다','가로 = 밑면의 둘레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X09','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로와 세로가 원기둥의 어디와 같은지 바꾸어 본다','세로 = 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X10','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'옆면의 가로로 밑면의 지름·반지름을 구할 때 곱셈·나눗셈을 거꾸로 하거나 반지름과 지름을 혼동한다','가로 ÷ 3.14 = 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X11','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'옆면이 직사각형이 아닌(기울어진) 그림도 원기둥의 전개도라고 본다','옆면은 직사각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X12','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'두 밑면이 옆면의 같은 쪽에 있어 접으면 겹치는 것을 알아차리지 못한다','마주 보는 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X13','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C4']::text[],'전개도의 밑면을 원 1개로, 또는 옆면을 원·삼각형으로 생각한다','원 2개 + 직사각형 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X14','math',6,'u6',ARRAY['M6-2-u6-C5','M6-2-u6-C6']::text[],'원기둥과 원뿔을 혼동한다(원이 두 개인지 한 개인지, 뾰족한 점이 있는지 보지 않는다)','원 하나·뾰족한 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X15','math',6,'u6',ARRAY['M6-2-u6-C6','M6-2-u6-C8']::text[],'원뿔의 모선과 높이를 혼동한다(모선을 높이로 쓰거나 높이가 모선보다 길다고 본다)','모선은 비스듬히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X16','math',6,'u6',ARRAY['M6-2-u6-C6']::text[],'원뿔의 모선이 하나뿐이라고 보거나 모선마다 길이가 다르다고 본다','모선은 무수히, 길이는 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X17','math',6,'u6',ARRAY['M6-2-u6-C7']::text[],'구의 반지름이 방향마다 다르다고 보거나 구의 중심이 여러 개라고 본다','중심 1개, 반지름은 모두 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X18','math',6,'u6',ARRAY['M6-2-u6-C7','M6-2-u6-C8']::text[],'원기둥·원뿔·구를 위·앞·옆에서 본 모양을 혼동한다','위에서는 모두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X19','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C3','M6-2-u6-C4','M6-2-u6-C5','M6-2-u6-C6','M6-2-u6-C7','M6-2-u6-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 아닌↔맞는','물음의 「잘못·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X20','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C8']::text[],'앞모양 넓이에서 삼각형의 ÷ 2를 빠뜨리거나 밑변을 반지름으로 두는 등 넓이·길이 계산을 잘못한다','삼각형은 ÷ 2') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#1','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','원기둥은 어떤 입체도형인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"원기둥은 어떤 입체도형인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","correct":true},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X01"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X03"},{"t":"한 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["원기둥의 뜻을 떠올려요.","원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."],"variant_rule":{"alt":[{"stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]},{"stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"원기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 각기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#2','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."],"variant_rule":{"alt":[{"stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."]},{"stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#3','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'sa','auto','사각기둥의 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":1,"kind":"sa","stem":"사각기둥의 면은 모두 몇 개인가요?","answer":["6"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 사각형이에요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"variant_rule":{"alt":[{"stem":"삼각기둥의 모서리는 모두 몇 개인가요?","answer":["9"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 삼각형이에요.","한 밑면의 변 3개가 위아래로 두 번, 옆 모서리가 3개 — 3 × 3 = 9개예요."]},{"stem":"오각기둥의 꼭짓점은 모두 몇 개인가요?","answer":["10"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 오각형이에요.","한 밑면의 꼭짓점 5개가 위아래로 두 번 — 5 × 2 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#4','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'sa','auto','사각뿔의 꼭짓점은 모두 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"sa","stem":"사각뿔의 꼭짓점은 모두 몇 개인가요?","answer":["5"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 사각형이에요.","밑면의 꼭짓점 4개와 각뿔의 꼭짓점 1개 — 4 + 1 = 5개예요."],"variant_rule":{"alt":[{"stem":"삼각뿔의 면은 모두 몇 개인가요?","answer":["4"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 삼각형이에요.","밑면 1개와 옆면 3개 — 3 + 1 = 4개예요."]},{"stem":"오각뿔의 모서리는 모두 몇 개인가요?","answer":["10"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 오각형이에요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#5','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."]},{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#6','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'sa','auto','가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 3 × 2 = 6 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 세로 7 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]},{"stem":"가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#7','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X06']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에서 뻗어 나간 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"밑면의 반지름","correct":true},{"t":"높이","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]},{"stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#8','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'ox','auto','원기둥의 두 원은 서로 평행하고 합동이에요.',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":2,"kind":"ox","stem":"원기둥의 두 원은 서로 평행하고 합동이에요.","answer":"O","reason_options":[{"t":"원기둥은 서로 평행하고 합동인 두 원을 면으로 하기 때문에","correct":true},{"t":"원기둥의 두 원은 크기가 달라도 되기 때문에","mis":"M6-2-u6-X02"}],"mis":"M6-2-u6-X02","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"두 면이 원이면 모두 원기둥이에요.","answer":"X","reason_options":[{"t":"두 원이 서로 평행하고 합동이어야 원기둥이기 때문에","correct":true},{"t":"원이 두 개 있으면 원기둥이라고 정했기 때문에","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]},{"stem":"밑면이 원인 기둥 모양도 각기둥이라고 불러요.","answer":"X","reason_options":[{"t":"각기둥의 밑면은 다각형이고 원은 다각형이 아니기 때문에","correct":true},{"t":"기둥 모양은 모두 각기둥이기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#9','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'sa','auto','가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 라 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 — 이 가운데 원기둥 모양은 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 라 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["2"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 라예요.","모두 2개예요."],"mis":"M6-2-u6-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 북 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["1"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가예요.","모두 1개예요."]},{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 다 서로 평행하고 합동인 두 원을 면으로 하는 북 · 라 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["3"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 나, 다예요.","모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#10','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',3,'mc','auto','다음 가운데 원기둥 모양은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X01']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄","correct":true},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"두 원이 비스듬히 잘려 평행하지 않은 통","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄」이 원기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔","correct":true},{"t":"두 원이 비스듬히 잘려 평행하지 않은 통","mis":"M6-2-u6-X02"},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔」이 원기둥이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 북","correct":true},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"},{"t":"한 원을 면으로 하고 뾰족한 점이 있는 고깔모자","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 북」이 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#1','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'sa','auto','가로 4 cm, 세로 10 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 10 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["막대에 붙인 세로 10 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 4 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 3 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?","answer":["3"],"explanation":["막대에 붙인 세로 3 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 7 cm는 밑면의 반지름이 돼요.","그래서 높이는 3 cm예요."]},{"stem":"가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 세로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#2','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'sa','auto','육각기둥의 모서리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"육각기둥의 모서리는 모두 몇 개인가요?","answer":["18"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 육각형이에요.","한 밑면의 변 6개가 위아래로 두 번, 옆 모서리가 6개 — 6 × 3 = 18개예요."],"variant_rule":{"alt":[{"stem":"칠각기둥의 면은 모두 몇 개인가요?","answer":["9"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 칠각형이에요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]},{"stem":"팔각뿔의 모서리는 모두 몇 개인가요?","answer":["16"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 팔각형이에요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#3','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'error','auto','원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":3,"kind":"error","stem":"원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"순달 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"지석 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"나린 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#4','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"직사각형을 한 바퀴","r":"원기둥"},{"l":"직각삼각형을 한 바퀴","r":"원뿔"},{"l":"반원을 한 바퀴","r":"구"}],"mis":"M6-2-u6-X03","explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"막대에 붙인 변","r":"높이"},{"l":"뻗어 나간 변","r":"밑면의 반지름"},{"l":"뻗어 나간 변의 2배","r":"밑면의 지름"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"두 면이 평행하고 합동인 다각형","r":"각기둥"},{"l":"두 면이 평행하고 합동인 원","r":"원기둥"},{"l":"한 원을 면으로 하는 뿔","r":"원뿔"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#5','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'ox','auto','직사각형을 한 변을 기준으로 한 바퀴 돌리면 원기둥이 돼요.',ARRAY['M6-2-u6-X03']::text[],true,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":3,"kind":"ox","stem":"직사각형을 한 변을 기준으로 한 바퀴 돌리면 원기둥이 돼요.","answer":"O","reason_options":[{"t":"돌린 변은 높이, 뻗은 변은 밑면의 반지름이 되기 때문에","correct":true},{"t":"직사각형의 네 변이 모두 원이 되기 때문에","mis":"M6-2-u6-X03"}],"mis":"M6-2-u6-X03","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"직각삼각형을 한 바퀴 돌리면 원기둥이 돼요.","answer":"X","reason_options":[{"t":"직각삼각형을 돌리면 뾰족한 점이 생겨 원뿔이 되기 때문에","correct":true},{"t":"직각삼각형에도 직각이 있어 원기둥이 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]},{"stem":"원기둥과 각기둥은 모두 서로 평행하고 합동인 두 면이 있어요.","answer":"O","reason_options":[{"t":"두 밑면이 서로 평행하고 합동이라는 점이 같기 때문에","correct":true},{"t":"원기둥과 각기둥은 밑면의 모양까지 같기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#6','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'sa','auto','가로 6 cm, 세로 4 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":3,"kind":"sa","stem":"가로 6 cm, 세로 4 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 가로 6 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 9 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["막대에 붙인 가로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."]},{"stem":"가로 8 cm, 세로 3 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["14"],"explanation":["막대에 붙인 가로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름 6 cm와 높이 8 cm — 6 + 8 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#7','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'mc','auto','「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":3,"kind":"mc","stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."]},{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#8','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'sa','auto','가로 7 cm, 세로 12 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":4,"kind":"sa","stem":"가로 7 cm, 세로 12 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["26"],"explanation":["막대에 붙인 세로 12 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 7 cm는 밑면의 반지름이 돼요.","지름 14 cm와 높이 12 cm — 14 + 12 = 26 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["23"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","지름 18 cm와 높이 5 cm — 18 + 5 = 23 cm예요."]},{"stem":"가로 4 cm, 세로 15 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["23"],"explanation":["막대에 붙인 세로 15 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름 8 cm와 높이 15 cm — 8 + 15 = 23 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#9','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'sa','auto','가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 서로 평행하고 합동인 두 원을 면으로 하는 북 — 이 가운데 원기둥 모양은 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":4,"kind":"sa","stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 서로 평행하고 합동인 두 원을 면으로 하는 북 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["3"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 다, 마예요.","모두 3개예요."],"mis":"M6-2-u6-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 나 서로 평행하고 합동인 두 원을 면으로 하는 북 · 다 밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕 · 라 위쪽 원이 아래쪽 원보다 작은 컵 · 마 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["1"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 나예요.","모두 1개예요."]},{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 나 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 다 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 굽은 면으로만 둘러싸인 구슬 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["2"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 다예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#10','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'essay','teacher','간식을 담은 통 가운데 마주 보는 두 면이 모두 원인데 위쪽 원이 아래쪽 원보다 작은 통이 있어요. 이 통이 원기둥이 아닌 까닭을 원기둥의 뜻을 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"간식을 담은 통 가운데 마주 보는 두 면이 모두 원인데 위쪽 원이 아래쪽 원보다 작은 통이 있어요. 이 통이 원기둥이 아닌 까닭을 원기둥의 뜻을 써서 설명해 보세요.","answer_guide":{"answer":"예: 원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이다. 이 통은 두 면이 원이고 평행하지만, 위쪽 원이 더 작아 두 원이 합동이 아니므로 원기둥이 아니다.","scoring_points":["원기둥의 뜻(서로 평행하고 합동인 두 원)을 썼는가","두 원이 합동이 아님을 짚었는가","그래서 원기둥이 아니라고 결론지었는가"]},"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","위쪽 원이 더 작으면 두 원이 합동이 아니에요.","그래서 원기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#1','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#2','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]},{"stem":"밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#3','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','원기둥의 밑면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"원기둥의 밑면은 모두 몇 개인가요?","answer":["2"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 밑면은 서로 평행하고 합동인 두 원 — 2개예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥의 평평한 면은 모두 몇 개인가요?","answer":["2"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥에서 평평한 면은 두 밑면뿐 — 2개예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."]},{"stem":"원기둥의 옆면은 모두 몇 개인가요?","answer":["1"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 옆면은 굽은 면 하나예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#4','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥의 높이는 무엇인가요?',ARRAY['M6-2-u6-X06']::text[],true,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자와 삼각자를 밑면에 수직으로 대어 두 밑면 사이의 거리를 재요","correct":true},{"t":"밑면의 지름을 재요","mis":"M6-2-u6-X06"},{"t":"옆면을 따라 비스듬히 줄자를 대어 재요","mis":"M6-2-u6-X06"},{"t":"밑면의 둘레를 재요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]},{"stem":"원기둥의 높이를 비스듬히 재면 어떻게 되나요?","options":[{"t":"두 밑면 사이의 거리보다 길게 나와요","correct":true},{"t":"두 밑면 사이의 거리보다 짧게 나와요","mis":"M6-2-u6-X06"},{"t":"언제나 같은 값이 나와요","mis":"M6-2-u6-X06"},{"t":"밑면의 지름과 같아져요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#5','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["15"],"explanation":["밑면의 반지름은 6 ÷ 2 = 3 cm예요.","높이는 12 cm예요.","3 + 12 = 15 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm이고 높이가 7 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["12"],"explanation":["밑면의 반지름은 10 ÷ 2 = 5 cm예요.","높이는 7 cm예요.","5 + 7 = 12 cm예요."]},{"stem":"밑면의 지름이 8 cm이고 높이가 15 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["19"],"explanation":["밑면의 반지름은 8 ÷ 2 = 4 cm예요.","높이는 15 cm예요.","4 + 15 = 19 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#6','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["16"],"explanation":["밑면의 지름은 4 × 2 = 8 cm예요.","높이는 8 cm예요.","8 + 8 = 16 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 반지름이 5 cm이고 높이가 9 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["19"],"explanation":["밑면의 지름은 5 × 2 = 10 cm예요.","높이는 9 cm예요.","10 + 9 = 19 cm예요."]},{"stem":"밑면의 반지름이 3 cm이고 높이가 11 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["17"],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","높이는 11 cm예요.","6 + 11 = 17 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#7','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'ox','auto','원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.',ARRAY['M6-2-u6-X05']::text[],true,'{"seq":7,"concept":"M6-2-u6-C2","difficulty":2,"kind":"ox","stem":"원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.","answer":"X","reason_options":[{"t":"밑면은 「기본이 되는 면」 — 서로 평행하고 합동인 두 원 모두 밑면이기 때문에","correct":true},{"t":"밑면이라는 이름처럼 밑에 있는 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"mis":"M6-2-u6-X05","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 옆면은 굽은 면이에요.","answer":"O","reason_options":[{"t":"두 밑면과 만나는 면이 둥글게 굽어 있기 때문에","correct":true},{"t":"원기둥의 옆면은 직사각형 여러 개이기 때문에","mis":"M6-2-u6-X05"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]},{"stem":"원기둥의 높이는 밑면에 수직으로 재요.","answer":"O","reason_options":[{"t":"높이는 두 밑면 사이의 거리이기 때문에","correct":true},{"t":"비스듬히 재야 정확하기 때문에","mis":"M6-2-u6-X06"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#8','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'mc','auto','원기둥과 각기둥의 같은 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X07']::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 다른 점은 어느 것인가요?","options":[{"t":"밑면이 원기둥은 원, 각기둥은 다각형이에요","correct":true},{"t":"원기둥은 밑면이 1개, 각기둥은 2개예요","mis":"M6-2-u6-X05"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"},{"t":"원기둥은 두 밑면이 평행하지 않아요","mis":"M6-2-u6-X02"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?","options":[{"t":"모서리와 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#9','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'error','auto','원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X19']::text[],true,'{"seq":9,"concept":"M6-2-u6-C2","difficulty":2,"kind":"error","stem":"원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"순달 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"지석 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"나린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#10','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',3,'match','auto','원기둥에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C2","difficulty":3,"kind":"match","stem":"원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"서로 평행하고 합동인 두 원","r":"밑면"},{"l":"두 밑면과 만나는 굽은 면","r":"옆면"},{"l":"두 밑면 사이의 거리","r":"높이"}],"mis":"M6-2-u6-X05","explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥의 밑면의 수","r":"2개"},{"l":"원기둥의 옆면의 수","r":"1개"},{"l":"원기둥의 꼭짓점의 수","r":"0개"}],"explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"밑면","r":"원"},{"l":"옆면","r":"굽은 면"},{"l":"높이","r":"두 밑면 사이의 거리"}],"explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#1','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'sa','auto','밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 12 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["24"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","12 × 2 = 24 cm예요."]},{"stem":"밑면의 반지름이 15 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["30"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","15 × 2 = 30 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#2','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'mc','auto','원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06']::text[],true,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?","options":[{"t":"모서리와 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"원기둥과 각기둥의 다른 점은 어느 것인가요?","options":[{"t":"밑면이 원기둥은 원, 각기둥은 다각형이에요","correct":true},{"t":"원기둥은 밑면이 1개, 각기둥은 2개예요","mis":"M6-2-u6-X05"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"},{"t":"원기둥은 두 밑면이 평행하지 않아요","mis":"M6-2-u6-X02"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#3','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'ox','auto','원기둥을 눕혀 놓으면 밑면이 옆면이 돼요.',ARRAY['M6-2-u6-X05']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":3,"kind":"ox","stem":"원기둥을 눕혀 놓으면 밑면이 옆면이 돼요.","answer":"X","reason_options":[{"t":"놓는 방향과 상관없이 평행하고 합동인 두 원이 밑면이기 때문에","correct":true},{"t":"아래에 닿은 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"mis":"M6-2-u6-X05","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥에는 모서리가 없어요.","answer":"O","reason_options":[{"t":"평평한 면끼리 만나는 선분이 없기 때문에","correct":true},{"t":"원기둥의 모서리는 2개이기 때문에","mis":"M6-2-u6-X07"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]},{"stem":"원기둥의 높이는 밑면의 지름과 언제나 같아요.","answer":"X","reason_options":[{"t":"높이는 두 밑면 사이의 거리라 지름과 따로 정해지기 때문에","correct":true},{"t":"원기둥은 높이와 지름이 같은 도형이기 때문에","mis":"M6-2-u6-X06"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#4','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'error','auto','원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X19']::text[],true,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":3,"kind":"error","stem":"원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"하린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"도윤 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"민준 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 수아의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"나린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 가온의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"지석 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 민지의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
